window.QUESTIONS=[{"lv":1,"id":"c1-1","ch":1,"n":1,"q":"Điền vào chỗ trống: “Triết học là… về thế giới và vị trí con người, trong thế giới đó, là khoa học về sự vận động, phát triển chung nhất của tự nhiên, xã hội và tư duy”.","o":["Hệ thống quan điểm duy nhất.","Hệ thống lý luận về quan điểm.","Hệ thống lý luận chung nhất.","Hệ thống luận điểm duy nhất"],"a":2},{"lv":2,"id":"c1-2","ch":1,"n":2,"q":"Tư duy triết học bắt đầu từ đâu?","o":["Từ những lực lượng siêu nhiên ở bên ngoài chi phối nhận thức của con người.","Từ những cảm giác, nhận thức chủ quan của con người.","Từ các triết lý, từ sự khôn ngoan, từ tình yêu sự thông thái dần hình thành các hệ thống những tri thức chung nhất về thế giới.","Tất cả các phương án đều đúng."],"a":2},{"lv":3,"id":"c1-3","ch":1,"n":3,"q":"Trong lịch sử nhân loại, triết học xuất hiện khi tri thức của con người đã phát triển đến mức có khả năng khái quát các sự vật, hiện tượng thành những quan điểm chung về thế giới. Nếu vận dụng cách tiếp cận này để xem xét sự phát triển của trí tuệ nhân tạo hiện nay có thể tạo ra một hệ thống triết học mới hay không, nhận định nào sau đây là phù hợp nhất?","o":["Chỉ cần có nhiều dữ liệu là tất yếu hình thành một hệ thống triết học mới.","Sự phát triển của tri thức và tư duy khái quát là điều kiện nhận thức quan trọng, nhưng sự ra đời của triết học còn gắn với những điều kiện xã hội – lịch sử nhất định.","Mọi tiến bộ khoa học đều tự động chuyển hóa thành triết học bởi triết học là khoa học của mọi khoa học.","Triết học chỉ xuất hiện khi con người đã giải thích được toàn bộ thế giới."],"a":1},{"lv":1,"id":"c1-4","ch":1,"n":4,"q":"Điền vào chỗ trống: “… là khái niệm triết học dùng để chỉ hệ thống các tri thức, quan điểm, tình cảm, niềm tin, lý tưởng xác định về thế giới và vị trí con người trong thế giới đó”.","o":["Phương pháp luận.","Thế giới quan.","Chủ nghĩa duy vật.","Chủ nghĩa duy tâm."],"a":1},{"lv":2,"id":"c1-5","ch":1,"n":5,"q":"Thế giới quan có thể được hiểu một cách ngắn gọn là:","o":["Hệ thống quan điểm của con người về thế giới.","Bức tranh chung về thế giới.","Cảm nhận về thế giới","Nhận thức chung về cuộc đời"],"a":0},{"lv":1,"id":"c1-6","ch":1,"n":6,"q":"Thế giới quan quy định điều gì trong việc định hướng nhận thức và hoạt động thực tiễn của con người?","o":["Các nguyên tắc, thái độ, giá trị.","Các nguyên nhân, mức độ và giá trị.","Điều kiện, nền tảng và cách thức.","Điều kiện, giá trị và điều lệ."],"a":0},{"lv":2,"id":"c1-7","ch":1,"n":7,"q":"Sự hình thành các trường phái khác nhau trong triết học xuất phát từ sự khác biệt về:","o":["Trình độ tư duy.","Giai cấp.","Thế giới quan.","Vị trí địa lý."],"a":2},{"lv":2,"id":"c1-8","ch":1,"n":8,"q":"Thế giới quan đúng đắn là một thế giới quan như thế nào?","o":["Thế giới quan phù hợp với cách nghĩ của chủ thể nhận thức.","Thế giới quan phù hợp với tâm lý chung của xã hội.","Thế giới quan đúng với đạo đức xã hội.","Thế giới quan phù hợp với hiện thực khách quan."],"a":3},{"lv":2,"id":"c1-9","ch":1,"n":9,"q":"Thế giới quan và nhân sinh quan có mối quan hệ như thế nào?","o":["Thế giới quan bao hàm cả nhân sinh quan.","Thế giới quan đối lập với nhân sinh quan.","Thế giới quan xuất không có mối liên hệ với nhân sinh quan.","Thế giới quan là một phần của nhân sinh quan."],"a":0},{"lv":1,"id":"c1-10","ch":1,"n":10,"q":"Triết học có vai trò như thế nào đối với thế giới quan?","o":["Là linh hồn của thế giới quan.","Là nguyên nhân – lý luận của thế giới quan.","Là hạt nhân – lý luận của thế giới quan.","Là vấn đề cơ bản của thế giới quan"],"a":2},{"lv":2,"id":"c1-11","ch":1,"n":11,"q":"Triết học là hạt nhân của thế giới quan được hiểu là:","o":["Triết học có chức năng xây dựng thế giới quan.","Thế giới quan là một giai đoạn phát triển cao của triết học.","Không thể xuất hiện thế giới quan nào nếu không có triết học.","Thế giới quan bao trùm cả triết học."],"a":0},{"lv":2,"id":"c1-12","ch":1,"n":12,"q":"Mối quan hệ giữa tư duy và tồn tại là muốn nói đến mối quan hệ giữa hai yếu tố nào?","o":["Những vấn đề không tồn tại và những vấn đề đang tồn tại.","Ý thức và sự tồn vong.","Ý thức và vật chất.","Thế giới ảo và thế giới thực."],"a":2},{"lv":1,"id":"c1-13","ch":1,"n":13,"q":"Hai mặt trong vấn đề cơ bản của triết học là:","o":["Khả tri luận và bất khả tri luận.","Nhị nguyên luận và nhất nguyên luận.","Hoài nghi luận và ý thức luận.","Bản thể luận và nhận thức luận."],"a":3},{"lv":2,"id":"c1-14","ch":1,"n":14,"q":"Bản thể luận trong vấn đề cơ bản của triết học được hiểu là:","o":["Bàn luận về bản chất con người.","Bàn về bản chất của triết học","Bàn về yếu tố đầu tiên hình thành và quyết định thế giới.","Bàn về thể thức nghiên cứu của triết học."],"a":2},{"lv":2,"id":"c1-15","ch":1,"n":15,"q":"Mặt bản thể luận trong vấn đề cơ bản của triết học giải quyết nội dung gì?","o":["Mối quan hệ giữa con người với thế giới.","Mối quan hệ giữa vật chất và ý thức.","Mối quan hệ giữa bản chất và hiện tượng.","Mối quan hệ giữa thực thể tự nhiên và thực thể xã hội."],"a":1},{"lv":2,"id":"c1-16","ch":1,"n":16,"q":"Mặt nhận thức luận trong vấn đề cơ bản của triết học giải quyết nội dung gì?","o":["Luận giải về nguồn gốc của ý thức.","Xem xét khả năng tư duy trừu tượng của con người về bản thân mình.","Khả năng nhận thức của con người về thế giới.","Bàn luận về nguồn gốc của thế giới."],"a":2},{"lv":2,"id":"c1-17","ch":1,"n":17,"q":"Việc giải quyết vấn đề cơ bản có ảnh hưởng như thế nào đến sự phát triển của triết học?","o":["Cơ bản giải quyết xong mọi vấn đề của triết học.","Bàn luận những vấn đề của khoa học cơ bản trong triết học.","Giải quyết tranh cãi xem vật chất có trước hay có sau.","Tạo tiền tề cho việc hình thành các trường phái triết học."],"a":3},{"lv":1,"id":"c1-18","ch":1,"n":18,"q":"Chủ nghĩa duy tâm có những trường phái nào?","o":["Duy tâm thần bí và duy tầm siêu hình.","Duy tâm khách quan và duy tâm chủ quan.","Duy tâm biện chứng và duy tâm siêu hình.","Duy tâm thần thánh và duy tâm con người."],"a":1},{"lv":3,"id":"c1-19","ch":1,"n":19,"q":"Quan niệm: “Sống chết có mệnh, giàu sang do trời” của Khổng Tử phản ánh thế giới quan của trường phái triết học nào?","o":["Duy tâm chủ quan.","Duy tâm khách quan.","Duy vật siêu hình.","Duy vật cổ đại."],"a":1},{"lv":2,"id":"c1-20","ch":1,"n":20,"q":"Câu nói “\"Vẻ đẹp không nằm ở đôi má hồng của người thiếu nữ mà ở trong mắt của kẻ si tình\"” phản ánh quan điểm của trường phái triết học nào?","o":["Trường phái duy tâm chủ quan.","Trường phái duy tâm khách quan.","Trường phái duy vật siêu hình.","Trường phái duy vật biện chứng"],"a":0},{"lv":1,"id":"c1-21","ch":1,"n":21,"q":"Chủ nghĩa duy vật có những trường phái nào?","o":["Duy vật siêu hình và duy vật biện chứng.","Duy vật chất phác và duy vật siêu hình.","Duy vật chất phác thời cổ đại, duy vật siêu hình và duy vật biện chứng.","Duy vật chất phác và duy vật biện chứng."],"a":2},{"lv":2,"id":"c1-22","ch":1,"n":22,"q":"Chủ nghĩa duy vật lịch sử là kết quả của hoạt động nào?","o":["Nghiên cứu sự phát triển của chủ nghĩa duy vật trong lịch sử.","Nghiên cứu những quan điểm duy vật trong lịch sử.","Vận dụng và mở rộng quan điểm duy vật biện chứng vào nghiên cứu lịch sử xã hội.","Vận dụng lịch sử trong việc nghiên cứu những vấn đề triết học duy vật."],"a":2},{"lv":3,"id":"c1-23","ch":1,"n":23,"q":"Câu thành ngữ “Phú quý sinh lễ nghĩa” phản ánh quan điểm của trường phái triết học nào?","o":["Chủ nghĩa duy vật.","Chủ nghĩa duy tâm.","Nhị nguyên luận.","Không thuộc trường phái nào."],"a":0},{"lv":2,"id":"c1-24","ch":1,"n":24,"q":"Chủ nghĩa duy tâm giải quyết mặt bản thể luận trong vấn đề cơ bản của triết học như thế nào?","o":["Vật chất và ý thức sinh ra đồng thời và nương tựa vào nhau biến đổi.","Thế giới tinh thần có trước và quyết định sự tồn tại của thế giới vật chất.","Thế giới tinh thần là sản phẩm của các yếu tố vật chất.","Thế giới tinh thần là thế giới duy nhất tồn tại vĩnh hằng."],"a":1},{"lv":2,"id":"c1-25","ch":1,"n":25,"q":"Chủ nghĩa duy vật giải quyết mặt bản thể luận trong vấn đề cơ bản của triết học như thế nào?","o":["Vật chất là cái có trước, vật chất quyết định ý thức.","Thế giới tinh thần có trước và quyết định sự tồn tại của thế giới vật chất.","Vật chất và ý thức sinh ra đồng thời và nương tựa vào nhau biến đổi.","Thế giới tinh thần là thế giới duy nhất tồn tại vĩnh hằng."],"a":0},{"lv":4,"id":"c1-26","ch":1,"n":26,"q":"Do con người không thể nhận thức được tất cả các sự vật, hiện tượng trong vũ trụ rộng lớn, nên việc giải quyết mặt bản thể luận trong vấn đề cơ bản của triết học cần theo hướng nào?","o":["Cần phải làm rõ vật chất và ý thức cái nào có trước, cái nào có sau để tiếp tục nghiên cứu về thế giới.","Thừa nhận vật chất và ý thức đều cùng xuất hiện và chi phối lẫn nhau vì thực tế là như vậy.","Không cần xác định vật chất hay ý thức có trước hay có sau, chỉ cần thừa nhận sự tồn tại của nó trong thế giới và tiếp tục nghiên cứu.","Xác định một cách tương đối, nếu như có những phát hiện mới về vật chất và ý thức thì xác định lại."],"a":0},{"lv":2,"id":"c1-27","ch":1,"n":27,"q":"Nhận định nào đúng về khả năng nhận thức của con người đối với thế giới khách quan?","o":["Con người không thể nhận thức được thế giới khách quan.","Con người có thể nhận thức đầy đủ về thế giới khách quan.","Con người hiện tại chưa thể nhận thức được thế giới khách quan.","Con người hoàn toàn nhận thức được thế giới khách quan nhưng sẽ không đầy đủ."],"a":3},{"lv":2,"id":"c1-28","ch":1,"n":28,"q":"“Thế giới rộng lớn và phức tạp, con người không thể nào nhận thức được hết, vì vậy nhận thức là bất khả thi.”. Quan điểm trên thuộc lập trường nào về mặt nhận thức luận trong triết học?","o":["Duy tâm khách quan.","Thuyết bất khả tri.","Duy vật biện chứng.","Thuyết khả tri"],"a":1},{"lv":3,"id":"c1-29","ch":1,"n":29,"q":"Câu thành ngữ “Ếch ngồi đáy giếng, coi trời bằng vung” thể hiện vấn đề gì về thế giới quan?","o":["Người có nhận thức sai lầm.","Người có nhận thức lệch lạc.","Người ít hiểu biết, kiến thức nông cạn do điều kiện tiếp xúc hạn hẹp; người ngông nghênh, tự phụ, phiến diện.","Người có nhận thức cảm tính."],"a":2},{"lv":1,"id":"c1-30","ch":1,"n":30,"q":"Trong triết học, có hai phương pháp tư duy chung nhất đối lập nhau đó là:","o":["Phương pháp quy nạp và phương pháp diễn dịch.","Phương pháp chứng minh và phương pháp phản chứng.","Phương pháp trừu tượng và phương pháp cụ thể.","Phương pháp biện chứng và phương pháp siêu hình."],"a":3},{"lv":2,"id":"c1-31","ch":1,"n":31,"q":"Câu nói “Chỉ thấy cây mà không thấy rừng” cho thấy phương pháp tư duy nào trong triết học?","o":["Tư duy biện chứng.","Tư duy siêu hình.","Tư duy trừu tượng.","Tư duy độc lập."],"a":1},{"lv":2,"id":"c1-32","ch":1,"n":32,"q":"Câu nói “Không ai tắm hai lần trên một dòng sông” cho thấy phương pháp tư duy nào trong triết học?","o":["Tư duy biện chứng.","Tư duy siêu hình.","Tư duy trừu tượng.","Tư duy độc lập."],"a":0},{"lv":2,"id":"c1-33","ch":1,"n":33,"q":"Khi vận dụng, phương pháp tư duy biện chứng sẽ ưu việt hơn phương pháp tư duy siêu hình ở điểm nào?","o":["Có cái nhìn một chiều, sâu sắc hơn.","Có cái nhìn đa chiều, đầy đủ hơn.","Đầy đủ chứng cứ hơn.","Tính phản biện cao hơn."],"a":1},{"lv":3,"id":"c1-34","ch":1,"n":34,"q":"Người học cần vận dụng phương pháp tư duy nào trong triết học Mác – Lênin để có thể đánh giá sự vật, hiện tượng hoặc hành động đúng đắn, khách quan và khoa học?","o":["Tư duy trừu tượng.","Phương pháp tư duy siêu hình.","Tư duy phiến diện.","Phương pháp tư duy biện chứng."],"a":3},{"lv":3,"id":"c1-35","ch":1,"n":35,"q":"Ông cha ta có câu: “Không thầy đố mày làm nên”, đồng thời lại có câu “Học thầy không tày học bạn” điều này thể hiện tư duy gì của người Việt Nam?","o":["Siêu hình, tuyệt đối hóa một chiều.","Biện chứng.","Duy tâm.","Duy vật."],"a":1},{"lv":1,"id":"c1-36","ch":1,"n":36,"q":"Các hình thức cơ bản của phép biện chứng trong lịch sử là:","o":["Phép biện chứng tự phát, phép biện chứng duy tâm và phép biện chứng duy vật.","Phép biện chứng tự nhiên, phép biện chứng xã hội và phép biện chứng tư duy.","Phép biện chứng khách quan, phép biện chứng chủ quan và phép biện chứng duy ý chí.","Phép biện chứng toàn diện, phép biện chứng cụ thể và phép biện chứng lịch sử."],"a":0},{"lv":3,"id":"c1-37","ch":1,"n":37,"q":"Trong quá trình nghiên cứu khoa học, một giả thuyết mới được chấp nhận không phải vì nó phù hợp với mong muốn chủ quan của nhà nghiên cứu mà phải được kiểm nghiệm bằng thực tiễn và bằng chứng khách quan. Cách tiếp cận này gần nhất với lập trường nào?","o":["Chủ nghĩa duy tâm chủ quan, vì tri thức khoa học vẫn được hình thành thông qua hoạt động ý thức của con người.","Chủ nghĩa duy vật, vì thừa nhận hiện thực khách quan là cơ sở để kiểm nghiệm và điều chỉnh nhận thức.","Chủ nghĩa duy tâm khách quan, vì các quy luật khoa học tồn tại độc lập với ý thức cá nhân.","Nhị nguyên luận, vì hoạt động khoa học luôn đồng thời phụ thuộc vào cả vật chất và ý thức như hai bản nguyên ngang nhau."],"a":1},{"lv":3,"id":"c1-38","ch":1,"n":38,"q":"Khi đánh giá biến đổi khí hậu, có quan điểm cho rằng chỉ cần xử lý một nguồn phát thải riêng lẻ là có thể giải quyết toàn bộ vấn đề, không cần quan tâm đến năng lượng, giao thông, sản xuất, tiêu dùng và chính sách quốc tế. Cách tiếp cận này có hạn chế gì?","o":["Quá chú trọng vào mối liên hệ giữa các sự vật","Là biểu hiện của chủ nghĩa duy vật biện chứng vì tập trung vào phân tích nguyên nhân cụ thể khi giải quyết từng trường hợp.","Thể hiện đầy đủ quan điểm phát triển khi xem xét vấn đề.","Có biểu hiện xem xét sự vật cô lập, tách rời, phiến diện, gần với phương pháp siêu hình."],"a":3},{"lv":4,"id":"c1-39","ch":1,"n":39,"q":"Sự khác nhau cơ bản giữa chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật siêu hình được thể hiện rõ nhất ở cách giải thích nào về sự biến đổi của sự vật?","o":["Chủ nghĩa duy vật biện chứng thừa nhận sự vật biến đổi do tác động bên ngoài, còn chủ nghĩa duy vật siêu hình nhấn mạnh nguyên nhân bên trong.","Chủ nghĩa duy vật biện chứng xem sự vật trong mối liên hệ, vận động và mâu thuẫn nội tại; chủ nghĩa duy vật siêu hình thường xem xét sự vật cô lập và tương đối tĩnh tại.","Chủ nghĩa duy vật biện chứng phủ nhận tính ổn định của sự vật, còn chủ nghĩa duy vật siêu hình khẳng định mọi sự vật hoàn toàn bất biến.","Chủ nghĩa duy vật biện chứng chỉ nghiên cứu sự phát triển về chất, còn chủ nghĩa duy vật siêu hình chỉ nghiên cứu sự biến đổi về lượng."],"a":1},{"lv":5,"id":"c1-40","ch":1,"n":40,"q":"Đánh giá nào phù hợp nhất khi so sánh phương pháp siêu hình và phương pháp biện chứng trong nhận thức?","o":["Phương pháp siêu hình hoàn toàn vô giá trị trong mọi lĩnh vực khoa học.","Phương pháp biện chứng phủ nhận mọi hình thức phân tích sự vật trong trạng thái tương đối ổn định.","Phương pháp siêu hình có thể hữu ích trong những điều kiện nhất định nhưng bị hạn chế khi tuyệt đối hóa sự cô lập và bất biến của sự vật.","Hai phương pháp chỉ khác nhau về thuật ngữ, không khác nhau về cách nhận thức."],"a":2},{"lv":3,"id":"c1-41","ch":1,"n":41,"q":"Trong quá trình phát triển của các nền văn minh cổ đại, tri thức của con người dần vượt khỏi những kinh nghiệm riêng lẻ về sản xuất, thiên nhiên và đời sống xã hội để hình thành khả năng khái quát các mối liên hệ và quy luật chung. Việc xuất hiện triết học trong điều kiện đó phản ánh sự vận động nào của nhận thức?","o":["Nhận thức chuyển từ việc tiếp nhận các hiện tượng riêng lẻ sang khả năng khái quát lý luận về những vấn đề chung của thế giới.","Nhận thức chuyển từ kinh nghiệm cảm tính sang việc giải thích thế giới chủ yếu bằng các niềm tin siêu nhiên có tính hệ thống.","Nhận thức đạt tới trình độ lý luận khi con người có thể thay thế hoàn toàn kinh nghiệm thực tiễn bằng tư duy trừu tượng.","Nhận thức triết học xuất hiện chủ yếu do con người đã tích lũy đủ số lượng tri thức, không phụ thuộc vào sự phát triển của năng lực tư duy khái quát."],"a":0},{"lv":3,"id":"c1-42","ch":1,"n":42,"q":"Sự hình thành các trung tâm văn minh cổ đại gắn với sự phát triển của sản xuất, phân công lao động xã hội, sự phân hóa giai cấp và sự tách biệt tương đối giữa lao động trí óc với lao động chân tay. Khi phân tích điều kiện này, theo anh (chị) nhận định nào sau đây là phù hợp nhất?","o":["Triết học ra đời chủ yếu vì tầng lớp trí thức có nhu cầu tách khỏi đời sống vật chất để theo đuổi nhận thức thuần túy.","Triết học xuất hiện trong điều kiện xã hội đã tạo ra cơ sở vật chất, sự phân công xã hội và lực lượng trí tuệ cần thiết cho tư duy lý luận.","Sự xuất hiện của giai cấp là nguyên nhân duy nhất quyết định sự ra đời của triết học, còn trình độ sản xuất chỉ có vai trò hỗ trợ.","Sự phát triển sản xuất tự nó tất yếu tạo ra triết học, bất kể xã hội có phân công lao động và sự phát triển của tư duy lý luận hay không."],"a":1},{"lv":3,"id":"c1-43","ch":1,"n":43,"q":"Trong quá trình hoạch định chính sách phát triển, việc đánh giá một vấn đề không chỉ dựa vào dữ liệu riêng lẻ mà còn phải xác định cách nhìn tổng thể về thế giới, con người và vị trí của con người trong các quan hệ xã hội. Điều này cho thấy vai trò nào sau đây của triết học?","o":["Triết học cung cấp toàn bộ tri thức chuyên ngành cần thiết để trực tiếp giải quyết mọi vấn đề thực tiễn.","Triết học có thể thay thế các khoa học cụ thể trong việc nghiên cứu từng lĩnh vực của đời sống.","Triết học giữ vai trò hạt nhân lý luận của thế giới quan, góp phần định hướng cách nhìn và phương thức nhận thức thế giới.","Triết học chủ yếu cung cấp các niềm tin và lý tưởng, còn tri thức khoa học cụ thể không có vai trò trong việc hình thành thế giới quan."],"a":2},{"lv":4,"id":"c1-44","ch":1,"n":44,"q":"Việc giải thích sự phát triển xã hội chỉ bằng “ý chí của các nhà lãnh đạo” hoặc “tư tưởng của một cá nhân” mà bỏ qua điều kiện kinh tế - xã hội phản ánh hạn chế nào sau đây?","o":["Tuyệt đối hóa vai trò của nhân tố chủ quan và xem nhẹ cơ sở khách quan của đời sống xã hội.","Nhấn mạnh đúng vai trò của ý thức nhưng chưa phân biệt được ý thức cá nhân với ý thức xã hội.","Vận dụng quan điểm duy vật lịch sử nhưng chưa đánh giá đầy đủ tác động của tư tưởng.","Phân tích mối quan hệ giữa điều kiện vật chất và ý thức nhưng ưu tiên quá mức yếu tố kinh tế."],"a":0},{"lv":4,"id":"c1-45","ch":1,"n":45,"q":"Đâu là sự đối lập đúng về nguồn gốc của sự vận động và thay đổi theo hai phương pháp?","o":["Siêu hình: nguồn gốc vận động nằm bên ngoài đối tượng; biện chứng: nguồn gốc vận động là sự đấu tranh của các mặt đối lập, của mâu thuẫn nội tại trong bản thân sự vật.","Siêu hình: nguồn gốc vận động là mâu thuẫn nội tại; biện chứng: nguồn gốc vận động nằm bên ngoài đối tượng.","Siêu hình: nguồn gốc vận động là sự đấu tranh của các mặt đối lập; biện chứng: nguồn gốc vận động là sự biến đổi về số lượng.","Siêu hình và biện chứng đều cho rằng nguồn gốc của vận động nằm bên ngoài đối tượng, nhưng khác nhau về mức độ vận động."],"a":0},{"lv":5,"id":"c1-46","ch":1,"n":46,"q":"Trước một hiện tượng xã hội phức tạp, theo thế giới quan duy vật biện chứng anh (chị) nên lựa chọn phương án nào?","o":["Ưu tiên giải thích hiện tượng bằng một nguyên nhân duy nhất để bảo đảm tính rõ ràng.","Phân tích các điều kiện vật chất, các mối liên hệ và sự tác động qua lại giữa nhiều yếu tố trong quá trình vận động.","Xem xét hiện tượng chủ yếu từ ý muốn và mục tiêu của các chủ thể tham gia.","Tập trung vào biểu hiện bên ngoài vì đó là căn cứ trực tiếp nhất để đánh giá sự vật."],"a":1},{"lv":5,"id":"c1-47","ch":1,"n":47,"q":"Từ nhận định của Ăngghen về phương pháp siêu hình là phương pháp “chỉ nhìn thấy cây mà không thấy rừng”, có thể đánh giá rằng hạn chế cơ bản nhất của phương pháp này là:","o":["Nhận thức các mặt đối lập với nhau có một ranh giới tuyệt đối, chưa thấy được sự lệ thuộc, ảnh hưởng, ràng buộc và quy định lẫn nhau của các mặt đối lập.","Nhận thức đối tượng ở trạng thái cô lập, tách rời đối tượng ra khỏi các quan hệ được xem xét, qua đó chưa nhận thức được đối tượng trong các mối liên hệ phổ biến vốn có của nó.","Nhận thức đối tượng ở trạng thái tĩnh, đồng nhất đối tượng với trạng thái tĩnh trước đó và chỉ thừa nhận sự biến đổi về số lượng, về các hiện tượng bề ngoài.","Coi nguyên nhân của sự biến đổi nằm bên ngoài đối tượng, do đó chưa nhận thức được sự đấu tranh của các mặt đối lập, của mâu thuẫn nội tại trong bản thân sự vật."],"a":1},{"lv":6,"id":"c1-48","ch":1,"n":48,"q":"Trong một bài tập nghiên cứu khoa học, sinh viên được yêu cầu đề xuất cách tiếp cận để nghiên cứu sự phát triển của một công nghệ mới. Phương án nào sau đây thể hiện sự sáng tạo dựa trên quan điểm biện chứng?","o":["Nhận thức công nghệ từ những đặc điểm cơ bản đang tồn tại, đồng thời theo dõi sự thay đổi của các đặc điểm đó qua quá trình vận động để xác định xu hướng phát triển của công nghệ.","Nhận thức công nghệ thông qua việc phân tích các thành phần cấu thành của nó, tách từng thành phần khỏi các quan hệ liên quan để xác định chính xác đặc điểm và vai trò của từng thành phần.","Nhận thức công nghệ trong các mối liên hệ phổ biến vốn có của nó, xem xét sự lệ thuộc, ảnh hưởng, ràng buộc, quy định giữa các thành phần, đồng thời phân tích quá trình vận động, biến đổi và sự đấu tranh của các mặt đối lập.","Nhận thức sự phát triển của công nghệ thông qua những biến đổi về số lượng của các thông số kỹ thuật, đồng thời xem xét những biến đổi của các hiện tượng bề ngoài để xác định mức độ phát triển."],"a":2},{"lv":6,"id":"c1-49","ch":1,"n":49,"q":"Một nhóm sinh viên Trường Đại học Kỹ thuật Công nghiệp được yêu cầu xây dựng một mô hình nghiên cứu nhằm giải thích sự thay đổi của một hệ thống kỹ thuật theo thời gian. Nhóm đưa ra bốn thiết kế. Thiết kế nào sáng tạo và phù hợp nhất với phương pháp biện chứng?","o":["Xây dựng mô hình từ trạng thái hiện tại của hệ thống, đồng thời xem xét những biến đổi của hệ thống qua các giai đoạn để xác định sự thay đổi của các đặc điểm cơ bản.","Xây dựng mô hình bằng cách phân tích các thành phần của hệ thống, xác định đặc điểm của từng thành phần, sau đó xem xét sự thay đổi của từng thành phần trong quá trình vận động.","Xây dựng mô hình nhận thức hệ thống trong các mối liên hệ phổ biến vốn có của nó, xem xét sự lệ thuộc, ảnh hưởng, ràng buộc, quy định giữa các thành phần; đồng thời phân tích sự vận động, biến đổi cả về lượng và chất và sự đấu tranh của các mặt đối lập.","Xây dựng mô hình dựa trên sự biến đổi của hệ thống theo thời gian, tập trung vào những thay đổi về số lượng và các hiện tượng bề ngoài, đồng thời xác định những tác động bên ngoài làm hệ thống thay đổi."],"a":2},{"lv":1,"id":"c1-50","ch":1,"n":50,"q":"Điền vào chỗ trống: “… là hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy – thế giới quan và phương pháp luận khoa học, cách mạng của giai cấp công nhân, nhân dân lao động và các lực lượng xã hội tiến bộ trong nhận thức và cải tạo thế giới”.","o":["Triết học.","Triết học hiện sinh.","Triết học cổ điển Anh","Triết học Mác – Lênin."],"a":3},{"lv":1,"id":"c1-51","ch":1,"n":51,"q":"Điền vào chỗ trống: “Triết học Mác – Lênin là hệ thống quan điểm … về tự nhiên, xã hội và tư duy – thế giới quan và phương pháp luận khoa học, cách mạng của giai cấp công nhân, nhân dân lao động và các lực lượng xã hội tiến bộ trong nhận thức và cải tạo thế giới”.","o":["Duy vật biện chứng.","Duy vật siêu hình.","Duy tâm khách quan.","Duy tâm chủ quan."],"a":0},{"lv":1,"id":"c1-52","ch":1,"n":52,"q":"Điền vào chỗ trống: “Triết học Mác – Lênin là hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy – thế giới quan và phương pháp luận khoa học, cách mạng của …và các lực lượng xã hội tiến bộ trong nhận thức và cải tạo thế giới”.","o":["Tầng lớp trí thức, tiểu tư sản.","Giai cấp tư sản và giới tinh hoa.","Tầng lớp quý tộc, vương giả.","Gai cấp công nhân, nhân dân lao động."],"a":3},{"lv":1,"id":"c1-53","ch":1,"n":53,"q":"Yếu tố nào không phải là điều kiện khách quan cho sự ra đời của triết học Mác - Lênin?","o":["Sự phát triển của phong trào công nhân.","Triết học cổ điển Đức.","Sự ra đời của nền đại công nghiệp.","Sự thay đổi lập trường triết học của C. Mác."],"a":3},{"lv":2,"id":"c1-54","ch":1,"n":54,"q":"Trong ba bộ phận cấu thành nên chủ nghĩa Mác - Lênin, bộ phận nào giữ vai trò là thế giới quan và phương pháp luận chung nhất?","o":["Triết học Mác – Lênin.","Kinh tế chính trị Mác – Lênin.","Chủ nghĩa xã hội khoa học.","Chủ nghĩa duy vật lịch sử."],"a":0},{"lv":2,"id":"c1-55","ch":1,"n":55,"q":"Những điều kiện và tiền đề cơ bản nào dẫn đến sự ra đời và phát triển của triết học Mác – Lênin?","o":["Sự phát triển của chủ nghĩa tư bản và phong trào công nhân; những tiền đề lý luận từ triết học cổ điển Đức, kinh tế chính trị học cổ điển Anh và chủ nghĩa xã hội không tưởng; các thành tựu khoa học tự nhiên thế kỷ XIX; đồng thời được phát triển qua thực tiễn cách mạng và sự đóng góp của Mác, Ăngghen và Lênin.","Chủ yếu do sự phát triển của triết học cổ điển Đức, còn các yếu tố kinh tế – xã hội và khoa học tự nhiên chỉ có vai trò thứ yếu.","Chủ yếu do sự phát triển của khoa học tự nhiên và kinh tế tư bản chủ nghĩa, không liên quan trực tiếp đến phong trào công nhân và các tiền đề lý luận.","Do sự kế thừa trực tiếp toàn bộ tư tưởng triết học, kinh tế và xã hội trước đó, kết hợp với sự phát triển của chủ nghĩa tư bản mà không cần điều kiện thực tiễn cách mạng."],"a":0},{"lv":2,"id":"c1-56","ch":1,"n":56,"q":"Phát kiến vĩ đại thiên tài của Mác trong lĩnh vực triết học là:","o":["Học thuyết giá trị thặng dư.","Chủ nghĩa duy vật lịch sử.","Sứ mệnh lịch sử của giai cấp công nhân.","Không có phát kiến thiên tài nào."],"a":1},{"lv":3,"id":"c1-57","ch":1,"n":57,"q":"Nhận định: “Triết học Mác – Lênin là cơ sở thế giới quan, phương pháp luận khoa học và cách mạng để phân tích xu hướng phát triển của xã hội” là dựa trên cơ sở nào?","o":["Triết học Mác – Lênin chỉ ra quy luật vận động và phát triển chung nhất của tự nhiên, xã hội và tư duy.","Triết học Mác – lênin là chìa khóa vạn năng, có thể dùng để giải quyết tất cả các vấn đề phát sinh trong đời sống xã hội.","Triết học Mác – Lênin có khả năng dự báo tương lai của xã hội loài người một cách chính xác.","Triết học Mác – Lênin là khoa học về việc hoạch định chính sách phát triển kinh tế - xã hội của loài người."],"a":0},{"lv":3,"id":"c1-58","ch":1,"n":58,"q":"Ý nghĩa lịch sử to lớn của triết học Mác – Lênin là gì?","o":["Là học thuyết triết học đầu tiên trong lịch sử nhân loại kết hợp được lý luận của ba nhà tư tưởng lỗi lạc của nhân loại.","Là học thuyết triết học đầu tiên trong lịch sử nhân loại đứng trên lập trường của người lao động.","Là học thuyết triết học đầu tiên trong lịch sử nhân loại nghiên cứu về mối quan hệ giữa vật chất và ý thức.","Là học thuyết triết học đầu tiên trong lịch sử nhân loại có chức năng xây dựng thế giới quan, phương pháp luận."],"a":1},{"lv":3,"id":"c1-59","ch":1,"n":59,"q":"Phát biểu nào sau đây thể hiện bản chất cách mạng của triết học Mác - Lênin?","o":["Triết học Mác - Lênin chỉ tập trung vào việc giải thích thế giới.","Triết học Mác - Lênin phục vụ lợi ích cho mọi giai cấp trong quá trình phát triển xã hội.","Triết học Mác - Lênin gắn liền với sự nghiệp giải phóng giai cấp, giải phóng dân tộc và giải phóng con người.","Triết học Mác - Lênin phủ nhận vai trò của thực tiễn cách mạng."],"a":2},{"lv":3,"id":"c1-60","ch":1,"n":60,"q":"Trong bối cảnh Cách mạng công nghiệp lần thứ tư, một quốc gia vừa phải tiếp thu thành tựu công nghệ toàn cầu, vừa phải bảo đảm năng lực tự chủ và lợi ích quốc gia. Theo phương pháp luận của triết học Mác – Lênin, cách tiếp cận nào dưới đây, anh (chị) cho là phù hợp nhất?","o":["Đóng cửa hoàn toàn để bảo đảm độc lập, chống lại những mâu thuẫn xã hội có thể xảy ra do tác động của toàn cầu hóa.","Phụ thuộc hoàn toàn vào công nghệ bên ngoài để tận dụng lợi ích toàn cầu hóa và hội nhập kinh tế quốc tế mang lại.","Từ chối công nghệ mới từ bên ngoài, tập trung phát triển các công nghệ do quốc gia đó tạo ra để tạo sức mạnh tự chủ.","Kết hợp phát huy nội lực với chủ động hội nhập, tiếp thu thành tựu bên ngoài trên cơ sở phù hợp với điều kiện cụ thể."],"a":3},{"lv":3,"id":"c1-61","ch":1,"n":61,"q":"Đại hội Đảng lần thứ XIV xác định khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số là những động lực quan trọng của mô hình tăng trưởng mới, đồng thời nhấn mạnh phát triển kinh tế số, kinh tế xanh và kinh tế tuần hoàn. Nếu vận dụng phương pháp luận duy vật biện chứng để phân tích định hướng này, nhận định nào phù hợp nhất?","o":["Chỉ cần phát triển công nghệ là có thể tự động tạo ra phát triển bền vững.","Kinh tế xanh và kinh tế số là hai xu hướng hoàn toàn đối lập nhau khó có thể dung hòa.","Công nghệ cần được đặt trong mối liên hệ với mô hình tăng trưởng, thể chế, nhân lực, môi trường và mục tiêu xã hội.","Phát triển công nghệ phải được tách khỏi các vấn đề xã hội để bảo đảm tính khách quan và có như vậy mới đạt hiệu quả cao."],"a":2},{"lv":3,"id":"c1-62","ch":1,"n":62,"q":"Qua 40 năm “Đổi mới”, Việt Nam vừa đạt được nhiều thành tựu vừa phải tiếp tục nhận diện những hạn chế, mâu thuẫn và vấn đề mới nảy sinh để điều chỉnh đường lối phát triển. Theo phương pháp luận của triết học Mác – Lênin, cách tiếp cận nào sau đây là phù hợp nhất?","o":["Chỉ tập trung vào thành tựu để khẳng định đường lối đề ra đã đúng và hoàn thiện.","Chỉ tập trung vào hạn chế để tìm ra cách thức, phương hướng giải quyết điểm nghẽn, khó khăn trong giai đoạn phát triển tiếp theo của đất nước.","Đánh giá khách quan cả thành tựu và hạn chế, phân tích mối liên hệ, nguyên nhân và điều kiện phát triển để tiếp tục bổ sung lý luận và chính sách.","Giữ nguyên mọi quan điểm đã có trong các kỳ đại hội của Đảng trước đó để bảo đảm tính ổn định của lý luận."],"a":2},{"lv":3,"id":"c1-63","ch":1,"n":63,"q":"Tại sao sinh viên cần phải học, học phần Triết học Mác - Lênin? Chọn đáp án đúng nhất trong các đáp án sau:","o":["Triết học Mác – Lênin là một học phần bắt buộc trong chương trình học, nếu không học tốt sẽ ảnh hưởng đến kết quả học tập và cơ hội việc làm.","Triết học Mác – Lênin là một học phần bắt buộc trong chương trình học, giúp cho sinh viên trang bị được thế giới quan và phương pháp luận khoa học, cách mạng.","Triết học rất khó, nếu học được nó sẽ khiến mọi người thán phục, vì không phải ai cũng học được triết học.","Triết học là khoa học của mọi khoa học."],"a":1},{"lv":3,"id":"c1-64","ch":1,"n":64,"q":"Để tiếp thu hiệu quả những tri thức của triết học nói chung và triết học Mác – Lênin nói riêng, sinh viên cần nhất điều gì?","o":["Khả năng ghi nhớ và khả năng học thuộc lòng thật tốt.","Tìm được tài liệu ngắn nhất, cô đọng nhất.","Bản thân phải có khả năng bẩm sinh về triết học hoặc có tư duy dị biệt.","Nghiên cứu, học tập, trải nghiệm thực tiễn phong phú và nền tảng kiến thức phổ thông vững chắc."],"a":3},{"lv":3,"id":"c1-65","ch":1,"n":65,"q":"Học triết học và những khoa học khác cần nắm vững nguyên tắc nào?","o":["Học liên tục không được ngắt quãng.","Học theo năng lực của bản thân.","Học tập lý luận gắn với vận dụng thực tiễn sinh động.","Cần có tâm lý tốt và ý chí sắt đá."],"a":2},{"lv":3,"id":"c1-66","ch":1,"n":66,"q":"Trong quá trình học tập và nghiên cứu kỹ thuật tại Trường Đại học Kỹ thuật Công nghiệp, sinh viên tiếp cận đồng thời kiến thức cơ khí, điện, tự động hóa và công nghệ thông tin. Việc sử dụng triết học Mác – Lênin để khái quát mối liên hệ giữa các lĩnh vực trên thể hiện yêu cầu nào?","o":["Tách biệt các lĩnh vực khoa học để bảo đảm tính chuyên môn hóa tuyệt đối.","Nhận thức các sự vật trong mối liên hệ và tác động qua lại với nhau.","Xem triết học có thể thay thế toàn bộ các khoa học chuyên ngành.","Chỉ sử dụng tri thức triết học khi kiến thức chuyên ngành không đủ để giải quyết vấn đề."],"a":1},{"lv":3,"id":"c1-67","ch":1,"n":67,"q":"Khi thực hiện một đề tài kỹ thuật, sinh viên thu thập số liệu thí nghiệm, kiểm tra sai số và đối chiếu với kết quả thực tế trước khi đưa ra kết luận. Cách làm này vận dụng trực tiếp quan điểm nào?","o":["Lấy suy luận lý luận làm căn cứ chủ yếu, không cần kiểm chứng thực nghiệm.","Xem kết quả nghiên cứu phụ thuộc chủ yếu vào ý muốn của người nghiên cứu.","Xuất phát từ hiện thực khách quan và kiểm nghiệm nhận thức bằng thực tiễn.","Chỉ dựa vào những kết luận đã được thừa nhận trong giáo trình."],"a":2},{"lv":3,"id":"c1-68","ch":1,"n":68,"q":"Một nhóm sinh viên triển khai dự án kỹ thuật nhưng không khảo sát nhu cầu thực tế, chỉ lựa chọn đề tài vì “đang là xu hướng”. Theo phương pháp luận duy vật biện chứng, hạn chế chính của cách làm này là:","o":["Chưa phát huy đầy đủ vai trò của tư duy sáng tạo.","Có nguy cơ tách hoạt động nhận thức và sáng tạo khỏi điều kiện thực tiễn.","Đã quá chú trọng đến vai trò của khoa học công nghệ.","Đã vận dụng quá nhiều dữ liệu khách quan vào quá trình nghiên cứu."],"a":1},{"lv":3,"id":"c1-69","ch":1,"n":69,"q":"Khi một thiết bị kỹ thuật liên tục phát sinh lỗi, nhóm sinh viên không chỉ thay thế linh kiện mà còn phân tích thiết kế, điều kiện vận hành, quy trình lắp ráp và dữ liệu sử dụng. Cách xử lý này vận dụng chủ yếu:","o":["Quan điểm toàn diện và quan điểm phát triển trong nhận thức sự vật.","Quan điểm cô lập sự vật để xác định một nguyên nhân duy nhất.","Phương pháp siêu hình nhằm phân chia hệ thống thành các bộ phận độc lập.","Quan điểm duy tâm vì coi trọng vai trò của hoạt động tư duy."],"a":0},{"lv":4,"id":"c1-70","ch":1,"n":70,"q":"Tại sao hiện nay việc bổ sung, phát triển lý luận của triết học Mác– Lênin là cấp thiết? Chọn đáp án sai trong các đáp án sau:","o":["Do mong muốn chủ quan của các nhà nghiên cứu lý luận.","Do đặc điểm thời đại: sự tương tác giữa cách mạng khoa học công nghệ và cách mạng xã hội đã tạo nên sự biến đổi rất năng động của đời sống xã hội.","Do sự khủng hoảng của chủ nghĩa xã hội làm cho yêu cầu phát triển triết học Mác – Lênin càng trở nên cấp bách.","Do sự phát triển lý luận triết học mácxít và đổi mới chủ nghĩa xã hội trong thực tiễn là một quá trình thống nhất."],"a":0},{"lv":4,"id":"c1-71","ch":1,"n":71,"q":"Thực chất và ý nghĩa cuộc cách mạng trong triết học do C. Mác và Ph. Ăngghen thực hiện?","o":["Khắc phục được hạn chế của các trường phái triết học trong lịch sử để xây dựng chủ nghĩa duy vật biện chứng.","Vận dụng và mở rộng quan điểm duy vật biện chứng vào nghiên cứu lịch sử xã hội, sáng tạo ra chủ nghĩa duy vật lịch sử.","Bổ sung những đặc tính mới vào triết học, sáng tạo ra triết học chân chính khoa học – triết học duy vật biện chứng.","Tất cả các đáp án đều đúng."],"a":3},{"lv":4,"id":"c1-72","ch":1,"n":72,"q":"Vai trò của triết học Mác – Lênin đối với sự nghiệp đổi mới theo định hướng xã hội chủ nghĩa ở Việt Nam?","o":["Là nền tảng, cơ sở cho quá trình đổi mới tư duy ở Việt Nam.","Góp phần tìm được lời giải đáp về con đường đi lên chủ nghĩa xã hội ở Việt Nam. Đồng thời, qua thực tiễn để bổ sung, phát triển tư duy lý luận về chủ nghĩa xã hội.","Giúp giải quyết những vấn đề đặt ra trong thực tiễn xây dựng chủ nghĩa xã hội và thực tiễn đổi mới của đất nước ta.","Tất cả các đáp án đều đúng."],"a":3},{"lv":4,"id":"c1-73","ch":1,"n":73,"q":"Đường lối cách mạng của Đảng Cộng sản Việt Nam là sự vận dụng sáng tạo của hệ thống lý luận nào vào điều kiện thực tiễn Việt Nam?","o":["Chủ nghĩa Mác – Lênin, được vận dụng phù hợp với những điều kiện lịch sử cụ thể của Việt Nam.","Chủ nghĩa Mác, chủ nghĩa Lênin và tư tưởng Hồ Chí Minh, được kết hợp nhằm xác định phương hướng phát triển kinh tế của Việt Nam.","Chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh, được vận dụng sáng tạo và phát triển phù hợp với thực tiễn cách mạng Việt Nam.","Chủ nghĩa Mác – Lênin và những thành tựu lý luận tiến bộ của nhân loại, được vận dụng trong quá trình hoạch định đường lối cách mạng."],"a":2},{"lv":4,"id":"c1-74","ch":1,"n":74,"q":"Trong bối cảnh toàn cầu hóa và cuộc Cách mạng công nghiệp lần thứ tư, triết học Mác – Lênin vẫn được khẳng định có vai trò quan trọng đối với sự nghiệp đổi mới ở Việt Nam. Theo anh (chị) nhận định nào dưới đây làm rõ bản chất của vai trò đó?","o":["Triết học Mác – Lênin cung cấp các giải pháp kỹ thuật để phát triển khoa học và công nghệ.","Triết học Mác – Lênin là cơ sở thế giới quan và phương pháp luận khoa học giúp nhận thức đúng xu hướng vận động của xã hội, từ đó định hướng xây dựng đường lối và chính sách phù hợp.","Triết học Mác – Lênin thay thế toàn bộ các ngành khoa học xã hội trong việc hoạch định chính sách.","Triết học Mác Lênin chỉ có giá trị trong nghiên cứu lịch sử tư tưởng."],"a":1},{"lv":4,"id":"c1-75","ch":1,"n":75,"q":"Công cuộc Đổi mới ở Việt Nam cho thấy việc vận dụng triết học Mác – Lênin vào thực tiễn không thể chỉ dừng ở việc lặp lại các kết luận có sẵn. Phân tích nào sau đây làm rõ nhất yêu cầu đó?","o":["Lý luận phải được giữ nguyên để bảo đảm tính ổn định, còn thực tiễn cần điều chỉnh theo lý luận.","Thực tiễn có thể thay thế hoàn toàn lý luận trong quá trình hoạch định đường lối phát triển.","Cần xuất phát từ điều kiện thực tiễn, nhận thức quy luật khách quan, tổng kết kinh nghiệm và phát triển lý luận phù hợp với yêu cầu lịch sử cụ thể.","Chỉ cần thay đổi phương thức tổ chức thực hiện mà không cần đổi mới tư duy lý luận."],"a":2},{"lv":4,"id":"c1-76","ch":1,"n":76,"q":"Trong nội dung giáo trình Triết học Mác – Lênin có viết: “Trong những năm đầu của công cuộc đổi mới, việc giải quyết vấn đề kinh tế - xã hội còn gặp không ít khó khăn do quan điểm chỉ đạo chưa thật sự thống nhất”. Vậy, nguyên nhân chủ yếu của tình trạng này là gì?","o":["Những quan điểm lý luận làm cơ sở định hướng cho việc giải quyết các vấn đề thực tiễn chưa thực sự rõ ràng, đồng bộ và nhất quán.","Điều kiện kinh tế và nguồn lực vật chất của đất nước chưa đáp ứng đầy đủ yêu cầu đặt ra trong quá trình đổi mới.","Cơ sở vật chất – kỹ thuật của nền kinh tế còn nhiều hạn chế, chưa phát triển đồng bộ giữa các ngành và lĩnh vực.","Năng lực tổ chức, quản lý và kinh nghiệm thực tiễn của đội ngũ cán bộ chưa theo kịp những yêu cầu mới của quá trình đổi mới."],"a":0},{"lv":4,"id":"c1-77","ch":1,"n":77,"q":"Điều gì phản ánh rõ nhất vai trò của triết học Mác – Lênin trong đời sống xã hội hiện nay?","o":["Triết học cung cấp các giải pháp kỹ thuật cụ thể cho từng lĩnh vực nên có thể thay thế các khoa học chuyên ngành.","Triết học cung cấp hệ thống thế giới quan và phương pháp luận chung, giúp định hướng việc phân tích các vấn đề thực tiễn trên cơ sở kết hợp lý luận với tri thức cụ thể.","Triết học chủ yếu có giá trị trong việc giải thích các vấn đề lịch sử, còn những vấn đề mới của khoa học và xã hội cần được giải quyết độc lập với triết học.","Triết học giữ vai trò định hướng nhận thức bằng cách cung cấp những kết luận cố định, giúp hạn chế sự thay đổi trong tư duy lý luận."],"a":1},{"lv":4,"id":"c1-78","ch":1,"n":78,"q":"Sự phát triển của trí tuệ nhân tạo đặt ra đồng thời những vấn đề về khoa học, lao động, đạo đức, pháp luật và tổ chức xã hội. Điều gì phản ánh đúng nhất yêu cầu phương pháp luận của triết học Mác – Lênin trong việc phân tích hiện tượng này?","o":["Cần ưu tiên phân tích công nghệ vì các yếu tố xã hội chỉ là hệ quả thứ yếu.","Cần tách riêng từng lĩnh vực để tránh làm phức tạp việc nhận thức bản chất của trí tuệ nhân tạo.","Cần xem xét hiện tượng trong hệ thống các mối liên hệ giữa khoa học – công nghệ, con người và các quan hệ xã hội.","Cần tập trung vào những tác động trước mắt vì các xu hướng dài hạn chưa thể được nhận thức đầy đủ."],"a":2},{"lv":5,"id":"c1-79","ch":1,"n":79,"q":"Trong điều kiện phát triển nhanh của khoa học tự nhiên, quan điểm nào nên được lựa chọn khi đánh giá về mối quan hệ giữa khoa học cụ thể và triết học?","o":["Các phát minh khoa học mới làm cho các nguyên lý triết học trước đó không còn giá trị.","Triết học cần khái quát những thành tựu khoa học mới, đồng thời khoa học cụ thể cần tránh các kết luận thế giới quan tùy tiện.","Triết học có thể thay thế khoa học cụ thể trong việc giải thích các quy luật chuyên ngành.","Khoa học phát triển độc lập hoàn toàn với những vấn đề thế giới quan và phương pháp luận."],"a":1},{"lv":5,"id":"c1-80","ch":1,"n":80,"q":"Đánh giá nào phù hợp nhất về vai trò của ba phát minh lớn trong khoa học tự nhiên thế kỷ XIX đối với sự ra đời của triết học Mác?","o":["Các phát minh này trực tiếp tạo ra triết học Mác mà không cần điều kiện kinh tế – xã hội.","Các phát minh này cung cấp cơ sở khoa học quan trọng để nhận thức tính thống nhất vật chất và sự vận động, phát triển của thế giới.","Các phát minh này chứng minh rằng khoa học tự nhiên có thể thay thế triết học.","Các phát minh này chỉ có ý nghĩa kỹ thuật, không ảnh hưởng đến thế giới quan triết học."],"a":1},{"lv":5,"id":"c1-81","ch":1,"n":81,"q":"Đại hội XIV xác định mục tiêu tăng trưởng GDP bình quân giai đoạn 2026–2030 từ 10%/năm trở lên, đồng thời nhấn mạnh phát triển nhanh và bền vững. Theo phương pháp luận duy vật biện chứng, phương án đánh giá nào phù hợp nhất?","o":["Mục tiêu tăng trưởng cao cần được ưu tiên tuyệt đối vì quy mô kinh tế là cơ sở của mọi tiến bộ xã hội.","Mục tiêu tăng trưởng cao chỉ có thể đạt được nếu tạm thời giảm yêu cầu về môi trường và công bằng xã hội.","Mục tiêu tăng trưởng cần được đánh giá trong mối quan hệ với năng suất, chất lượng, môi trường, xã hội và các điều kiện thực tế.","Mục tiêu tăng trưởng cần được giữ nguyên bất kể điều kiện khách quan thay đổi như thế nào."],"a":2},{"lv":5,"id":"c1-82","ch":1,"n":82,"q":"Trong quá trình xây dựng chủ nghĩa xã hội ở Việt Nam, có nhiều định hướng chính sách được đề xuất. Từ phương pháp luận của triết học Mác – Lênin, theo anh (chị) chính sách nào nên được ưu tiên thực hiện?","o":["Duy trì cơ chế quản lý tập trung, quan liêu, bao cấp để đảm bảo tính thống nhất.","Chỉ tập trung phát triển kinh tế thị trường mà không quan tâm đến định hướng xã hội chủ nghĩa.","Hạn chế hội nhập quốc tế để tránh tác động từ bên ngoài để bảo tồn văn hóa Việt Nam.","Tiếp tục hoàn thiện nền kinh tế thị trường định hướng xã hội chủ nghĩa trên cơ sở đổi mới tư duy lý luận, tổng kết thực tiễn và vận dụng sáng tạo chủ nghĩa Mác – Lênin."],"a":3},{"lv":5,"id":"c1-83","ch":1,"n":83,"q":"Trong quá trình hoạch định đường lối phát triển đất nước, có rất nhiều phương án được đề xuất. Từ kiến thức đã học trong học phần Triết học Mác – Lênin, theo anh (chị) phương án nào phù hợp nhất?","o":["Kết hợp thế giới quan và phương pháp luận của Triết học Mác – Lênin với việc tổng kết thực tiễn, phân tích bối cảnh quốc tế và điều kiện cụ thể của Việt Nam để xây dựng đường lối phát triển.","Xây dựng chính sách chủ yếu dựa trên kinh nghiệm của các quốc gia phát triển.","Chỉ dựa vào kinh nghiệm thực tiễn trong nước mà không cần cơ sở lý luận bởi mỗi quốc gia đều có đặc thù riêng.","Chủ yếu dựa trên dự báo kinh tế ngắn hạn hoặc phụ thuộc vào khả năng nhạy bén nắm bắt vấn đề của những người lãnh đạo."],"a":0},{"lv":5,"id":"c1-84","ch":1,"n":84,"q":"Khi đánh giá thành tựu của công cuộc Đổi mới ở Việt Nam, theo anh (chị) nhận định nào sau đây là thuyết phục nhất?","o":["Cần dựa vào các chỉ tiêu tăng trưởng để khẳng định thành công của Đổi mới.","Cần đánh giá đồng thời những thành tựu, hạn chế, nguyên nhân và yêu cầu phát triển mới.","Những hạn chế còn tồn tại làm giảm đáng kể giá trị của các thành tựu đã đạt được.","Thành công của Đổi mới chủ yếu chứng minh tính đúng đắn của một mô hình chính sách cụ thể."],"a":1},{"lv":5,"id":"c1-85","ch":1,"n":85,"q":"Đại hội XIV của Đảng đặt đồng thời các mục tiêu về tăng trưởng, năng suất, kinh tế số, đời sống xã hội và môi trường. Điều gì phản ánh rõ nhất phương pháp luận được thể hiện trong hệ thống mục tiêu này?","o":["Ưu tiên nhiều mục tiêu để phân tán rủi ro chính sách.","Đặt mục tiêu xã hội và môi trường nhằm bù đắp những hạn chế của tăng trưởng kinh tế.","Nhận thức phát triển như một chỉnh thể gồm nhiều mặt có quan hệ tác động qua lại.","Xem các chỉ tiêu kinh tế là nền tảng, còn các chỉ tiêu khác có vai trò hỗ trợ."],"a":2},{"lv":5,"id":"c1-86","ch":1,"n":86,"q":"Có quan điểm cho rằng “lý luận Mác – Lênin phải được giữ nguyên từng luận điểm cụ thể để bảo đảm tính trung thành”. Theo anh (chị) đánh giá nào phù hợp nhất?","o":["Đúng vì mọi sự điều chỉnh lý luận đều có thể dẫn đến xa rời nguyên lý nền tảng.","Chưa phù hợp vì trung thành với lý luận phải gắn với vận dụng sáng tạo và phát triển phù hợp thực tiễn.","Sai vì lý luận chỉ có giá trị lịch sử và không còn ý nghĩa phương pháp luận.","Đúng trong lĩnh vực triết học nhưng không áp dụng đối với các lĩnh vực khác."],"a":1},{"lv":5,"id":"c1-87","ch":1,"n":87,"q":"Khi đánh giá những hạn chế trong quá trình vận dụng lý luận Mác – Lênin ở một số giai đoạn lịch sử, nhận định nào sau đây có tính thuyết phục nhất?","o":["Những hạn chế chứng minh bản thân lý luận không phù hợp với thực tiễn.","Những hạn chế chủ yếu do điều kiện khách quan nên không cần xem xét yếu tố chủ quan.","Mọi sai lầm trong vận dụng đều có thể giải thích bằng sự thiếu hụt lý luận.","Cần phân biệt giữa nguyên lý lý luận, cách giải thích, phương thức vận dụng và điều kiện lịch sử cụ thể."],"a":3},{"lv":6,"id":"c1-88","ch":1,"n":88,"q":"Trong quá trình chuyển đổi số quốc gia, nếu anh/chị là thành viên ban chỉ đạo xây dựng một hệ thống ra quyết định dựa trên dữ liệu, mô hình nào phù hợp nhất với chức năng phương pháp luận của triết học Mác – Lênin?","o":["Sử dụng dữ liệu quá khứ làm căn cứ chính để dự báo và giữ ổn định các quyết định.","Kết hợp dữ liệu thực tế, phân tích các mối liên hệ, nhận diện xu hướng vận động, kiểm nghiệm bằng thực tiễn và điều chỉnh quyết định khi điều kiện thay đổi.","Để thuật toán tự động đưa ra quyết định nhằm hạn chế sự can thiệp của yếu tố chủ quan.","Ưu tiên những dữ liệu có lợi cho mục tiêu phát triển để bảo đảm tính thống nhất của chính sách."],"a":1},{"lv":6,"id":"c1-89","ch":1,"n":89,"q":"Nếu anh (chị) được giao xây dựng chương trình phát triển kỹ năng nghề nghiệp cho sinh viên học tại trường Đại học Kỹ thuật Công nghiệp, anh (chị) sẽ vận dụng quan điểm của triết học Mác – Lênin để đề xuất phương án phù hợp nhất là?","o":["Chỉ tăng số lượng giờ thực hành và giờ thực tập doanh nghiệp và giảm bớt lý thuyết.","Giảm thời gian học lỳ thuyết và thực hành so với hệ thống hiện hành để tạo điều kiện cho sinh viên sớm ra trường.","Thiết kế chương trình tích hợp giữa lý luận và thực tiễn; kết hợp kiến thức chuyên môn với kỹ năng nghề nghiệp, kỹ năng số, nghiên cứu khoa học, đạo đức nghề nghiệp, khả năng thích ứng với chuyển đổi số và học tập suốt đời.","Thiết kế giảm bớt thời gian học lý thuyết và thực hành để tăng cường đào tạo các kỹ năng vì kỹ năng quan trọng và cần thiết trong bối cảnh chuyển đổi số hiện nay."],"a":2},{"lv":6,"id":"c1-90","ch":1,"n":90,"q":"Nếu anh (chị) được giao xây dựng một hệ thống đánh giá tác động của công nghệ trí tuệ nhân tạo (AI) đối với xã hội, phương án nào sau đây là sáng tạo nhất?","o":["Đánh giá chủ yếu dựa trên năng suất lao động và tốc độ đổi mới công nghệ.","Đánh giá đồng thời tác động đến năng suất, việc làm, quan hệ xã hội, giáo dục, quyền con người, dữ liệu và năng lực quản trị.","Tập trung kiểm soát những rủi ro trực tiếp của AI trước khi mở rộng ứng dụng trên thực tế.","Khuyến khích đổi mới công nghệ, sau đó điều chỉnh các vấn đề xã hội phát sinh bằng chính sách cụ thể."],"a":1},{"lv":6,"id":"c1-91","ch":1,"n":91,"q":"Nếu anh (chị) được giao xây dựng “Mô hình sinh viên kỹ thuật TNUT chủ động đổi mới sáng tạo trong thời đại số”, phương án tổng thể nào nên được lựa chọn?","o":["Xây dựng hệ sinh thái gồm nền tảng lý luận khoa học, năng lực chuyên môn, tư duy biện chứng, kỹ năng số, nghiên cứu thực tiễn, hợp tác liên ngành và cơ chế thử nghiệm – phản hồi – cải tiến.","Tập trung đào tạo kỹ năng sử dụng công nghệ mới, vì công nghệ là yếu tố trung tâm của đổi mới sáng tạo.","Tập trung vào các cuộc thi đổi mới sáng tạo để tạo động lực cạnh tranh giữa sinh viên.","Ưu tiên đào tạo những sinh viên có thành tích cao để hình thành các nhóm nghiên cứu tinh hoa."],"a":0},{"lv":6,"id":"c1-92","ch":1,"n":92,"q":"Nếu được giao xây dựng một kế hoạch nâng cao năng lực đổi mới sáng tạo của sinh viên kỹ thuật, phương án nào thể hiện rõ nhất sự kế thừa và phát triển?","o":["Loại bỏ hoàn toàn các phương pháp học tập truyền thống để thay thế bằng phương pháp mới.","Giữ nguyên toàn bộ phương pháp hiện có để bảo đảm sự ổn định của quá trình đào tạo.","Đánh giá những yếu tố còn phù hợp của phương pháp cũ, loại bỏ những hạn chế và tích hợp các phương pháp mới dựa trên kết quả thực tiễn.","Chọn phương pháp hiện đại nhất từ một trường đại học tiên tiến và áp dụng trực tiếp."],"a":2},{"lv":6,"id":"c1-93","ch":1,"n":93,"q":"Nếu phải thiết kế một mô hình hợp tác giữa sinh viên kỹ thuật, giảng viên và doanh nghiệp trong nghiên cứu công nghệ, phương án nào thể hiện tốt nhất sự thống nhất giữa khoa học cụ thể và triết học?","o":["Để các nhà khoa học kỹ thuật quyết định toàn bộ nội dung vì họ có chuyên môn sâu nhất.","Để triết học định hướng trực tiếp mọi giải pháp kỹ thuật cụ thể.","Tách triết học khỏi nghiên cứu kỹ thuật vì các ngành khoa học cụ thể đã có phương pháp riêng.","Kết hợp tri thức chuyên ngành, dữ liệu thực tế và phương pháp luận triết học để phân tích những vấn đề chung, mối liên hệ và định hướng phát triển của dự án."],"a":3},{"lv":6,"id":"c1-94","ch":1,"n":94,"q":"Nếu là thành viên ban chỉ đạo xây dựng “TNUT xanh”, phương án tổng thể nào phù hợp nhất với tư duy duy vật biện chứng?","o":["Tập trung tuyên truyền ý thức bảo vệ môi trường cho sinh viên, vì thay đổi nhận thức là điều kiện quyết định duy nhất.","Kết hợp thay đổi nhận thức, cải thiện hạ tầng, điều chỉnh hành vi, sử dụng công nghệ, đo lường kết quả và điều chỉnh chính sách theo thực tế.","Đầu tư hệ thống công nghệ xử lý môi trường hiện đại, vì công nghệ có thể giải quyết căn bản các vấn đề môi trường.","Đặt ra các quy định nghiêm khắc và coi việc xử phạt là phương thức chủ yếu để thay đổi hành vi."],"a":1},{"lv":6,"id":"c1-95","ch":1,"n":95,"q":"Nếu phải xây dựng kế hoạch giúp sinh viên kỹ thuật tham gia giải quyết các vấn đề phát triển bền vững, phương án nào là phù hợp nhất?","o":["Tập trung vào các giải pháp kỹ thuật có hiệu suất cao nhất.","Tập trung vào mục tiêu giảm tác động môi trường, bất kể chi phí và khả năng triển khai.","Thiết kế giải pháp trên cơ sở đánh giá đồng thời hiệu quả kỹ thuật, kinh tế, xã hội, môi trường và khả năng phát triển lâu dài.","Ưu tiên các giải pháp có thể triển khai nhanh nhất để tạo ra kết quả tức thời."],"a":2},{"lv":1,"id":"c2-1","ch":2,"n":1,"q":"Đặc điểm chung của các quan niệm triết học duy vật thời kỳ cổ đại về vật chất là gì?","o":["Đồng nhất vật chất với nguyên tử.","Đồng nhất vật chất với dạng cụ thể của vật chất.","Đồng nhất vật chất với khối lượng.","Đồng nhất vật chất với ý thức."],"a":1},{"lv":1,"id":"c2-2","ch":2,"n":2,"q":"Đặc điểm chung của các quan niệm triết học duy vật thời kỳ cận đại về vật chất là gì?","o":["Đồng nhất vật chất với dạng cụ thể của vật chất.","Đồng nhất vật chất với khối lượng; giải thích sự vận động của thế giới vật chất trên nền tảng cơ học.","Đồng nhất vật chất với nguyên tử.","Đồng nhất vật chất với ý thức."],"a":1},{"lv":1,"id":"c2-3","ch":2,"n":3,"q":"Chọn đáp án đúng điền vào chỗ trống sau: … là một phạm trù triết học dùng để chỉ thực tại khách quan được đem lại cho con người trong cảm giác, được cảm giác của chúng ta chép lại, chụp lại, phản ánh, và tồn tại không lệ thuộc vào cảm giác?","o":["Vật chất.","Ý thức.","Cảm giác.","Tri giác."],"a":0},{"lv":1,"id":"c2-4","ch":2,"n":4,"q":"Theo Ph. Ăngghen, một trong những phương thức tồn tại cơ bản của vật chất là gì?","o":["Phát triển.","Vận động.","Chuyển hóa.","Vật thể hữu hình."],"a":1},{"lv":1,"id":"c2-5","ch":2,"n":5,"q":"Tính thống nhất vật chất của thế giới được hiểu như thế nào?","o":["Chỉ có một thế giới tồn tại đó là thế giới vật chất, ngoài ra không có thế giới nào khác.","Thế giới vật chất là một chỉnh thể vừa thống nhất, vừa đa dạng. Thống nhất ở tính vật chất và đa dạng ở các hình thức tồn tại của nó.","Lịch sử loài người là kết quả của sự tiến hoá lâu dài của giới tự nhiên, của vật chất nói chung, nó không phải là thế giới bên cạnh của thế giới tự nhiên.","Tất cả đáp án đều đúng."],"a":3},{"lv":1,"id":"c2-6","ch":2,"n":6,"q":"Theo quan niệm của Triết học Mác - Lênin, ý thức là gì?","o":["Hình ảnh của thế giới khách quan.","Hình ảnh phản ánh sự vận động và phát triển của thế giới khách quan.","Là một phần chức năng của bộ óc con người.","Là hình ảnh phản ánh sáng tạo lại hiện thực khách quan."],"a":3},{"lv":1,"id":"c2-7","ch":2,"n":7,"q":"Điều kiện cần cho sự ra đời của ý thức là gì?","o":["Bộ não người.","Năng lực chế tạo và sử dụng công cụ lao động.","Bộ não người và hiện thực khách quan tương tác với nó.","Năng lực ngôn ngữ phát triển."],"a":2},{"lv":1,"id":"c2-8","ch":2,"n":8,"q":"Điều kiện đủ cho sự ra đời của ý thức là gì?","o":["Lao động và ngôn ngữ.","Bộ não người và hiện thực khách quan.","Năng lực chế tạo và sử dụng công cụ lao động.","Ngôn ngữ phát triển với cả tiếng nói và chữ viết."],"a":0},{"lv":1,"id":"c2-9","ch":2,"n":9,"q":"Nội dung nào dưới đây phản ánh đầy đủ nhất về bản chất của ý thức?","o":["Ý thức mang bản chất xã hội.","Ý thức mang bản chất tự nhiên","Ý thức có tính năng động, sáng tạo và mang bản chất xã hội.","Tất cả đáp án đều đúng."],"a":2},{"lv":1,"id":"c2-10","ch":2,"n":10,"q":"Ý nghĩa phương pháp luận được rút ra từ Mối quan hệ giữa vật chất và ý thức là gì?","o":["Trong nhận thức và hoạt động phải có quan điểm khách quan.","Mục tiêu và phương pháp đều phải căn cứ vào điều kiện khách quan thực tế, không được chủ quan duy ý chí.","Cần Phát huy tính năng động sáng tạo của ý thức.","Tất cả đáp án đều đúng."],"a":3},{"lv":2,"id":"c2-11","ch":2,"n":11,"q":"Bổ sung để được một khẳng định đúng: “Định nghĩa về vật chất của V.I.Lênin...”?","o":["Thừa nhận vật chất tồn tại bên ngoài và độc lập với ý thức con người, thông qua các dạng cụ thể của vật chất.","Thừa nhận vật chất nói chung tồn tại vĩnh viễn, tách rời các dạng cụ thể của vật chất.","Đồng nhất vật chất nói chung với một dạng cụ thể của vật chất.","Đồng nhất vật chất với khối lượng."],"a":0},{"lv":2,"id":"c2-12","ch":2,"n":12,"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, vật chất là:","o":["Thực tại khách quan và chủ quan, được ý thức phản ánh.","Tồn tại ở các dạng vật chất cụ thể, có thể cảm nhận được.","Thực tại khách quan độc lập với ý thức, không phụ thuộc vào ý thức.","Thực tại khách quan không nhận thức được."],"a":2},{"lv":2,"id":"c2-13","ch":2,"n":13,"q":"Chọn đáp án đúng về phạm trù vật chất theo quan điểm của triết học Mác - Lênin?","o":["Vật chất là nguyên tử .","Vật chất là nước.","Vật chất là đất, nước, lửa, không khí.","Vật chất là hiện thực khách quan."],"a":3},{"lv":2,"id":"c2-14","ch":2,"n":14,"q":"Nội dung nào dưới đây trong định nghĩa vật chất của V.I. Lênin giải quyết được mặt thứ nhất của vấn đề cơ bản của triết học?","o":["Vật chất là một phạm trù triết học dùng để chỉ thực tại khách quan.","Vật chất phụ thuộc vào cảm giác của con người.","Thực tại khách quan tồn tại không lệ thuộc vào cảm giác.","Thực tại chủ quan được cảm giác chép lại, chụp lại, phản ảnh."],"a":2},{"lv":2,"id":"c2-15","ch":2,"n":15,"q":"Chọn đáp án đúng về điểm đặc biệt và tính sáng tạo trong phương pháp định nghĩa vật chất của V.I. Lênin?","o":["Định nghĩa vật chất thông qua đối lập với ý thức.","Định nghĩa vật chất thông qua vận động.","Định nghĩa vật chất thông qua tồn tại.","Định nghĩa vật chất thông qua khái niệm."],"a":0},{"lv":2,"id":"c2-16","ch":2,"n":16,"q":"Hãy chỉ ra một đáp án sai khi phân tích về nội dung định nghĩa vật chất dưới đây?","o":["Vật chất là tất cả những gì tồn tại trong thế giới khách quan.","Vật chất là tất cả những cái gây nên cảm giác ở con người khi bằng cách nào đó trực tiếp hay gián tiếp tác động nên giác quan của con người.","Vật chất là những vật cụ thể tồn tại trong thế giới chủ quan và khách quan.","Khái niệm vật chất không có nghĩa gì khác hơn là thực tại khách quan tồn tại độc lập với ý thức con người và được ý thức con người phản ánh."],"a":2},{"lv":2,"id":"c2-17","ch":2,"n":17,"q":"Khẳng định: “vật chất là phức hợp những cảm giác của con người\", đó là quan điểm của trường phái triết học nào?","o":["Chủ nghĩa duy tâm khách quan.","Chủ nghĩa duy tâm chủ quan.","Chủ nghĩa duy vật biện chứng.","Chủ nghĩa duy vật siêu hình."],"a":1},{"lv":2,"id":"c2-18","ch":2,"n":18,"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, khẳng định nào sau đây là đúng?","o":["Vận động là tuyệt đối, đứng im là tương đối, tạm thời.","Vận động và đứng im phải được quan niệm là tuyệt đối.","Vận động và đứng im chỉ là tương đối, tạm thời.","Đứng im là tuyệt đối, vận động là tương đối."],"a":0},{"lv":2,"id":"c2-19","ch":2,"n":19,"q":"Chọn đáp án đúng nhất về vận động của vật chất:","o":["Vật chất chỉ có một phương thức tồn tại là vận động.","Vận động là sự dịch chuyển vị trí của các vật thể trong không gian.","Vận động là do ngoại lực tác động.","Vận động của vật chất là cố hữu, tuyệt đối, vô hạn."],"a":3},{"lv":2,"id":"c2-20","ch":2,"n":20,"q":"Nguồn gốc vận động của vật chất theo triết học Mác - Lênin là:","o":["Ở bên ngoài sự vật hiện tượng do sự tương tác hay do sự tác động.","Do ý thức tinh thần tư tưởng quyết định.","Ở trong bản thân sự vật hiện tượng do sự tác động của các mặt, các yếu tố trong sự vật hiện tượng gây ra.","Do các lực lượng siêu nhiên tạo ra."],"a":2},{"lv":2,"id":"c2-21","ch":2,"n":21,"q":"Quan điểm nào cho rằng, không gian, thời gian, vận động không liên quan với nhau và ở bên ngoài vật chất?","o":["Chủ nghĩa duy vật siêu hình.","Chủ nghĩa duy vật biện chứng.","Chủ nghĩa duy tâm khách quan.","Chủ nghĩa duy vật chất phác."],"a":0},{"lv":2,"id":"c2-22","ch":2,"n":22,"q":"Bản chất của ý thức theo quan điểm của chủ nghĩa duy vật biện chứng là gì?","o":["Hình ảnh của thế giới chủ quan và khách quan.","Quá trình vật chất vận động bên trong bộ não.","Sự phản ánh tích cực, năng động, sáng tạo thế giới khách quan vào trong đầu óc con người.","Tiếp nhận và xử lý các kích thích từ môi trường bên ngoài vào bên trong bộ não."],"a":2},{"lv":2,"id":"c2-23","ch":2,"n":23,"q":"Tại sao ý thức có khả năng tác động trở lại hiện thực khách quan?","o":["Ý thức là thuộc tính của một dạng vật chất đặc biệt.","Ý thức có thể phản ánh đúng hiện thực khách quan.","Ý thức có thể phản ánh sáng tạo, tích cực ngoài giới hạn của hiện thực khách quan.","Do hoạt động thực tiễn có ý thức của con người."],"a":3},{"lv":2,"id":"c2-24","ch":2,"n":24,"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, mệnh đề nào dưới đây là đúng?","o":["Ý thức là tồn tại duy nhất, tuyệt đối, là tính thứ nhất từ đó sinh ra tất cả; còn thế giới vật chất chỉ là bản sao, biểu hiện khác của ý thức tinh thần, là tính thứ hai, do ý thức tinh thần sinh ra.","Vật chất sinh ra ý thức và quyết định ý thức nhưng không chịu sự tác động gì từ ý thức.","Vật chất là tồn tại duy nhất, tuyệt đối, là tính thứ nhất từ đó sinh ra ý thức, đồng thời tồn tại độc lập, riêng rẽ hoàn toàn với ý thức.","Vật chất và ý thức có mối quan hệ biện chứng, tác động lẫn nhau trong đó vật chất là cái có trước, sinh ra và quyết định ý thức, còn ý thức sau khi được sinh ra cũng có tính độc lập tương đối, có khả năng tác động trở lại vật chất."],"a":3},{"lv":2,"id":"c2-25","ch":2,"n":25,"q":"Hãy xác định mệnh đề đúng về vai trò của ý thức?","o":["Ý thức cải biến hiện thực thông qua khoa học.","Ý thức tự nó cải tạo được hiện thực.","Ý thức cải biến hiện thực thông qua hoạt động thực tiễn của con người.","Ý thức phản ánh nhưng không thể cải biến hiện thực."],"a":2},{"lv":2,"id":"c2-26","ch":2,"n":26,"q":"Ý thức có thể tác động ngược trở lại vật chất thông qua hoạt động nào dưới đây?","o":["Nhận thức cảm tính.","Hoạt động thực tiễn của con người.","Tự bản thân ý thức đã tác động ngược trở lại vật chất.","Thông qua lực lượng siêu nhiên ở bên ngoài."],"a":1},{"lv":2,"id":"c2-27","ch":2,"n":27,"q":"Chọn đáp án đúng về vai trò của vật chất đối với ý thức theo quan điểm của chủ nghĩa duy vật biện chứng?","o":["Vật chất quyết định nguồn gốc và nội dung của ý thức; nội dung của ý thức là sự phản ánh đối với vật chất.","Vật chất quyết định sự biến đổi, phát triển của ý thức; sự biến đổi của ý thức là sự phản ánh đối với sự biến đổi của vật chất.","Vật chất là nhân tố quyết định, phát huy tính năng động sáng tạo của ý thức trong hoạt động thực tiễn.","Tất cả các đáp án đều đúng."],"a":3},{"lv":3,"id":"c2-28","ch":2,"n":28,"q":"Xã hội loài người có được coi là một bộ phận của thế giới vật chất không?","o":["Có, vì nó được xem là cấp độ đặc biệt của tổ chức vật chất và là cấp độ cao nhất của cấu trúc vật chất. Trong xã hội đó, tuy nhân tố hoạt động là những con người có ý thức, song không làm mất đi tính vật chất, khách quan của đời sống xã hội, của các quan hệ vật chất xã hội.","Có, vì xã hội loài người suy cho cùng cũng là vật chất và là cấp độ cao nhất của cấu trúc vật chất.","Không, vì xã hội loài người thuộc về ý thức, với những hoạt động nhận thức và tư duy sâu sắc, đặc trưng của con người.","Không, vì xét đến cùng con người là sản phẩm phát triển cao nhất của tự nhiên nhờ vào tư duy vượt trội của mình."],"a":0},{"lv":3,"id":"c2-29","ch":2,"n":29,"q":"Khi đánh giá một công nghệ mới, việc chỉ căn cứ vào một thuộc tính riêng như khối lượng, kích thước hoặc trạng thái vật lý để kết luận “đó có phải là vật chất hay không” là chưa phù hợp vì:","o":["Mọi vật chất đều phải có khối lượng xác định.","Vật chất chỉ được nhận biết bằng giác quan trực tiếp như cầm, nắm, cân, đong, đo, đếm được.","Vật chất với tư cách phạm trù triết học không bị đồng nhất với một dạng hay thuộc tính cụ thể.","Các thuộc tính vật lý không có giá trị trong nhận thức khoa học."],"a":2},{"lv":3,"id":"c2-30","ch":2,"n":30,"q":"Trong nghiên cứu kỹ thuật, khi một vật liệu mới bị thay thế bởi vật liệu khác, cách hiểu nào phù hợp với quan niệm của triết học Mác – Lênin?","o":["Vật chất nói chung đã mất đi vì dạng vật chất ban đầu không còn tồn tại.","Một dạng vật chất cụ thể có thể biến đổi hoặc chuyển hóa, nhưng không đồng nghĩa với việc vật chất nói chung bị tiêu tan.","Vật chất chỉ tồn tại khi giữ nguyên cấu trúc ban đầu.","Mọi biến đổi vật chất đều chỉ là thay đổi nhận thức của con người."],"a":1},{"lv":3,"id":"c2-31","ch":2,"n":31,"q":"Trong sản xuất công nghiệp, việc dây chuyền máy móc vẫn hoạt động ổn định trong một khoảng thời gian dù bên trong luôn diễn ra các quá trình cơ học, vật lý và hóa học thể hiện mối quan hệ nào?","o":["Đứng im tuyệt đối và vận động tương đối.","Vận động tuyệt đối và đứng im tương đối.","Vận động và đứng im hoàn toàn tách biệt.","Đứng im là trạng thái phủ định hoàn toàn vận động."],"a":1},{"lv":3,"id":"c2-32","ch":2,"n":32,"q":"Trong quá trình nghiên cứu biến đổi khí hậu, việc theo dõi nhiệt độ, thời gian diễn biến và sự thay đổi không gian của các hiện tượng tự nhiên cho thấy không gian và thời gian được xem là:","o":["Những thực thể tồn tại độc lập với vật chất.","Hình thức tồn tại của vật chất.","Sản phẩm thuần túy của ý thức con người.","Những đại lượng chỉ có ý nghĩa trong toán học."],"a":1},{"lv":3,"id":"c2-33","ch":2,"n":33,"q":"Khi một quá trình vật chất đã diễn ra, không thể làm cho nó quay trở lại nguyên trạng quá khứ theo cách tuyệt đối. Điều này phù hợp với đặc điểm nào của thời gian?","o":["Thời gian có tính ba chiều hoặc nhiều chiều, bao phủ không gian.","Thời gian tồn tại độc lập, tách rời với mọi quá trình vật chất.","Thời gian có tính một chiều, diễn ra từ quá khứ đến hiện tại và tương lai.","Thời gian chỉ phụ thuộc vào cảm nhận, tâm trạng của cá nhân."],"a":2},{"lv":3,"id":"c2-34","ch":2,"n":34,"q":"Khi một công nghệ mới được hình thành trên cơ sở các thành tựu của nhiều lĩnh vực khoa học khác nhau, việc này phản ánh cách hiểu nào về thế giới?","o":["Các sự vật tồn tại hoàn toàn biệt lập với nhau.","Chỉ có các hiện tượng tinh thần mới có quan hệ với nhau.","Mọi sự vật đều có cùng một hình thức vận động.","Thế giới vật chất có sự thống nhất và liên hệ giữa các bộ phận."],"a":3},{"lv":3,"id":"c2-35","ch":2,"n":35,"q":"Khi một sự vật được con người nhận thức dưới dạng hình ảnh tinh thần trong đầu óc, điều này thể hiện:","o":["Ý thức đồng nhất với bản thân sự vật.","Ý thức là hình ảnh chủ quan của thế giới khách quan.","Ý thức tồn tại độc lập với thế giới khách quan.","Ý thức là một dạng cụ thể của vật chất."],"a":1},{"lv":3,"id":"c2-36","ch":2,"n":36,"q":"Khi sử dụng các hệ thống trí tuệ nhân tạo trong học tập kỹ thuật, nhận định nào phù hợp nhất với quan điểm về nguồn gốc tự nhiên của ý thức?","o":["Mọi hệ thống xử lý thông tin đều có ý thức vì đều có khả năng phản ánh dữ liệu.","Ý thức là thuộc tính của mọi dạng vật chất có khả năng vận động.","Ý thức gắn với dạng vật chất có tổ chức cao là bộ óc người, đồng thời hình thành trong mối liên hệ với thế giới khách quan.","Chỉ cần có một hệ thống xử lý thông tin đủ nhanh là có thể đồng nhất với ý thức con người."],"a":2},{"lv":3,"id":"c2-37","ch":2,"n":37,"q":"Trong phát triển nguồn nhân lực chất lượng cao, việc đầu tư vào giáo dục, khoa học – công nghệ và môi trường thực tiễn phù hợp nhất với quan điểm nào về nguồn gốc xã hội của ý thức?","o":["Ý thức hình thành hoàn toàn tự nhiên, không cần xã hội.","Ý thức phát triển trong hoạt động thực tiễn, lao động và giao tiếp xã hội.","Ý thức chỉ là sản phẩm của bộ óc cá nhân.","Ý thức có thể phát triển đầy đủ mà không cần ngôn ngữ."],"a":1},{"lv":3,"id":"c2-38","ch":2,"n":38,"q":"Trong quá trình học tập và nghiên cứu kỹ thuật, việc tích lũy tri thức giúp nâng cao khả năng nhận thức và giải quyết vấn đề phù hợp với quan điểm nào về kết cấu của ý thức?","o":["Tri thức là yếu tố cơ bản và là hạt nhân của ý thức.","Niềm tin có thể thay thế hoàn toàn tri thức để hình thành ý thức.","Tình cảm là yếu tố duy nhất quyết định ý thức.","Ý thức không phụ thuộc vào lượng tri thức đã tích lũy."],"a":0},{"lv":3,"id":"c2-39","ch":2,"n":39,"q":"Khi kinh nghiệm thao tác kỹ thuật được thực hiện gần như tự động sau quá trình rèn luyện lâu dài, hiện tượng này phù hợp nhất với cấp độ nào của ý thức?","o":["Tự ý thức.","Tiềm thức.","Vô thức hoàn toàn.","Ý thức xã hội."],"a":1},{"lv":3,"id":"c2-40","ch":2,"n":40,"q":"Khả năng nhận ra điểm mạnh, điểm yếu của bản thân sau quá trình học tập để từ đó lập kế hoạch khắc phục hạn chế và phát huy ưu điểm phản ánh điều gì về ý thức?","o":["Hoạt động vô thức của con người.","Khả năng phản ánh hiện thực khách quan.","Khả năng tự ý thức của con người.","Sự hình thành ý thức xã hội."],"a":2},{"lv":3,"id":"c2-41","ch":2,"n":41,"q":"Trong hoạt động nghiên cứu và phát triển, việc sử dụng mô hình mô phỏng để dự đoán kết quả trước khi triển khai thực tế thể hiện khả năng nào của ý thức?","o":["Khả năng sáng tạo và dự báo trên cơ sở phản ánh hiện thực.","Khả năng tạo ra hiện thực hoàn toàn không phụ thuộc vật chất.","Khả năng thay thế hoàn toàn thực tiễn.","Khả năng tồn tại độc lập với hoạt động xã hội."],"a":0},{"lv":3,"id":"c2-42","ch":2,"n":42,"q":"Trong hoạt động nghiên cứu khoa học, khi kết quả giả thuyết không phù hợp với thực nghiệm, cách xử lý nào phù hợp với phương pháp luận duy vật biện chứng?","o":["Giữ nguyên giả thuyết vì ý thức có thể vượt qua mọi điều kiện vật chất.","Bác bỏ mọi kết quả thực nghiệm vì chúng chỉ phản ánh hiện tượng.","Kiểm tra lại giả thuyết trên cơ sở đối chiếu với thực tiễn và quy luật khách quan.","Điều chỉnh hiện thực để phù hợp với giả thuyết ban đầu."],"a":2},{"lv":3,"id":"c2-43","ch":2,"n":43,"q":"Việc một hệ thống trí tuệ nhân tạo (AI) có thể xử lý dữ liệu, nhận diện hình ảnh và tạo văn bản nhưng vẫn phụ thuộc vào dữ liệu, thuật toán và thiết kế của con người phù hợp với nhận định nào?","o":["AI đã có ý thức như con người nhưng ở trình độ thấp hơn.","AI là sản phẩm vật chất – kỹ thuật do con người tạo ra và chưa đồng nhất với ý thức con người.","AI là một dạng ý thức nhân tạo và độc lập hoàn toàn không liên quan với con người.","AI không liên quan đến hoạt động ý thức vì chỉ xử lý những dữ liệu có sẵn."],"a":1},{"lv":3,"id":"c2-44","ch":2,"n":44,"q":"Khi một hệ thống trí tuệ nhân tạo xử lý dữ liệu theo thuật toán do con người thiết kế, kết luận phù hợp theo quan điểm của Triết học Mác - Lênin là:","o":["Hệ thống đó có ý thức vì có thể xử lý thông tin như một con người.","Hệ thống đó không có ý thức vì nó không phải là con người.","Hệ thống đó tự tư duy độc lập và hình thành bản chất xã hội như con người.","Hệ thống đó mô phỏng một số thao tác của tư duy nhưng không đồng nhất với ý thức con người."],"a":3},{"lv":3,"id":"c2-45","ch":2,"n":45,"q":"Khi đánh giá sự phát triển của một nền kinh tế, việc chỉ dựa vào mong muốn chủ quan mà không xem xét năng suất lao động, công nghệ và nguồn lực thực tế là biểu hiện của cách tiếp cận nào?","o":["Phát huy tính năng động, tích cực, sáng tạo của ý thức.","Tôn trọng tính khách quan của vật chất.","Chủ quan duy ý chí, xa rời điều kiện khách quan.","Vận dụng đúng mối quan hệ biện chứng giữa vật chất và ý thức."],"a":2},{"lv":3,"id":"c2-46","ch":2,"n":46,"q":"Khi điều kiện vật chất thay đổi làm thay đổi nội dung nhận thức và quan niệm của con người, điều đó thể hiện:","o":["Ý thức tồn tại độc lập tuyệt đối với vật chất.","Vật chất quyết định nội dung và sự biến đổi của ý thức.","Ý thức quyết định nội dung và hình thức của vật chất.","Vật chất và ý thức không có quan hệ với nhau."],"a":1},{"lv":3,"id":"c2-47","ch":2,"n":47,"q":"Trong hoạt động phát triển công nghệ, việc sử dụng các quy luật vật lý, hóa học và sinh học để tạo ra sản phẩm mới phù hợp với quan điểm nào về vai trò của ý thức?","o":["Ý thức trực tiếp tạo ra vật chất mà không cần hoạt động thực tiễn.","Ý thức tác động trở lại vật chất thông qua hoạt động thực tiễn của con người.","Ý thức quyết định tuyệt đối mọi quá trình vật chất.","Ý thức chỉ phản ánh hiện thực mà không thể cải tạo hiện thực."],"a":1},{"lv":3,"id":"c2-48","ch":2,"n":48,"q":"Một chương trình đào tạo kỹ thuật muốn nâng cao chất lượng nhân lực cần đồng thời phát triển cơ sở vật chất, phòng thí nghiệm, chương trình học và năng lực tư duy. Cách tiếp cận này phù hợp nhất với quan điểm nào?","o":["Chỉ cần nâng cao ý thức là có thể giải quyết mọi hạn chế vật chất.","Chỉ cần đầu tư vật chất, không cần phát triển tri thức và năng lực con người.","Coi vật chất và ý thức là hai lĩnh vực hoàn toàn độc lập.","Kết hợp điều kiện vật chất với phát huy tính năng động của ý thức."],"a":3},{"lv":3,"id":"c2-49","ch":2,"n":49,"q":"Khi điều kiện vật chất đã thay đổi nhưng cách nghĩ và phương pháp tổ chức vẫn giữ nguyên là không phù hợp. Vì vậy, việc điều chỉnh nhận thức là cần thiết vì:","o":["Tự bản thân ý thức sẽ tác động ngược trở lại và quyết định vật chất.","Ý thức phải phản ánh sự biến đổi của hiện thực khách quan để phù hợp với điều kiện mới.","Vật chất không quyết định đến sự hình thành và phát triển của ý thức.","Mọi thay đổi trong ý thức đều không liên quan đến thực tiễn bởi ý thức sẽ tự điều chỉnh."],"a":1},{"lv":3,"id":"c2-50","ch":2,"n":50,"q":"Khi cơ sở vật chất và công nghệ thay đổi nhanh chóng, yêu cầu phù hợp đối với đào tạo nguồn nhân lực kỹ thuật là:","o":["Giữ nguyên phương pháp, nội dung cũ để bảo đảm tính ổn định của chương trình đào tạo đã ban hành.","Chỉ cần đầu tư thiết bị, không nhất thiết phải thay đổi tri thức và phương pháp học tập.","Kết hợp phát triển điều kiện vật chất với đổi mới tri thức, phương pháp và năng lực sáng tạo.","Chỉ cần thay đổi nhận thức vì nhận thức đúng mọi việc sẽ làm sẽ đúng, điều kiện vật chất không ảnh hưởng đến ý thức."],"a":2},{"lv":3,"id":"c2-51","ch":2,"n":51,"q":"Câu tục ngữ, thành ngữ nào sau đây phản ánh vai trò quyết định của vật chất đối với ý thức?","o":["Nước chảy đá mòn.","Có thực mới vực được đạo.","Tốt gỗ hơn tốt nước sơn.","Ở bầu thì tròn ở ống thì dài."],"a":1},{"lv":3,"id":"c2-52","ch":2,"n":52,"q":"Câu thành ngữ nào sau đây phản ánh sự tác động trở lại của ý thức đối với vật chất?","o":["Rút dây động rừng.","Có thực mới vực được đạo.","Thuận vợ thuận chồng tát biển Đông cũng cạn.","Đi một ngày đàng học một sàng khôn."],"a":2},{"lv":3,"id":"c2-53","ch":2,"n":53,"q":"Vận dụng nội dung triết học nào dưới đây để giải thích hiện tượng: “Trẻ em ở thành thị trường năng động, thông minh hơn trẻ em ở nông thôn”?","o":["Mối quan hệ nguyên nhân, kết quả.","Nguyên lý về sự phát triển.","Mối quan hệ giữa vật chất và ý thức.","Nguyên lý mối liên hệ phổ biến."],"a":2},{"lv":3,"id":"c2-54","ch":2,"n":54,"q":"Vận dụng nội dung triết học nào dưới đây để giải thích việc: “Xét về tương quan lực lượng, cơ sở vật chất có sự chênh lệch rất lớn nhưng Việt Nam đã giành thắng lợi trong cuộc đấu tranh chống lại 2 cường quốc lớn nhất thế giới là thực dân Pháp và đế quốc Mỹ ở thế kỷ XX”?","o":["Vật chất quyết định ý thức.","Tính độc lập tương đối của ý thức so với vật chất.","Nguyên lý mối liên hệ phổ biến.","Nguyên nhân và kết quả."],"a":1},{"lv":4,"id":"c2-55","ch":2,"n":55,"q":"Nguyên nhân chủ yếu làm xuất hiện khủng hoảng trong quan niệm duy vật về vật chất cuối thế kỷ XĨ, đầu thế kỷ XX là gì?","o":["Khoa học tự nhiên phủ nhận hoàn toàn sự tồn tại của thế giới khách quan.","Những phát hiện mới làm lung lay quan niệm đồng nhất vật chất với các dạng vật chất cụ thể.","Các nhà khoa học chuyển sang phủ nhận mọi quy luật của tự nhiên.","Vật lý học chứng minh rằng ý thức tồn tại độc lập với bộ óc con người."],"a":1},{"lv":4,"id":"c2-56","ch":2,"n":56,"q":"Bản chất khoa học của định nghĩa vật chất của V.I.Lênin được thể hiện rõ nhất ở điểm nào?","o":["Xác định vật chất là nguyên tử và các hạt cơ bản.","Xác định vật chất là mọi thứ có khối lượng và trọng lượng.","Xác định vật chất thông qua thuộc tính tồn tại khách quan trong quan hệ với ý thức.","Xác định vật chất chỉ bao gồm các đối tượng có thể quan sát trực tiếp."],"a":2},{"lv":4,"id":"c2-57","ch":2,"n":57,"q":"Mối quan hệ giữa các hình thức vận động cơ bản của vật chất được phản ánh đúng nhất ở nhận định nào?","o":["Hình thức vận động cao có thể tồn tại mà không bao hàm các hình thức thấp hơn.","Hình thức vận động thấp có thể bao hàm đầy đủ hình thức vận động cao hơn.","Các hình thức vận động hoàn toàn tách biệt và không liên hệ với nhau.","Hình thức vận động cao xuất hiện trên cơ sở hình thức thấp và bao hàm những hình thức thấp hơn."],"a":3},{"lv":4,"id":"c2-58","ch":2,"n":58,"q":"Nhận định nào phản ánh đúng nhất mối quan hệ giữa không gian, thời gian và vật chất?","o":["Không gian và thời gian tồn tại độc lập với vật chất.","Không gian và thời gian là những hình thức tồn tại của vật chất.","Vật chất chỉ tồn tại trong không gian, không tồn tại trong thời gian.","Không gian và thời gian chỉ là sản phẩm của tư duy, suy nghĩ của con người."],"a":1},{"lv":4,"id":"c2-59","ch":2,"n":59,"q":"Chọn đáp án đúng nhất về nguồn gốc tự nhiên của ý thức theo quan điểm của chủ nghĩa duy vật biện chứng.","o":["Bộ óc người và sự phản ánh.","Thế giới bên ngoài và ngôn ngữ.","Bộ óc người cùng với thế giới bên ngoài tác động lên bộ óc người.","Lao động và ngôn ngữ."],"a":2},{"lv":4,"id":"c2-60","ch":2,"n":60,"q":"Chọn đáp án đúng nhất về nguồn gốc xã hội của ý thức theo quan điểm của chủ nghĩa duy vật biện chứng.","o":["Lao động và sự phát triển lực lượng sản xuất.","Ngôn ngữ và bộ óc người.","Lao động và ngôn ngữ.","Bộ óc người và thế giới khách quan."],"a":2},{"lv":4,"id":"c2-61","ch":2,"n":61,"q":"Mối quan hệ nào giải thích trực tiếp nhất vai trò của ngôn ngữ đối với ý thức?","o":["Ngôn ngữ là phương tiện vật chất để biểu đạt, lưu giữ và truyền đạt nội dung ý thức.","Ngôn ngữ là một dạng vận động cơ học của cơ thể.","Ngôn ngữ tồn tại độc lập với tư duy và ý thức.","Ngôn ngữ chỉ có chức năng giao tiếp, truyền đạt thông tin không liên quan đến nhận thức."],"a":0},{"lv":4,"id":"c2-62","ch":2,"n":62,"q":"Bản chất của ý thức được phản ánh đầy đủ nhất trong nhận định nào?","o":["Ý thức là bản sao vật lý nguyên trạng của thế giới khách quan.","Ý thức là sự phản ánh năng động, sáng tạo hiện thực khách quan vào bộ óc người.","Ý thức là cái có trước, là cái sản sinh ra vật chất và thế giới khách quan.","Ý thức là tổng hợp các phản xạ sinh học đơn giản của con người."],"a":1},{"lv":4,"id":"c2-63","ch":2,"n":63,"q":"Phân tích nào làm rõ nhất sự khác nhau về bản chất giữa trí tuệ nhân tạo và ý thức con người?","o":["Trí tuệ nhân tạo có thể xử lý thông tin nhanh hơn nên có ý thức cao hơn so với con người.","Máy móc không thể tiếp nhận bất kỳ thông tin nào từ thế giới xung quanh mà nó chỉ xử lý thông tin có sẵn.","Ý thức con người chỉ là một chương trình phức tạp hơn máy tính.","Máy móc có thể mô phỏng một số thao tác tư duy nhưng không có ý thức xã hội và khả năng phản ánh sáng tạo như con người."],"a":3},{"lv":4,"id":"c2-64","ch":2,"n":64,"q":"Mối quan hệ giữa vật chất và ý thức được phân tích đúng nhất theo quan điểm duy vật biện chứng là gì?","o":["Vật chất và ý thức tồn tại song song, không tác động lẫn nhau. Sở dĩ chúng tác động với nhau là nhờ yếu tố siêu nhiên bên ngoài.","Ý thức là cái có trước. Ý thức quyết định vật chất trong mọi điều kiện.","Vật chất quyết định ý thức, còn ý thức có tính độc lập tương đối và tác động trở lại vật chất thông qua hoạt động thực tiễn của con người.","Vật chất chỉ quyết định nguồn gốc của ý thức, còn nội dung và sự phát triển của ý thức hoàn toàn độc lập."],"a":2},{"lv":4,"id":"c2-65","ch":2,"n":65,"q":"Theo anh (chị), nhận định nào sau đây không phù hợp với quan điểm của chủ nghĩa duy vật biện chứng?","o":["Ý thức chỉ phát huy tác dụng khi gắn với điều kiện vật chất và hoạt động thực tiễn.","Trong những quan hệ và điều kiện nhất định, ý thức có thể giữ vai trò quyết định.","Vật chất xét đến cùng vẫn quyết định ý thức.","Ý thức có thể tồn tại và quyết định hiện thực khách quan ngay cả khi không do vật chất sinh ra."],"a":3},{"lv":4,"id":"c2-66","ch":2,"n":66,"q":"Theo chủ nghĩa duy vật biện chứng, phát biểu nào sau đây không đúng về sự tác động trở lại của ý thức đối với vật chất?","o":["Tự bản thân ý thức có thể tác động ngược trở lại vật chất.","Ý thức phản ánh đúng hiện thực sẽ góp phần cải tạo sự vật.","Ý thức phản ánh sai quy luật sẽ cản trở hoạt động thực tiễn.","Ý thức phát huy tác dụng thông qua hoạt động thực tiễn của con người."],"a":0},{"lv":5,"id":"c2-67","ch":2,"n":67,"q":"Phương án nào đánh giá đúng nhất giá trị phương pháp luận của định nghĩa vật chất của Lênin?","o":["Giới hạn vật chất vào các đối tượng đã biết.","Bảo đảm khả năng tiếp tục nhận thức những dạng vật chất mới.","Xác định vật chất bằng khối lượng.","Tách vật chất khỏi hoạt động nhận thức."],"a":1},{"lv":5,"id":"c2-68","ch":2,"n":68,"q":"Phương án nào phù hợp nhất với quan niệm về tính vĩnh cửu và vô tận của không gian và thời gian?","o":["Không gian và thời gian có điểm kết thúc tuyệt đối.","Không gian chỉ vô tận theo chiều ngang.","Không gian và thời gian không có tận cùng tuyệt đối.","Thời gian có thể dừng lại hoàn toàn."],"a":2},{"lv":5,"id":"c2-69","ch":2,"n":69,"q":"Giải pháp nào tối ưu nhất để khắc phục bệnh chủ quan, duy ý chí của con người?","o":["Lấy mong muốn của mỗi cá nhân làm căn cứ hành động.","Xuất phát từ hiện thực khách quan và tôn trọng quy luật.","Chỉ cần dựa vào kinh nghiệm quá khứ của bản thân.","Nhờ có may mắn hoặc chờ điều kiện khách quan tự thay đổi."],"a":1},{"lv":5,"id":"c2-70","ch":2,"n":70,"q":"Quan điểm nào dưới đây phù hợp nhất với phương pháp luận của chủ nghĩa duy vật biện chứng trong việc khắc phục tư tưởng bảo thủ, trì trệ?","o":["Kiên trì bám sát những điều kiện vật chất hiện có, hạn chế thay đổi để tránh rủi ro.","Phát huy tính năng động, sáng tạo của ý thức, coi đó là nhân tố quyết định sự thay đổi của hiện thực khách quan trong mọi điều kiện.","Xuất phát từ điều kiện vật chất khách quan là đủ để cải tạo hiện thực, không nhất thiết phải phát huy vai trò của ý thức.","Phát huy tính năng động, sáng tạo của ý thức trên cơ sở tôn trọng hiện thực khách quan và quy luật khách quan."],"a":3},{"lv":5,"id":"c2-71","ch":2,"n":71,"q":"Trong quá trình triển khai chuyển đổi số quốc gia, phương án nào phản ánh đầy đủ nhất quan điểm của chủ nghĩa duy vật biện chứng về mối quan hệ giữa vật chất và ý thức?","o":["Đầu tư đồng bộ hạ tầng số là điều kiện quyết định; khi đó nhận thức và phương thức quản lý sẽ tự thích nghi.","Phát huy quyết tâm chính trị, đổi mới tư duy và năng lực lãnh đạo là nhân tố quyết định để tạo ra mọi điều kiện vật chất cần thiết.","Xuất phát từ điều kiện vật chất hiện có, đồng thời phát huy vai trò của nhận thức, năng lực tổ chức và hoạt động thực tiễn nhằm cải tạo hiện thực khách quan.","Đồng thời đầu tư công nghệ và tuyên truyền nâng cao nhận thức, trong đó có thể ưu tiên bất kỳ yếu tố nào tùy hoàn cảnh mà không cần tuân theo quy luật khách quan."],"a":2},{"lv":5,"id":"c2-72","ch":2,"n":72,"q":"Theo phương pháp luận của triết học Mác – Lênin, phương án nào phản ánh đầy đủ nhất việc kết hợp đúng vai trò của vật chất và ý thức trong phát triển?","o":["Xuất phát từ điều kiện khách quan, tôn trọng quy luật khách quan, đồng thời phát huy tính năng động, sáng tạo của ý thức thông qua hoạt động thực tiễn.","Phát huy tối đa vai trò của ý thức để chủ động tạo ra những điều kiện vật chất cần thiết khi mục tiêu đã được xác định.","Xuất phát từ điều kiện vật chất khách quan, đồng thời để sự phát triển của điều kiện vật chất tự quyết định hiệu quả hoạt động thực tiễn.","Kết hợp phát huy vai trò của ý thức và điều kiện vật chất, trong đó tùy từng hoàn cảnh có thể lấy ý chí chủ quan làm căn cứ điều chỉnh quy luật khách quan."],"a":0},{"lv":5,"id":"c2-73","ch":2,"n":73,"q":"Trong bối cảnh đẩy mạnh công nghiệp hóa, hiện đại hóa và hội nhập quốc tế, phương án nào dưới đây đánh giá đúng và đầy đủ nhất việc vận dụng nguyên lý \"Ý thức không bao giờ có thể là cái gì khác hơn là tồn tại được ý thức...\" vào thực tiễn cách mạng Việt Nam hiện nay?","o":["Tập trung nâng cao giáo dục chính trị, tư tưởng và đạo đức xã hội chủ nghĩa; khi ý thức được nâng cao thì điều kiện kinh tế sẽ tự phát triển tương ứng.","Ưu tiên phát triển kinh tế làm trung tâm để tạo nền tảng vật chất, đồng thời xây dựng đời sống văn hóa, phát triển nguồn nhân lực chất lượng cao và phát huy nhân tố con người trên cơ sở quán triệt đường lối đổi mới của Đảng.","Phát triển đồng thời kinh tế và văn hóa, trong đó tùy từng giai đoạn có thể xem nhẹ việc xây dựng đội ngũ cán bộ nếu nền kinh tế đạt tốc độ tăng trưởng cao.","Lấy tăng trưởng kinh tế làm mục tiêu ưu tiên tuyệt đối vì khi điều kiện vật chất đầy đủ thì ý thức xã hội chủ nghĩa sẽ tự hình thành và phát triển."],"a":1},{"lv":5,"id":"c2-74","ch":2,"n":74,"q":"Trong quá trình vận dụng quan điểm của chủ nghĩa duy vật biện chứng về sự tác động trở lại của ý thức đối với vật chất vào hoạt động thực tiễn, nhận định nào dưới đây KHÔNG thể hiện đúng bản chất của quan điểm này?","o":["Ý thức chỉ có thể phát huy vai trò tích cực khi phản ánh đúng quy luật khách quan, giúp con người lựa chọn mục tiêu, phương hướng và biện pháp phù hợp để cải tạo hiện thực.","Trong những điều kiện và quan hệ nhất định, ý thức có thể giữ vai trò quyết định đối với kết quả hoạt động thực tiễn, nhưng vai trò đó vẫn phải được thực hiện thông qua hoạt động của con người và không tách rời điều kiện khách quan.","Khi ý thức phản ánh đúng hiện thực khách quan, việc cải tạo sự vật sẽ luôn đạt kết quả như mong muốn, bất kể điều kiện vật chất và phương thức tổ chức thực hiện có đáp ứng yêu cầu khách quan hay không.","Ý thức phản ánh sai quy luật khách quan có thể dẫn đến việc xác định mục tiêu, phương hướng và biện pháp không phù hợp, từ đó làm giảm hoặc triệt tiêu hiệu quả cải tạo hiện thực."],"a":2},{"lv":5,"id":"c2-75","ch":2,"n":75,"q":"Từ quan điểm: \"Thực chất, nói đến vai trò của ý thức là nói đến tính năng động, sáng tạo của con người. Tính năng động, sáng tạo ấy lý giải vì sao cùng xuất phát điểm và điều kiện như nhau nhưng người này thì tiến lên, kẻ kia lại thụt lùi.\", nhận định nào dưới đây KHÔNG phù hợp nhất với quan điểm của chủ nghĩa duy vật biện chứng?","o":["Trong cùng một điều kiện khách quan, kết quả hoạt động của mỗi cá nhân có thể khác nhau do sự khác biệt về tính năng động, sáng tạo trong nhận thức và hành động.","Sự khác biệt về kết quả giữa những người có cùng xuất phát điểm cho thấy vai trò của ý thức chỉ được phát huy thông qua hoạt động thực tiễn và không tách rời điều kiện khách quan.","Nếu các cá nhân có cùng điều kiện vật chất ban đầu thì sự khác biệt về kết quả chủ yếu phản ánh mức độ phát huy vai trò của nhân tố con người, chứ không phủ nhận vai trò quyết định của điều kiện khách quan.","Khi các cá nhân có cùng điều kiện khách quan, mọi sự khác biệt về kết quả đều chứng minh rằng ý thức là nhân tố quyết định tuyệt đối, có thể vượt lên và thay thế vai trò quyết định của điều kiện vật chất."],"a":3},{"lv":6,"id":"c2-76","ch":2,"n":76,"q":"Nếu anh (chị) được giao xây dựng mô hình phát triển năng lực kỹ thuật số cho sinh viên Trường Đại học Kỹ thuật Công nghiệp, phương án tổng thể nào dưới đây cần được ưu tiên lựa chọn nhất theo quan điểm của chủ nghĩa duy vật biện chứng về mối quan hệ giữa vật chất và ý thức?","o":["Ưu tiên phát triển nhận thức số, năng lực tự học và tư duy đổi mới sáng tạo; việc đầu tư hạ tầng có thể được bổ sung dần khi nhu cầu thực tiễn phát sinh.","Tập trung đầu tư đồng bộ hạ tầng số, phòng thí nghiệm và thiết bị hiện đại; khi điều kiện vật chất được bảo đảm thì năng lực số của sinh viên sẽ từng bước hình thành tương ứng.","Đồng thời đầu tư hạ tầng, công nghệ và môi trường học tập, kết hợp đổi mới chương trình đào tạo, phát triển tri thức, kỹ năng, phương pháp học tập và năng lực sáng tạo của sinh viên trên cơ sở yêu cầu thực tiễn.","Kết hợp đầu tư điều kiện vật chất với nâng cao nhận thức của sinh viên, trong đó có thể linh hoạt ưu tiên ý chí và quyết tâm của người học hơn những yêu cầu khách quan khi triển khai mô hình."],"a":2},{"lv":6,"id":"c2-77","ch":2,"n":77,"q":"Nếu anh (chị) được giao đề xuất mô hình phát triển năng lực tự học cho sinh viên kỹ thuật, phương án nào dưới đây nên được lựa chọn nhất?","o":["Xây dựng nền tảng tri thức vững chắc, đồng thời phát huy ý thức tự học, mục tiêu học tập, phương pháp học phù hợp và gắn với hoạt động thực tiễn nhằm phát triển năng lực tự học bền vững.","Tăng cường nền tảng tri thức chuyên môn và đầu tư môi trường học tập hiện đại; khi các điều kiện này được bảo đảm thì năng lực tự học sẽ hình thành tương ứng.","Xây dựng động cơ học tập, ý thức tự giác và tinh thần tự học là trọng tâm; điều kiện học tập và hoạt động thực tiễn sẽ từng bước được hoàn thiện trong quá trình đào tạo.","Kết hợp phát triển tri thức, kỹ năng và ý thức tự học; trong đó có thể ưu tiên mục tiêu cá nhân của người học hơn những yêu cầu khách quan của chương trình đào tạo khi cần thiết."],"a":0},{"lv":6,"id":"c2-78","ch":2,"n":78,"q":"Nếu anh (chị) được giao thiết kế mô hình phát triển năng lực giải quyết các vấn đề mới cho sinh viên kỹ thuật, phương án nào dưới đây cần được ưu tiên lựa chọn nhất theo quan điểm về sự thống nhất giữa phản ánh và sáng tạo của ý thức?","o":["Tăng cường tích lũy kinh nghiệm, chuẩn hóa các quy trình giải quyết vấn đề và lựa chọn phương án đã được kiểm chứng nhằm hạn chế tối đa rủi ro khi gặp tình huống mới.","Xuất phát từ việc phân tích dữ liệu và điều kiện thực tiễn, xây dựng mô hình tư duy, đề xuất phương án mới, kiểm chứng bằng thực nghiệm và điều chỉnh liên tục theo kết quả phản hồi.","Kết hợp phân tích dữ liệu thực tế với việc vận dụng các mô hình đã thành công trước đây; chỉ khi các phương án hiện có không đáp ứng yêu cầu mới tiến hành xây dựng giải pháp sáng tạo.","Khuyến khích hình thành nhiều ý tưởng mới trên cơ sở tri thức đã có; việc kiểm chứng và đánh giá tính phù hợp của giải pháp có thể thực hiện sau khi triển khai trên diện rộng."],"a":1},{"lv":6,"id":"c2-79","ch":2,"n":79,"q":"Nếu anh (chị) được giao thiết kế mô hình kết nối đào tạo kỹ thuật với doanh nghiệp nhằm phát triển ý thức nghề nghiệp và năng lực của sinh viên, phương án nào dưới đây cần được ưu tiên lựa chọn nhất theo quan điểm của chủ nghĩa Mác – Lênin về vai trò của lao động đối với sự hình thành và phát triển ý thức?","o":["Tăng cường cho sinh viên tham quan, quan sát quy trình sản xuất và trao đổi với chuyên gia doanh nghiệp để mở rộng hiểu biết thực tiễn trước khi tham gia lao động.","Kết hợp học phần lý thuyết với các đợt thực tập tại doanh nghiệp, trong đó ưu tiên giúp sinh viên làm quen môi trường sản xuất và quy trình công nghệ nhằm củng cố kiến thức đã học.","Chuyển phần lớn thời lượng đào tạo sang môi trường doanh nghiệp để sinh viên tích lũy kinh nghiệm thực tế, từ đó từng bước hình thành nhận thức nghề nghiệp.","Tổ chức cho sinh viên tham gia giải quyết các nhiệm vụ nghề nghiệp thực tế, có mục tiêu, sản phẩm đầu ra, cơ chế phản hồi và yêu cầu vận dụng tri thức để điều chỉnh, hoàn thiện nhận thức trong quá trình lao động."],"a":3},{"lv":1,"id":"c2-80","ch":2,"n":80,"q":"Điền vào chỗ trống: “… là sự thống nhất giữa thế giới quan duy vật biện chứng và phương pháp luận biện chứng duy vật; giữa lý luận nhận thức và lôgíc biện chứng; được chứng minh bằng sự phát triển của khoa học tự nhiên trước đó”.","o":["Phép biện chứng.","Phép biện chứng duy tâm.","Phép biện chứng duy vật.","Phép biện chứng chất phác."],"a":2},{"lv":1,"id":"c2-81","ch":2,"n":81,"q":"Thế nào là biện chứng khách quan?","o":["Là khái niệm dùng để chỉ mối liên hệ biến đổi, phát triển khách quan vốn có của các sự vật hiện tượng.","Là khái niệm dùng để chỉ mối liên hệ vốn có của ý niệm.","Là khái niệm dùng để chỉ ra sự biến đổi của thế giới tinh thần.","Là kết quả của biện chứng chủ quan."],"a":0},{"lv":1,"id":"c2-82","ch":2,"n":82,"q":"Thế nào là biện chứng chủ quan?","o":["Là biện chứng của thế giới vật chất, tồn tại độc lập với ý thức của con người.","Là sự phản ánh biện chứng khách quan được phản ánh vào đầu óc con người, biện chứng của chính quá trình nhận thức, biện chứng của tư duy.","Là bản chất của biện chứng khách quan.","Là sự biến đổi do lực lượng siêu nhiên bên ngoài tác động vào bộ não con người."],"a":1},{"lv":1,"id":"c2-83","ch":2,"n":83,"q":"“Mối liên hệ” là gì?","o":["Là khái niệm cơ bản của phép biện chứng được sử dụng để chỉ sự ràng buộc quy định lẫn nhau, đồng thời là sự tác động làm biến đổi lẫn nhau giữa các sự vật hiện tượng.","Là khái niệm của phép biện chứng dùng chỉ sự nương tựa vào nhau của thế giới tinh thần.","Là khái niệm của phép biện chứng dùng chỉ mối quan hệ một chiều giữa các sự vật, hiện tượng.","Là khái niệm của phép biện chứng dùng để chỉ sự tác động bên ngoài của các sự vật, hiện tượng."],"a":0},{"lv":1,"id":"c2-84","ch":2,"n":84,"q":"Tính khách quan của mối liên hệ là gì?","o":["Là mối liên hệ vốn có của thế giới các ý niệm.","Là mối liên hệ vốn có của sự vật hiện tượng. Cơ sở của nó là tính thống nhất vật chất của thế giới.","Là mối liên hệ khách quan tồn tại bên trong ý thức của con người.","Là phụ thuộc vào ý chí của con người."],"a":1},{"lv":1,"id":"c2-85","ch":2,"n":85,"q":"Chọn cụm từ thích hợp vào dấu … để được luận điểm đúng của chủ nghĩa duy vật biện chứng: “Khi xem xét các sự vật hiện tượng, các quan điểm toàn diện, quan điểm phát triển, quan điểm lịch sử cụ thể phải...”.","o":["Tách rời nhau hoàn toàn.","Không được tách rời nhau.","Có lúc tách rời nhau, có lúc không.","Hoán đổi cho nhau."],"a":1},{"lv":1,"id":"c2-86","ch":2,"n":86,"q":"Chọn cụm từ thích hợp vào dấu … để được luận điểm của chủ nghĩa duy vật biện chứng: “Nguyên lý về mối liên hệ phổ biến và nguyên lý về sự phát triển phải…”.","o":["Đồng nhất với nhau một cách hoàn toàn.","Độc lập với nhau một cách hoàn toàn.","Quan hệ chặt chẽ với nhau, nhưng không đồng nhất với nhau.","Phải thống nhất với nhau."],"a":3},{"lv":1,"id":"c2-87","ch":2,"n":87,"q":"Chọn cụm từ thích hợp vào dấu … để được định nghĩa về phạm trù: “phạm trù là những ... phản ánh những mặt, những thuộc tính, những mối liên hệ chung, cơ bản nhất của các sự vật và hiện tượng thuộc một lĩnh vực nhất định”.","o":["Khái niệm.","Khái niệm rộng nhất.","Khái niệm cơ bản nhất.","Tất cả các đáp án."],"a":1},{"lv":1,"id":"c2-88","ch":2,"n":88,"q":"Chọn đáp án thích hợp vào dấu …: “Cái … chỉ tồn tại trong cái … thông qua cái riêng mà biểu hiện sự tồn tại của mình”.","o":["Chung/Riêng.","Riêng/Chung.","Chung/Đơn nhất.","Đơn nhất/Riêng."],"a":0},{"lv":1,"id":"c2-89","ch":2,"n":89,"q":"Chọn đáp án thích hợp vào dấu …: “Cái … là cái toàn bộ, phong phú hơn cái …”.","o":["Chung/Riêng.","Riêng/Chung.","Chung/Đơn nhất.","Đơn nhất/Riêng."],"a":1},{"lv":1,"id":"c2-90","ch":2,"n":90,"q":"Chọn đáp án thích hợp vào dấu …: “Cái … là cái bộ phận, nhưng sâu sắc hơn cái …”.","o":["Chung/Riêng.","Riêng/Chung.","Chung/Đơn nhất.","Đơn nhất/Riêng."],"a":0},{"lv":1,"id":"c2-91","ch":2,"n":91,"q":"Chọn đáp án thích hợp vào dấu …: “Cái … và cái … có thể chuyển hóa lẫn nhau trong quá trình phát triển của sự vật”.","o":["Chung/Riêng.","Riêng/Chung.","Chung/Đơn nhất.","Đơn nhất/Riêng."],"a":2},{"lv":1,"id":"c2-92","ch":2,"n":92,"q":"Chọn đáp án thích hợp vào chỗ trống: “Ngẫu nhiên là cái không do ...(1)... kết cấu vật chất quyết định, mà do ...(2)... quyết định”.","o":["1- nguyên nhân, 2- hoàn cảnh bên ngoài.","1- Mối liên hệ bản chất bên trong, 2- nhân tố bên ngoài.","1- mối liên hệ bên ngoài, 2- mối liên hệ bên trong.","1- mối liên hệ cơ bản, 2- mối liên hệ không cơ bản."],"a":1},{"lv":1,"id":"c2-93","ch":2,"n":93,"q":"Chọn đáp án thích hợp vào dấu …: “Nội dung là .... những mặt, những yếu tố, những quá trình tạo nên sự vật”.","o":["Sự tác động.","Sự kết hợp.","Tổng hợp tất cả.","Sự bao gồm."],"a":2},{"lv":1,"id":"c2-94","ch":2,"n":94,"q":"Chọn đáp án thích hợp vào dấu …: “Hình thức là hệ thống ... giữa các yếu tố của sự vật”.","o":["Mối liên hệ tương đối bền vững.","Hệ thống các bước chuyển hoá.","Mặt đối lập.","Mâu thuẫn được thiết lập."],"a":0},{"lv":1,"id":"c2-95","ch":2,"n":95,"q":"Chọn đáp án thích hợp vào chỗ trống: “Bản chất là tổng hợp tất cả những mặt, những mối liên hệ ...(1)...bên trong sự vật, quy định sự ...(2)... của sự vật”.","o":["1- chung, 2- vận động và phát triển.","1- ngẫu nhiên, 2- tồn tại và biến đổi.","1- tất nhiên, tương đối ổn định, 2- vận động và phát triển.","1- tất nhiên, tương đối ổn định, 2- tồn tại và biến đổi."],"a":2},{"lv":1,"id":"c2-96","ch":2,"n":96,"q":"Chọn đáp án thích hợp vào dấu …: “Hiện tượng là ... của bản chất”.","o":["Cơ sở.","Nguyên nhân.","Biểu hiện ra bên ngoài.","Nguồn gốc."],"a":2},{"lv":1,"id":"c2-97","ch":2,"n":97,"q":"Chọn đáp án thích hợp vào dấu …: “Khả năng là phạm trù triết học chỉ ... khi có các điều kiện thích hợp”.","o":["Cái đang có, đang tồn tại.","Cái chưa có, nhưng sẽ có.","Cái không thể có.","Cái tiền đề để tạo nên sự vật mới."],"a":1},{"lv":1,"id":"c2-98","ch":2,"n":98,"q":"Chọn đáp án thích hợp vào dấu …: “Hiện thực là phạm trù triết học chỉ cái…”.","o":["Mối liên hệ giữa các sự vật.","Chưa có, chưa tồn tại.","Đã từng xuất hiện và tồn tại.","Hiện có đang tồn tại."],"a":3},{"lv":1,"id":"c2-99","ch":2,"n":99,"q":"Chọn đáp án thích hợp vào chỗ trống: “Chất là phạm trù triết học dùng để chỉ ... (1) ... khách quan ... (2) ... là sự thống nhất hữu cơ những thuộc tính làm cho sự vật là nó chứ không là cái khác”.","o":["1- Tính quy định, 2- Vốn có của sự vật.","1- Mối liên hệ, 2- Của các sự vật.","1- Các nguyên nhân, 2- Của các sự vật.","1- Các nguyên nhân, 2- Vốn có của sự vật."],"a":0},{"lv":1,"id":"c2-100","ch":2,"n":100,"q":"Chọn đáp án thích hợp vào chỗ trống: “Lượng là phạm trù triết học dùng để chỉ...(1) ... của sự vật về mặt ...(2) ... của sự vận động và phát triển cũng như các thuộc tính của sự vật”.","o":["1- tính quy định vốn có, 2- số lượng, quy mô, trình độ, nhịp điệu.","1- mối liên hệ và phụ thuộc, 2- bản chất bên trong.","1- mức độ quy mô, 2- chất lượng, phẩm chất.","1- tính quy định vốn có, 2- chất lượng, phẩm chất."],"a":0},{"lv":2,"id":"c2-101","ch":2,"n":101,"q":"Bổ sung để được một nhận định đúng theo phép biện chứng duy vật: “Phát triển là xu hướng vận động ...”?","o":["Luôn tiến bộ của thế giới vật chất, xảy ra bên ngoài sự ổn định của sự vật, do sự giải quyết mâu thuẫn gây ra, thông qua bước nhảy về chất và hướng theo xu thế phủ định của phủ định.","Từ thấp đến cao, từ đơn giản đến phức tạp, từ chưa hoàn thiện đến hoàn thiện, xảy ra trong thế giới vật chất.","Từ thấp đến cao, từ đơn giản đến phức tạp, từ chưa hoàn thiện đến hoàn thiện, xảy ra bên ngoài sự vận động cụ thể của các sự vật cá biệt.","Từ thấp đến cao, từ đơn giản đến phức tạp, từ chưa hoàn thiện đến hoàn thiện, xảy ra bên trong một sự vật cá biệt."],"a":1},{"lv":2,"id":"c2-102","ch":2,"n":102,"q":"Theo phép biện chứng duy vật, luận điểm nào sau đây là sai?","o":["Về cơ bản, hiện tượng và bản chất thống nhất với nhau.","Có hiện tượng biểu hiện đúng bản chất nhưng cũng có hiện tượng biểu hiện không đúng bản chất.","Để hành động hiệu quả, chúng ta không chỉ dựa vào bản chất mà trước tiên cần xuất phát từ hiện tượng.","Hiện tượng và bản chất là những cái đối lập nhau."],"a":2},{"lv":2,"id":"c2-103","ch":2,"n":103,"q":"“Mọi sự vật, hiện tượng luôn gắn bó trong mối liên hệ phổ biến.”. Quan điểm này phản ánh nội dung nguyên lý nào của triết học Mác-Lênin?","o":["Nguyên lý về sự phát triển.","Nguyên lý về mối liên hệ phổ biến.","Nguyên lý khách quan.","Nguyên lý thực tiễn."],"a":1},{"lv":2,"id":"c2-104","ch":2,"n":104,"q":"Câu thành ngữ “Một con ngựa đau, cả tàu bỏ cỏ” tương đồng với nội dung triết học nào dưới đây?","o":["Mối quan hệ nguyên nhân, kết quả.","Nguyên lý về sự phát triển.","Quy luật lượng - chất.","Nguyên lý mối liên hệ phổ biến."],"a":3},{"lv":2,"id":"c2-105","ch":2,"n":105,"q":"Câu thành ngữ nào dưới đây có nội dung tương đồng với nguyên lý về mối liên hệ phổ biến trong phép biện chứng duy vật?","o":["Gieo nhân nào, gặt quả ấy.","Đánh rắn động cỏ, rút dây động rừng.","Hổ phụ sinh hổ tử.","Mạnh vì gạo, bạo vì tiền."],"a":1},{"lv":2,"id":"c2-106","ch":2,"n":106,"q":"Khi nhìn vào sự thay đổi của công nghệ từ 2G → 3G → 4G → 5G, chúng ta thấy biểu hiện rõ của nguyên lý nào?","o":["Nguyên lý về mối liên hệ phổ biến.","Nguyên lý về sự phù hợp giữa ý thức và vật chất.","Nguyên lý về sự phát triển.","Nguyên lý khách quan."],"a":2},{"lv":2,"id":"c2-107","ch":2,"n":107,"q":"“Cái riêng, Cái chung”; “Nguyên nhân, Kết quả”; “Tất nhiên, Ngẫu nhiên”; “Nội dung, Hình thức”; “Bản chất, Hiện tượng”; “Khả năng, Hiện thực” đó là các … của triết học Mác - Lênin.","o":["Cặp khái niệm.","Thuật ngữ cơ bản.","Cặp phạm trù cơ bản.","Cặp phạm trù."],"a":2},{"lv":2,"id":"c2-108","ch":2,"n":108,"q":"Các phạm trù được hình thành do đâu?","o":["Một cách bẩm sinh trong ý thức của con người.","Sẵn có ở bên ngoài, độc lập với ý thức của con người.","Thông qua quá trình hoạt động, nhận thức và thực tiễn của con người.","Tất cả các đáp án."],"a":2},{"lv":2,"id":"c2-109","ch":2,"n":109,"q":"Cái riêng là một phạm trù triết học được hiểu là?","o":["Những mặt, những thuộc tính chung của nhiều sự vật.","Một sự vật, một hiện tượng, một quá trình riêng lẻ nhất định.","Những nét, những thuộc tính chỉ có ở một sự vật.","Các yếu tố cấu thành một hệ thống."],"a":1},{"lv":2,"id":"c2-110","ch":2,"n":110,"q":"Cái đơn nhất là một phạm trù triết học được hiểu là?","o":["Tồn tại ở nhiều sự vật, hiện tượng.","Chỉ tồn tại ở một sự vật, hiện tượng, tuyệt đối không lặp lại sự vật hiện tượng khác.","Tồn tại ở một sự vật, hiện tượng, trong một quan hệ xác định.","Không có phương án nào."],"a":1},{"lv":2,"id":"c2-111","ch":2,"n":111,"q":"Phạm trù triết học nào dùng để chỉ những thuộc tính chung, không những có ở một kết cấu vật chất nhất định mà còn được lặp lại trong nhiều sự vật, hiện tượng hay quá trình riêng lẻ khác?","o":["Cái riêng.","Cái chung.","Cái đơn nhất.","Tất cả đều sai."],"a":1},{"lv":2,"id":"c2-112","ch":2,"n":112,"q":"Ở con người, yếu tố nào được coi là cái đặc thù, đơn nhất để phân biệt giữa người này với người khác?","o":["Tên gọi.","Nhóm máu.","Dấu vân tay.","Ngoại hình."],"a":2},{"lv":2,"id":"c2-113","ch":2,"n":113,"q":"Phạm trù nhằm chỉ sự tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau, gây ra một biến đổi nào đó, gọi là gì?","o":["Nguyên nhân.","Kết quả.","Khả năng.","Không có đáp án nào đúng."],"a":0},{"lv":2,"id":"c2-114","ch":2,"n":114,"q":"Phạm trù nhằm chỉ những biến đổi xuất hiện do tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau gây ra, gọi là gì?","o":["Nguyên nhân.","Kết quả.","Khả năng.","Hệ quả."],"a":1},{"lv":2,"id":"c2-115","ch":2,"n":115,"q":"Có rất nhiều loại nguyên nhân, như: nguyên nhân cơ bản, nguyên nhân chủ yếu, nguyên nhân bên trong, nguyên nhân bên ngoài, nguyên nhân chủ quan, nguyên nhân khách quan… Điều đó chứng tỏ:","o":["Một kết quả chỉ có thể do một loại nguyên nhân gây ra.","Một kết quả có thể do nhiều loại nguyên nhân gây ra.","Một kết quả có thể không cần nguyên nhân gây ra.","Không thể nhận thức được quan hệ nguyên nhân – kết quả"],"a":1},{"lv":2,"id":"c2-116","ch":2,"n":116,"q":"Cái do các nhân tố bên ngoài, do sự ngẫu hợp của nhiều hoàn cảnh bên ngoài quyết định, gọi là gì?","o":["Tất nhiên.","Ngẫu nhiên.","Khả năng.","Không xác định."],"a":1},{"lv":2,"id":"c2-117","ch":2,"n":117,"q":"Luận điểm nào sau đây là luận điểm của chủ nghĩa duy vật biện chứng về bản chất, hiện tượng?","o":["Bản chất tồn tại khách quan bên ngoài sự vật.","Hiện tượng là tổng hợp các cảm giác của con người.","Bản chất và hiện tượng đều tồn tại khách quan, là cái vốn có của sự vật.","Hiện tượng và bản chất luôn thống nhất với nhau."],"a":2},{"lv":2,"id":"c2-118","ch":2,"n":118,"q":"Vai trò của quy luật từ những sự thay đổi dần về lượng dẫn đến sự thay đổi về chất và ngược lại (quy luật lượng – chất)?","o":["Chỉ ra nguồn gốc, động lực phát triển của sự vật, hiện tượng.","Chỉ ra phương thức, cách thức của sự vận động, biến đổi, phát triển của sự vật hiện tượng.","Được coi là hạt nhân cơ bản của phép biện chứng duy vật.","Chỉ ra xu hướng, khuynh hướng vận động, phát triển của sự vật, hiện tượng."],"a":1},{"lv":2,"id":"c2-119","ch":2,"n":119,"q":"Khoảng giới hạn lớn hơn 0 0C và nhỏ hơn 100 0C của nước trong điều kiện áp suất bình thường được gọi là gì trong quy luật lượng - chất?","o":["Lượng","Độ","Bước nhảy","Chất"],"a":1},{"lv":2,"id":"c2-120","ch":2,"n":120,"q":"Giới hạn 0 0C và 100 0C của nước trong điều kiện áp suất bình thường được gọi là gì trong quy luật lượng - chất?","o":["Lượng","Độ","Bước nhảy","Điểm nút"],"a":3},{"lv":2,"id":"c2-121","ch":2,"n":121,"q":"Khi nước chuyển từ trạng thái lỏng sang trạng thái khí tại 100 0C được gọi là gì trong quy luật lượng - chất?","o":["Độ","Chuyển hoá","Bước nhảy","Tiệm tiến"],"a":2},{"lv":2,"id":"c2-122","ch":2,"n":122,"q":"Câu thành ngữ “Có công mài sắt, có ngày nên kim” tương đồng với nội dung triết học nào dưới đây?","o":["Nguyên nhân, kết quả.","Quy luật lượng – chất.","Nguyên lý mối liên hệ phổ biến","Nội dung, hình thức."],"a":1},{"lv":2,"id":"c2-123","ch":2,"n":123,"q":"Quy luật mâu thuẫn có vị trí, vai trò như thế nào trong phép biện chứng duy vật?","o":["Là hạt nhân cơ bản của phép biện chứng duy vật, vạch ra nguồn gốc bên trong của sự vận động và phát triển.","Vạch ra xu hướng của sự phát triển.","Vạch ra cách thức của sự phát triển.","Tất cả các đáp án."],"a":0},{"lv":2,"id":"c2-124","ch":2,"n":124,"q":"Vai trò của quy luật thống nhất và đấu tranh của các mặt đối lập (quy luật mâu thuẫn)?","o":["Chỉ ra nguồn gốc, động lực của sự vận động, phát triển của sự vật, hiện tượng.","Chỉ ra phương thức, cách thức của sự vận động, biến đổi, phát triển của sự vật hiện tượng.","Chỉ ra xu hướng, khuynh hướng vận động, phát triển của sự vật, hiện tượng.","Tất cả các đáp án."],"a":0},{"lv":2,"id":"c2-125","ch":2,"n":125,"q":"Mâu thuẫn nổi lên hàng đầu ở một giai đoạn phát triển nhất định của sự vật, chi phối các mâu thuẫn khác trong giai đoạn đó được gọi là mâu thuẫn gì?","o":["Mâu thuẫn cơ bản.","Mâu thuẫn chủ yếu.","Mâu thuẫn thứ yếu.","Mâu thuẫn đối kháng."],"a":1},{"lv":2,"id":"c2-126","ch":2,"n":126,"q":"Trong mâu thuẫn biện chứng, các mặt đối lập quan hệ với nhau như thế nào?","o":["Chỉ thống nhất với nhau.","Chỉ có mặt đấu tranh với nhau.","Vừa thống nhất, vừa đấu tranh với nhau.","Tồn tại độc lập với nhau."],"a":2},{"lv":2,"id":"c2-127","ch":2,"n":127,"q":"Vai trò của quy luật phủ định của phủ định?","o":["Chỉ ra nguồn gốc, động lực phát triển của sự vật, hiện tượng.","Chỉ ra phương thức, cách thức của sự vận động, biến đổi, phát triển của sự vật hiện tượng.","Được coi là hạt nhân cơ bản của phép biện chứng duy vật.","Chỉ ra xu hướng, khuynh hướng vận động, phát triển của sự vật, hiện tượng."],"a":3},{"lv":2,"id":"c2-128","ch":2,"n":128,"q":"Trong quy luật phủ định của phủ định, sự thay thế sự vật này bằng sự vật kia được gọi là gì?","o":["Mâu thuẫn","Tồn tại","Vận động","Phủ định"],"a":3},{"lv":2,"id":"c2-129","ch":2,"n":129,"q":"Con đường phát triển của sự vật mà quy luật phủ định của phủ định vạch ra là con đường nào?","o":["Đường thẳng đi lên.","Đường tròn khép kín.","Đường xoáy ốc đi lên.","Đường rích rắc."],"a":2},{"lv":3,"id":"c2-130","ch":2,"n":130,"q":"Vận dụng quan điểm toàn diện của phép biện chứng duy vật để giải quyết mối quan hệ giữa tăng trưởng kinh tế và bảo vệ môi trường ở nước ta hiện nay, giải pháp nào sau đây là phù hợp nhất?","o":["Ưu tiên tăng trưởng kinh tế để tạo tiềm lực tài chính, từ đó đầu tư trở lại cho công nghệ xử lý môi trường.","Kiểm soát chặt chẽ các tiêu chuẩn môi trường, coi đây là điều kiện quyết định trong phát triển kinh tế.","Kết hợp hài hòa mục tiêu tăng trưởng kinh tế và bảo vệ môi trường trong từng chủ trương, chính sách.","Điều chỉnh quy mô sản xuất theo sức chịu tải của môi trường và yêu cầu phát triển từng giai đoạn."],"a":2},{"lv":3,"id":"c2-131","ch":2,"n":131,"q":"Vận dụng nguyên lý về mối liên hệ phổ biến của phép biện chứng duy vật, khi nghiên cứu tình trạng ô nhiễm môi trường tại một địa phương, cách tiếp cận nào sau đây là phù hợp nhất?","o":["Phân tích thực trạng của hoạt động sản xuất tại địa phương để đưa ra giải pháp phù hợp.","Đánh giá toàn diện tác động của chính sách phát triển kinh tế và hoạt động quản lý môi trường đối với tình trạng ô nhiễm.","Làm rõ mối liên hệ giữa các yếu tố tự nhiên, kinh tế, xã hội để xác định bản chất của tình trạng ô nhiễm.","Xem xét mức độ chấp hành quy định về bảo vệ môi trường của các doanh nghiệp trên địa bàn là chủ yếu."],"a":2},{"lv":3,"id":"c2-132","ch":2,"n":132,"q":"Theo nguyên lý về mối liên hệ phổ biến của phép biện chứng duy vật, khi xây dựng kế hoạch học tập ở bậc đại học, sinh viên nên lựa chọn cách thức nào sau đây?","o":["Xác định mục tiêu học tập theo định hướng nghề nghiệp và dành nhiều thời gian cho các học phần chuyên ngành.","Xây dựng kế hoạch học tập trên cơ sở cân đối giữa mục tiêu đào tạo, năng lực bản thân, điều kiện học tập và yêu cầu của từng học phần.","Điều chỉnh kế hoạch học tập theo yêu cầu của từng học kỳ nhằm bảo đảm hoàn thành tiến độ đào tạo.","Lựa chọn nội dung và phương pháp học tập phù hợp với thế mạnh và mục tiêu của bản thân đặt ra."],"a":1},{"lv":3,"id":"c2-133","ch":2,"n":133,"q":"Theo quan điểm phát triển của triết học Mác - Lênin, khi đánh giá kết quả học tập của một sinh viên từ học lực yếu vươn lên học lực giỏi, giảng viên nên lựa chọn cách đánh giá nào sau đây?","o":["Đánh giá kết quả học tập dựa trên thành tích đạt được ở thời điểm hiện tại để phản ánh chính xác năng lực của sinh viên.","Đánh giá sinh viên trong quá trình vận động và phát triển, xem xét sự chuyển biến về năng lực, nguyên nhân của sự tiến bộ và khả năng phát triển tiếp theo.","Đánh giá dựa trên sự so sánh với giai đoạn trước đó để thấy được sự nỗ lực của sinh viên.","Đánh giá kết quả học tập của sinh viên thông qua việc đối chiếu với mặt bằng chung của lớp để xác định mức độ tiến bộ của sinh viên đó."],"a":1},{"lv":3,"id":"c2-134","ch":2,"n":134,"q":"Trong quá trình phát triển đất nước, Đảng và Nhà nước Việt Nam triển khai đường lối đối ngoại độc lập, tự chủ, đa phương hóa, đa dạng hóa; kết hợp chặt chẽ giữa hợp tác kinh tế, quốc phòng - an ninh với ngoại giao văn hóa và bảo vệ môi trường trong hội nhập quốc tế là sự vận dụng trực tiếp nguyên tắc phương pháp luận nào của phép biện chứng duy vật?","o":["Nguyên tắc toàn diện","Nguyên tắc phát triển","Nguyên tắc thực tiễn","Nguyên tắc lịch sử - cụ thể"],"a":0},{"lv":3,"id":"c2-135","ch":2,"n":135,"q":"Tư tưởng Hồ Chí Minh \"Dĩ bất biến, ứng vạn biến\" được Đảng và Nhà nước vận dụng trong đường lối đối ngoại thông qua việc kiên định mục tiêu chiến lược, đồng thời điều chỉnh phương thức và giải pháp phù hợp với sự biến đổi của bối cảnh trong nước và quốc tế. Cách vận dụng này thể hiện rõ nhất nguyên tắc phương pháp luận nào của phép biện chứng duy vật?","o":["Quan điểm toàn diện","Quan điểm phát triển","Quan điểm thực tiễn","Quan điểm lịch sử - cụ thể"],"a":3},{"lv":3,"id":"c2-136","ch":2,"n":136,"q":"Theo quy luật chuyển hóa từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại của phép biện chứng duy vật, giải pháp nào sau đây có ý nghĩa quyết định đối với việc nâng cao năng lực học tập của sinh viên?","o":["Tăng cường thời lượng học tập ở những giai đoạn có khối lượng kiến thức lớn.","Kết hợp nhiều phương pháp học tập khác nhau để nâng cao khả năng tiếp thu và ghi nhớ kiến thức.","Tích lũy có hệ thống tri thức, kỹ năng và kinh nghiệm học tập một cách thường xuyên, liên tục để tạo ra bước phát triển mới về năng lực.","Điều chỉnh cường độ học tập linh hoạt theo yêu cầu của từng học phần và từng giai đoạn của khóa học."],"a":2},{"lv":3,"id":"c2-137","ch":2,"n":137,"q":"Trong quá trình xây dựng chương trình đào tạo, một trường đại học tiến hành thiết kế hệ thống các học phần theo một kết cấu logic nhằm bảo đảm nội dung kiến thức chuyên ngành được truyền tải đầy đủ, phù hợp với mục tiêu đào tạo là biểu hiện mối quan hệ biện chứng của cặp phạm trù nào trong phép biện chứng duy vật?","o":["Khả năng và hiện thực.","Nội dung và hình thức.","Tất nhiên và ngẫu nhiên.","Cái riêng và cái chung."],"a":1},{"lv":3,"id":"c2-138","ch":2,"n":138,"q":"Vận dụng mối quan hệ giữa cái chung và cái riêng của phép biện chứng duy vật, khi Việt Nam nghiên cứu áp dụng một mô hình công nghiệp hóa đã thành công ở một số quốc gia trên thế giới, cách tiếp cận nào sau đây phù hợp nhất?","o":["Tiếp thu những kinh nghiệm có giá trị của mô hình và vận dụng phù hợp với điều kiện phát triển của Việt Nam.","Lựa chọn những nội dung đã thành công của mô hình để triển khai thống nhất trong quá trình công nghiệp hóa tại Việt Nam.","Xây dựng mô hình công nghiệp hóa hoàn toàn dựa trên đặc thù của Việt Nam, chỉ sử dụng kinh nghiệm quốc tế như một yếu tố tham khảo.","Kết hợp các yếu tố của nhiều mô hình công nghiệp hóa nhằm hình thành mô hình phát triển mới."],"a":0},{"lv":3,"id":"c2-139","ch":2,"n":139,"q":"Khi tiếp cận các thông tin có quan điểm khác nhau về cùng một vấn đề kinh tế - xã hội trên không gian mạng, việc vận dụng quy luật thống nhất và đấu tranh của các mặt đối lập giúp sinh viên lựa chọn cách xử lý nào sau đây?","o":["Đánh giá từng quan điểm trên cơ sở nguồn thông tin và bối cảnh cụ thể.","Đối chiếu các quan điểm khác nhau để làm rõ mối quan hệ giữa chúng, từ đó nhận diện bản chất của vấn đề.","Ưu tiên những quan điểm được nhiều người đồng thuận nhằm nâng cao độ tin cậy của thông tin.","Lựa chọn quan điểm phù hợp với nhận thức của bản thân và tiếp tục tham khảo thêm các ý kiến khác."],"a":1},{"lv":3,"id":"c2-140","ch":2,"n":140,"q":"Vận dụng quy luật phủ định của phủ định, khi đổi mới chương trình đào tạo đại học, phương án nào sau đây là phù hợp nhất?","o":["Điều chỉnh những nội dung chưa phù hợp, đồng thời phát huy các giá trị còn đáp ứng yêu cầu đào tạo.","Thiết kế chương trình mới trên cơ sở tham khảo các mô hình đào tạo tiên tiến trong và ngoài nước.","Rà soát toàn diện chương trình hiện hành, kế thừa những nội dung còn giá trị và phát triển các nội dung đáp ứng yêu cầu mới.","Cập nhật nội dung đào tạo theo yêu cầu của thị trường lao động và xu hướng phát triển khoa học - công nghệ."],"a":2},{"lv":3,"id":"c2-141","ch":2,"n":141,"q":"Một doanh nghiệp chuyển từ quy trình sản xuất thủ công sang tự động hóa, đồng thời tiếp tục phát huy những phương thức quản lý đã được kiểm chứng trong thực tiễn. Tình huống này phản ánh sự vận dụng nội dung nào của phép biện chứng duy vật?","o":["Quy luật chuyển hóa từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại.","Quy luật phủ định của phủ định.","Quy luật thống nhất và đấu tranh của các mặt đối lập.","Quy luật phát triển."],"a":1},{"lv":3,"id":"c2-142","ch":2,"n":142,"q":"Vận dụng quy luật phủ định của phủ định, sinh viên nên lựa chọn cách học nào để nâng cao năng lực học tập?","o":["Điều chỉnh phương pháp học theo yêu cầu của từng học phần.","Phát triển kiến thức mới trên cơ sở hoàn thiện những hiểu biết đã tích lũy.","Mở rộng phạm vi học tập bằng cách tiếp cận nhiều nguồn tài liệu khác nhau.","Tăng cường trải nghiệm thực tiễn để củng cố kiến thức đã học."],"a":1},{"lv":3,"id":"c2-143","ch":2,"n":143,"q":"Giả sử một sinh viên đạt giải thưởng nghiên cứu khoa học cấp Bộ sau nhiều năm kiên trì tích lũy kiến thức và rèn luyện kỹ năng. Theo cặp phạm trù khả năng - hiện thực, nhận định nào sau đây là phù hợp nhất?","o":["Kết quả đạt được phụ thuộc chủ yếu vào cơ hội xuất hiện trong quá trình học tập.","Khả năng được hình thành trong quá trình học tập và được hiện thực hóa khi hội đủ các điều kiện cần thiết.","Thành tích nghiên cứu chủ yếu phản ánh năng lực vốn có của sinh viên, gặp môi trường thuận lợi sẽ đạt được kết quả.","Khi đã có khả năng, kết quả sẽ xuất hiện theo thời gian mà không phụ thuộc vào các yếu tố khác."],"a":1},{"lv":3,"id":"c2-144","ch":2,"n":144,"q":"Khi thị trường có nhiều biến động, một doanh nghiệp tiến hành rà soát các điều kiện kinh doanh và điều chỉnh chiến lược cho phù hợp với bối cảnh mới. Cách tiếp cận này thể hiện sự vận dụng nguyên tắc phương pháp luận nào của phép biện chứng duy vật?","o":["Quan điểm toàn diện.","Quan điểm phát triển.","Quan điểm lịch sử - cụ thể.","Quan điểm khách quan."],"a":2},{"lv":3,"id":"c2-145","ch":2,"n":145,"q":"Giải pháp nào dưới đây thể hiện đầy đủ nhất việc vận dụng phép biện chứng duy vật trong nghiên cứu khoa học của sinh viên?","o":["Kết hợp nghiên cứu tài liệu với việc phân tích các trường hợp thực tiễn để làm rõ vấn đề.","Tập trung xây dựng cơ sở lý luận vững chắc trước khi mở rộng nghiên cứu sang các khía cạnh thực tiễn.","Xem xét đối tượng nghiên cứu trong các mối liên hệ, quá trình vận động và phát triển, đồng thời kiểm chứng kết quả bằng thực tiễn.","Khai thác kết quả của các nghiên cứu trước để lựa chọn phương pháp phù hợp với mục tiêu nghiên cứu."],"a":2},{"lv":3,"id":"c2-146","ch":2,"n":146,"q":"Một sinh viên mới ra trường gặp nhiều áp lực trong công việc và có ý định nghỉ việc sau một thời gian ngắn. Vận dụng nguyên tắc phát triển của phép biện chứng duy vật để đưa ra lời khuyên phù hợp nhất?","o":["Đánh giá lại những khó khăn đang gặp phải, đồng thời xây dựng kế hoạch và kiên trì vượt qua khó khăn để tiến bộ.","Tìm kiếm một môi trường làm việc mới có điều kiện thuận lợi hơn để phát huy năng lực bản thân.","Tạm thời giảm mục tiêu nghề nghiệp để hạn chế áp lực trong giai đoạn đầu đi làm.","Tập trung nâng cao kỹ năng chuyên môn trước khi đưa ra quyết định thay đổi công việc."],"a":0},{"lv":3,"id":"c2-147","ch":2,"n":147,"q":"Trong một vụ tai nạn giao thông xảy ra khi xe mất phanh trên đoạn đường trơn trượt, để đề xuất giải pháp phòng ngừa lâu dài, cơ quan chức năng nên lựa chọn cách tiếp cận nào sau đây?","o":["Phân tích đồng thời tình trạng kỹ thuật của phương tiện, điều kiện mặt đường và ý thức chấp hành quy định an toàn giao thông để xác định nguyên nhân chủ yếu.","Tập trung đánh giá điều kiện thời tiết và hạ tầng giao thông để đề xuất giải pháp phù hợp.","Ưu tiên kiểm tra chất lượng kỹ thuật của phương tiện nhằm tăng cường công tác đăng kiểm và bảo dưỡng.","Tổng hợp các yếu tố liên quan và lựa chọn giải pháp phù hợp với từng nhóm nguyên nhân."],"a":0},{"lv":3,"id":"c2-148","ch":2,"n":148,"q":"Nếu phát hiện một sinh viên có biểu hiện học tập tốt trên lớp nhưng lại gian lận trong các kỳ thi, vận dụng mối quan hệ giữa bản chất và hiện tượng, giảng viên nên thực hiện cách đánh giá nào sau đây là đúng đắn nhất?","o":["Phân tích tổng hợp các hành vi ở nhiều hoàn cảnh khác nhau để làm rõ bản chất thực sự, tránh bị đánh lừa bởi những hiện tượng bề nổi hay hiện tượng sai lệch.","Đánh giá sinh viên dựa trên thái độ học tập tích cực hàng ngày trên lớp vì đây là bản chất chủ yếu.","Khẳng định hành vi gian lận thi cử phản ánh chính xác bản chất đạo đức của sinh viên, lấy đó làm căn cứ để xếp loại rèn luyện.","Kết hợp kết quả học tập quá khứ với biểu hiện hiện tại để đưa ra nhận xét chung, coi bản chất sinh viên là sự duy trì ổn định của các thói quen đã hình thành."],"a":0},{"lv":3,"id":"c2-149","ch":2,"n":149,"q":"Trong một xưởng sản xuất, khi công nhân phát hiện một sáng kiến kỹ thuật mới, độc đáo, nếu vận dụng mối quan hệ giữa cái đơn nhất và cái chung, ban giám đốc nên lựa chọn cách làm nào sau đây là phù hợp nhất?","o":["Tạo điều kiện thử nghiệm, hoàn thiện sáng kiến đó trong phạm vi hẹp để từng bước áp dụng phổ biến trong toàn nhà máy.","Triển khai áp dụng ngay sáng kiến đó trên toàn bộ các dây chuyền sản xuất để nhanh chóng tối ưu hóa hiệu quả kinh tế cho doanh nghiệp.","Áp dụng sáng kiến tại những nơi có điều kiện sản xuất tương đồng nhau để đạt hiệu quả cao nhất.","Duy trì sáng kiến như một giải pháp đặc thù riêng cho khâu sản xuất đó, không thể áp dụng trong các trường hợp sản xuất khác do không giống nhau về điều kiện."],"a":0},{"lv":3,"id":"c2-150","ch":2,"n":150,"q":"Để chuyển đổi chất từ \"sinh viên đại học\" sang chất mới là \"kỹ sư\", sinh viên các trường kỹ thuật cần thực hiện quá trình tích lũy về lượng như thế nào cho đúng quy luật triết học Mác - Lênin?","o":["Kiên trì học tập, hoàn thành đủ số lượng tín chỉ và các học phần theo đúng chương trình đào tạo cho tới khi tốt nghiệp.","Tập trung học tập, hoàn thành tốt các học phần chuyên ngành để nhanh chóng tích lũy kiến thức phục vụ cho công việc trong tương lai.","Sinh viên cần tích cực đăng kí học vượt để nhanh chóng tích lũy đủ khối lượng tín chỉ theo quy định.","Tập trung dành thời gian cho thời điểm ôn thi cuối kì vì đó là thời điểm thực hiện bước nhảy quan trọng nhất."],"a":0},{"lv":3,"id":"c2-151","ch":2,"n":151,"q":"Một doanh nghiệp khởi nghiệp đã nhanh chóng mở rộng số lượng chi nhánh khi năng lực quản lý, nhân sự và nguồn vốn chưa đáp ứng yêu cầu. Vận dụng quy luật lượng - chất, nhận định nào sau đây phù hợp nhất?","o":["Mở rộng quy mô trước khi các điều kiện cần thiết cho sự chuyển biến về chất được tích lũy đầy đủ.","Tăng quy mô hoạt động nhằm tạo thêm điều kiện tích lũy nguồn lực cho giai đoạn tiếp theo.","Mở rộng quy mô trước khi các điều kiện cần thiết cho sự chuyển biến về lượng được tích lũy đầy đủ.","Lựa chọn thời điểm mở rộng dựa trên sự tương thích giữa nguồn lực và yêu cầu của thị trường."],"a":0},{"lv":3,"id":"c2-152","ch":2,"n":152,"q":"Sau khi hoàn thành môn học Triết học Mác - Lênin, tư duy của sinh viên có sự thay đổi căn bản về chất. Theo quy luật lượng - chất, chất mới này sẽ tác động trở lại quá trình tích lũy tri thức tiếp theo của sinh viên như thế nào?","o":["Khi chất mới ra đời, quá trình tích lũy tri thức diễn ra nhanh hơn.","Định hướng cách tiếp nhận và tích lũy tri thức theo hướng chủ động, sâu sắc và có hệ thống hơn.","Tiếp tục duy trì cách thức tích lũy tri thức trước đó để không ngừng tăng lượng mới.","Chất mới ra đời sẽ làm cho tri thức mới được tích lũy khác hoàn toàn so với lượng tri thức cũ."],"a":1},{"lv":3,"id":"c2-153","ch":2,"n":153,"q":"Trong một nhóm sinh viên thực hiện đề tài nghiên cứu khoa học, các thành viên có quan điểm khác nhau về cách phân chia nhiệm vụ và hướng triển khai đề tài. Vận dụng phương pháp luận của quy luật thống nhất và đấu tranh giữa các mặt đối lập, nhóm nên lựa chọn cách giải quyết nào sau đây?","o":["Ưu tiên phương án của thành viên có nhiều kinh nghiệm để thống nhất cách thực hiện.","Phân chia nhiệm vụ theo đề xuất của từng thành viên, sau đó điều chỉnh khi phát sinh vấn đề.","Phân tích những điểm khác biệt, xác định lợi ích chung và thống nhất phương án trên cơ sở trao đổi giữa các thành viên.","Lựa chọn phương án được đa số thành viên đồng ý để hạn chế tối đa bất đồng trong quá trình thực hiện."],"a":2},{"lv":3,"id":"c2-154","ch":2,"n":154,"q":"Vận dụng tính đa dạng, phong phú của mâu thuẫn, việc phân biệt mâu thuẫn bên trong (năng suất lao động, cơ cấu kinh tế…) và mâu thuẫn bên ngoài (biến động thị trường thế giới) khi xử lý khó khăn kinh tế của một quốc gia có ý nghĩa phương pháp luận nào sau đây?","o":["Nhận diện mâu thuẫn bên ngoài là nhân tố giữ vai trò quyết định chiều hướng phát triển, từ đó ưu tiên điều chỉnh các chính sách đối ngoại và hội nhập quốc tế.","Nhận diện mâu thuẫn bên trong giữ vai trò quyết định, đồng thời kết hợp hợp lý các yếu tố bên ngoài.","Đánh giá các loại mâu thuẫn có vai trò ngang nhau trong tiến trình phát triển, làm cơ sở phân bổ đồng đều nguồn lực cho cả yếu tố bên trong và bên ngoài.","Ưu tiên xử lý các mâu thuẫn bên trong vì chúng tạo động lực trực tiếp lên quá trình vận động của nền kinh tế."],"a":1},{"lv":3,"id":"c2-155","ch":2,"n":155,"q":"Theo quan điểm của triết học Mác - Lênin, sự thống nhất giữa đồng hóa và dị hóa trong cơ thể sống được thể hiện như thế nào?","o":["Mang tính chất tương đối, tạm thời, gắn liền với trạng thái ổn định tương đối để giữ cho cơ thể sống tồn tại là chính nó.","Mang tính chất tuyệt đối, vĩnh viễn, duy trì sự cân bằng không thay đổi trong suốt toàn bộ tiến trình tồn tại của cơ thể sống.","Là sự duy trì các quá trình sinh học trong trạng thái ổn định, hạn chế sự biến đổi của cơ thể.","Là sự liên kết tạm thời mang tính ngẫu nhiên giữa các yếu tố trái ngược, trong đó mặt này hoạt động không phụ thuộc vào tiền đề của mặt kia."],"a":0},{"lv":3,"id":"c2-156","ch":2,"n":156,"q":"Vận dụng tính kế thừa của quy luật phủ định của phủ định, việc xây dựng nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc trong bối cảnh hội nhập quốc tế hiện nay cần thực hiện theo giải pháp nào sau đây?","o":["Lọc bỏ các hủ tục lạc hậu, kế thừa có chọn lọc các giá trị truyền thống tốt đẹp, đồng thời tiếp thu tinh hoa văn hóa nhân loại.","Giữ gìn nguyên vẹn mọi giá trị văn hóa truyền thống đã hình thành trong lịch sử để bảo tồn tuyệt đối bản sắc dân tộc trước nguy cơ hòa nhập.","Phát huy các giá trị văn hóa dân tộc trên cơ sở ưu tiên những yếu tố phù hợp với yêu cầu phát triển hiện nay.","Tiếp thu các giá trị văn hóa hiện đại, đồng thời điều chỉnh một số yếu tố truyền thống cho phù hợp với xu thế mới."],"a":0},{"lv":3,"id":"c2-157","ch":2,"n":157,"q":"Khi một thế hệ điện thoại thông minh mới thay thế thế hệ trước với nhiều cải tiến về công nghệ và tính năng, điều đó thể hiện đặc điểm nào của phủ định biện chứng?","o":["Phủ định có tính chủ quan và kế thừa.","Phủ định có tính khách quan và kế thừa.","Phủ định có tính khách quan và loại bỏ cái cũ.","Phủ định có tính tất yếu."],"a":1},{"lv":3,"id":"c2-158","ch":2,"n":158,"q":"Trong quá trình học tập, một sinh viên thường đạt điểm cao trong các bài kiểm tra nhưng gặp khó khăn khi vận dụng kiến thức vào tình huống thực tế. Nếu vận dụng cặp phạm trù bản chất - hiện tượng, nhận định nào sau đây phù hợp nhất?","o":["Điểm số cao phản ánh chính xác năng lực thực tế của sinh viên.","Kết quả kiểm tra là một biểu hiện cần được xem xét cùng nhiều biểu hiện khác để đánh giá năng lực.","Khả năng vận dụng thực tế là thước đo để đánh giá năng lực của sinh viên.","Cả 2 hiện tượng này đều không phản ánh được bản chất nhận thức của sinh viên."],"a":1},{"lv":3,"id":"c2-159","ch":2,"n":159,"q":"Trong tình huống dịch bệnh Covid bùng phát, Chính phủ đồng thời triển khai các biện pháp y tế, bảo đảm an sinh xã hội và duy trì hoạt động lưu thông hàng hóa. Cách tiếp cận này thể hiện rõ nhất việc vận dụng quan điểm phương pháp luận nào của triết học Mác - Lênin?","o":["Quan điểm lịch sử - cụ thể.","Quan điểm toàn diện.","Quan điểm phát triển.","Quan điểm thực tiễn."],"a":1},{"lv":3,"id":"c2-160","ch":2,"n":160,"q":"Vận dụng quy luật thống nhất và đấu tranh của các mặt đối lập vào quá trình tự rèn luyện, mâu thuẫn nào sau đây có thể trở thành động lực thúc đẩy sinh viên phát triển năng lực?","o":["Mâu thuẫn giữa mục tiêu nghề nghiệp và yêu cầu về thời gian, công sức học tập.","Mâu thuẫn giữa yêu cầu của tri thức khoa học và trình độ nhận thức hiện có của sinh viên.","Mâu thuẫn giữa nhu cầu học tập và sự phân bổ thời gian cho các hoạt động cá nhân.","Mâu thuẫn giữa định hướng phát triển bản thân và những điều kiện học tập hiện có."],"a":1},{"lv":3,"id":"c2-161","ch":2,"n":161,"q":"Một sinh viên không đạt yêu cầu trong kỳ thi đánh giá kỹ năng chuyên môn do tâm lý thiếu ổn định khi làm bài. Vận dụng cặp phạm trù nguyên nhân - kết quả, cách xử lý nào sau đây phù hợp nhất?","o":["Xem xét đồng thời yếu tố tâm lý, kiến thức và phương pháp học để xác định nguyên nhân chủ yếu và có hướng điều chỉnh phù hợp.","Tập trung cải thiện khả năng kiểm soát tâm lý khi thi, vì đây là yếu tố tác động trực tiếp đến kết quả bài làm.","Tập trung tìm nguyên nhân khiến cho tâm lý khi thi không vững vàng để cải thiện dần.","Coi thất bại này là kết quả tất yếu do giới hạn năng lực của bản thân."],"a":0},{"lv":3,"id":"c2-162","ch":2,"n":162,"q":"Một sinh viên có khả năng đạt học bổng nhờ kết quả học tập tốt, nhưng để đạt được học bổng, sinh viên vẫn phải đáp ứng các tiêu chí về số tín chỉ, điểm rèn luyện và các điều kiện khác. Tình huống này cho thấy nhận định nào sau đây phù hợp nhất?","o":["Kết quả học tập tốt đã phản ánh hiện thực của việc đạt học bổng trong tương lai.","Khả năng đạt học bổng có thể trở thành hiện thực khi hội tụ đủ các điều kiện cần thiết.","Các điều kiện xét duyệt quyết định trực tiếp khả năng đạt học bổng của sinh viên.","Việc đạt học bổng phụ thuộc chủ yếu vào kết quả học tập đã tích lũy."],"a":1},{"lv":3,"id":"c2-163","ch":2,"n":163,"q":"Một người kiên trì tập luyện thể thao, tăng dần cường độ vận động và từng bước cải thiện tỷ lệ mỡ, khối lượng cơ. Tuy nhiên, những thay đổi này chưa làm cơ thể chuyển sang một trạng thái mới về chất. Theo quy luật lượng - chất, giới hạn mà sự thay đổi về lượng chưa làm thay đổi căn bản về chất được gọi là gì?","o":["Điểm nút","Độ","Bước nhảy","Lượng"],"a":1},{"lv":3,"id":"c2-164","ch":2,"n":164,"q":"Một sinh viên tích lũy đủ số tín chỉ, hoàn thành các học phần và đáp ứng các điều kiện tốt nghiệp theo quy định của chương trình đào tạo. Xét theo quy luật lượng - chất, trạng thái mà tại đó sự tích lũy về lượng tạo điều kiện cho sự thay đổi về chất được gọi là gì?","o":["Độ","Điểm nút","Bước nhảy","Chất"],"a":1},{"lv":4,"id":"c2-165","ch":2,"n":165,"q":"Điều gì phản ánh đầy đủ nhất nội dung của nguyên lý về mối liên hệ phổ biến?","o":["Các sự vật tồn tại độc lập nhưng có thể tác động lẫn nhau trong một số điều kiện nhất định.","Các sự vật, hiện tượng tồn tại trong những mối liên hệ khách quan, phổ biến và tác động qua lại lẫn nhau.","Mối liên hệ giữa các sự vật tồn tại khi con người nhận thức được về chúng.","Chỉ những sự vật có cùng thuộc tính hoặc bản chất mới có khả năng tác động qua lại với nhau."],"a":1},{"lv":4,"id":"c2-166","ch":2,"n":166,"q":"Một doanh nghiệp có năng suất lao động thấp. Qua phân tích, doanh nghiệp phát hiện nguyên nhân không chỉ nằm ở trình độ người lao động mà còn liên quan đến công nghệ, tổ chức sản xuất, cơ chế tiền lương và thị trường đầu ra. Nhận định nào sau đây làm rõ nhất ý nghĩa của việc nhận thức tính đa dạng của các mối liên hệ?","o":["Các yếu tố cùng tác động nên có thể xem chúng có vai trò tương đương trong mọi trường hợp.","Mỗi yếu tố cần được xem xét trong quan hệ với những yếu tố khác và theo vai trò cụ thể của nó.","Những yếu tố thuộc nội bộ doanh nghiệp có ý nghĩa lớn hơn các yếu tố từ môi trường bên ngoài.","Những nguyên nhân tác động trực tiếp được sử dụng để giải thích cho toàn bộ kết quả."],"a":1},{"lv":4,"id":"c2-167","ch":2,"n":167,"q":"Khi phân tích xu hướng hội nhập kinh tế quốc tế của một quốc gia đang phát triển, điều gì phản ánh bản chất của nguyên lý về sự phát triển?","o":["Hội nhập là một quá trình tiến lên liên tục, đều đặn, đảm bảo mang lại sự tăng trưởng kinh tế cao và ổn định.","Hội nhập là một quá trình vận động quanh co, phức tạp, bao hàm cả những nguy cơ thụt lùi tạm thời nhưng xu hướng tất yếu là tạo ra chất mới tiến bộ hơn cho nền kinh tế.","Hội nhập diễn ra rất phức tạp, làm gia tăng sự phụ thuộc của nền kinh tế quốc gia với nền kinh tế thế giới.","Hội nhập luôn làm cho nền kinh tế trong nước phát triển hơn vì đó là xu thế chung của thời đại."],"a":1},{"lv":4,"id":"c2-168","ch":2,"n":168,"q":"Yếu tố nào quyết định tính khách quan của mối liên hệ giữa các sự vật, hiện tượng?","o":["Nhu cầu nhận thức và hoạt động thực tiễn của con người.","Khả năng con người phát hiện và sử dụng mối liên hệ đó.","Sự quy định, tác động và chuyển hóa lẫn nhau vốn có của các sự vật, hiện tượng.","Do thế giới vật chất luôn tồn tại khách quan, không phụ thuộc vào ý muốn chủ quan của con người."],"a":3},{"lv":4,"id":"c2-169","ch":2,"n":169,"q":"Khi vận dụng quan điểm phát triển vào nhận thức một sự vật, yêu cầu nào sau đây phù hợp nhất?","o":["Đánh giá sự vật chủ yếu dựa trên trạng thái hiện tại của nó.","Xem xét sự vật trong quá trình vận động, biến đổi và xu hướng phát triển của nó.","Dựa vào trạng thái ban đầu để dự đoán toàn bộ quá trình vận động của sự vật.","Tập trung vào những tác động bên ngoài để xác định hướng phát triển của sự vật."],"a":1},{"lv":4,"id":"c2-170","ch":2,"n":170,"q":"Một chính sách hỗ trợ khởi nghiệp từng đem lại hiệu quả cao tại một địa phương nhưng khi áp dụng tại địa phương khác lại cho kết quả hạn chế. Phân tích nào sau đây phù hợp nhất với quan điểm lịch sử - cụ thể?","o":["Chính sách cần được giữ nguyên vì hiệu quả trước đó đã chứng minh tính đúng đắn của nó.","Chính sách cần được điều chỉnh theo điều kiện kinh tế, xã hội và đặc điểm phát triển của từng địa phương.","Hiệu quả chính sách phụ thuộc chủ yếu vào mức độ quyết tâm của chủ thể tổ chức thực hiện.","Sự khác biệt về kết quả cho thấy chính sách ban đầu chưa phản ánh đầy đủ quy luật phát triển chung."],"a":1},{"lv":4,"id":"c2-171","ch":2,"n":171,"q":"Khi vận dụng một nguyên tắc chung vào những trường hợp cụ thể, nhận định nào phù hợp nhất với quan hệ giữa cái chung và cái riêng?","o":["Giữ nguyên nguyên tắc chung trong mọi trường hợp để bảo đảm tính thống nhất.","Chỉ căn cứ vào đặc điểm riêng của từng trường hợp, không cần quan tâm đến cái chung.","Vận dụng cái chung trên cơ sở điều chỉnh cho phù hợp với đặc điểm của từng cái riêng.","Ưu tiên cái riêng vì mỗi sự vật đều có những đặc điểm không thể sao chép."],"a":2},{"lv":4,"id":"c2-172","ch":2,"n":172,"q":"Khi phân tích mối quan hệ giữa mô hình kinh tế thị trường chung trên thế giới và mô hình kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam, nhận định nào làm rõ nhất tính biện chứng của cặp phạm trù cái chung và cái riêng?","o":["Kinh tế thị trường định hướng xã hội chủ nghĩa là một mô hình riêng biệt lập, khác với mô hình kinh tế thị trường thế giới.","Mô hình thế giới là cái chung tồn tại thuần túy bên ngoài, Việt Nam chỉ cần sao chép nguyên vẹn cấu trúc đó vào thực tiễn trong nước.","Mô hình kinh tế của Việt Nam là cái riêng mang tính toàn bộ, chứa đựng cả cái chung và cái đặc thù để phù hợp với điều kiện cụ thể của Việt Nam.","Kinh tế thị trường là cái chung còn kinh tế thị trường định hướng xã hội chủ nghĩa cái riêng, chúng có mỗi quan hệ biện chứng với nhau."],"a":3},{"lv":4,"id":"c2-173","ch":2,"n":173,"q":"Theo phép biện chứng duy vật, nhận định nào sau đây làm rõ nhất tính phức tạp của mối quan hệ nhân - quả?","o":["Có nhiều nguyên nhân cùng tác động, trong đó mỗi nguyên nhân dẫn đến một kết quả nhất định.","Các yếu tố tác động nối tiếp nhau theo thời gian, trong đó kết quả của quá trình này trở thành nguyên nhân của những biến đổi tiếp theo.","Các yếu tố tác động qua lại và đan xen, trong đó một nguyên nhân có thể dẫn đến nhiều kết quả, đồng thời kết quả có thể tác động trở lại nguyên nhân hoặc điều kiện ban đầu.","Tính phức tạp của mối quan hệ nhân - quả đều do tác động của con người."],"a":2},{"lv":4,"id":"c2-174","ch":2,"n":174,"q":"Khi phân tích một hiện tượng để xác định nguyên nhân, yêu cầu nào phù hợp nhất với phương pháp luận của cặp phạm trù nguyên nhân - kết quả?","o":["Tập trung vào yếu tố xuất hiện ngay trước hiện tượng cần giải thích vì đó sẽ là nguyên nhân trực tiếp nhất.","Xác định chủ yếu từ những nguyên nhân chính, bên trong tạo ra sự biến đổi, đồng thời xem xét điều kiện cụ thể.","Chọn nguyên nhân có biểu hiện rõ nhất để giải thích hiện tượng.","Xem mọi điều kiện liên quan đều là nguyên nhân trực tiếp của kết quả."],"a":1},{"lv":4,"id":"c2-175","ch":2,"n":175,"q":"Theo phép biện chứng duy vật, bản chất của mối quan hệ giữa cái tất nhiên và cái ngẫu nhiên được thể hiện rõ nhất ở nhận định nào sau đây?","o":["Cái tất nhiên giữ vai trò chi phối sự vận động, còn cái ngẫu nhiên chỉ tạo ra những biến đổi không đáng kể.","Cái tất nhiên và cái ngẫu nhiên cùng tham gia vào quá trình vận động, trong đó cái ngẫu nhiên có thể tác động đến cách thức biểu hiện của cái tất nhiên.","Cái tất nhiên quyết định kết quả của sự vật, còn cái ngẫu nhiên tồn tại độc lập với quá trình phát triển của sự vật.","Cái tất nhiên biểu hiện ổn định qua các sự vật, còn cái ngẫu nhiên thay đổi tùy thuộc vào cách con người nhận thức."],"a":1},{"lv":4,"id":"c2-176","ch":2,"n":176,"q":"Nhận định nào sau đây phân tích đúng nhất mối quan hệ giữa nội dung và hình thức theo quan điểm của phép biện chứng duy vật?","o":["Hình thức giữ vai trò quyết định vì nó quy định cách nội dung được biểu hiện và tồn tại.","Nội dung giữ vai trò quyết định; hình thức có tính độc lập tương đối và tác động trở lại nội dung.","Nội dung và hình thức có mối quan hệ tương đối ổn định, mỗi mặt vận động theo những quy luật riêng.","Nội dung và hình thức cùng biến đổi trong quá trình vận động, nhưng sự thay đổi của mỗi mặt không nhất thiết phụ thuộc vào mặt còn lại."],"a":1},{"lv":4,"id":"c2-177","ch":2,"n":177,"q":"Theo phép biện chứng duy vật, khi một bản chất được biểu hiện qua nhiều hiện tượng khác nhau, điều đó cho thấy gì?","o":["Bản chất không có tính ổn định và thay đổi theo từng hiện tượng.","Hiện tượng phong phú hơn bản chất và chịu sự chi phối của điều kiện cụ thể.","Hiện tượng tồn tại độc lập và không chịu sự quy định của bản chất.","Bản chất chỉ có thể được nhận thức thông qua một hiện tượng điển hình."],"a":1},{"lv":4,"id":"c2-178","ch":2,"n":178,"q":"Theo phép biện chứng duy vật, yếu tố nào có vai trò quyết định trực tiếp đối với việc một khả năng trở thành hiện thực?","o":["Sự tồn tại của khả năng trong bản thân sự vật.","Một điều kiện riêng lẻ có tác động mạnh nhất đến sự vật.","Sự hội đủ những điều kiện cần thiết và phù hợp để khả năng được thực hiện.","Mong muốn chủ quan của chủ thể đối với kết quả cần đạt được."],"a":2},{"lv":4,"id":"c2-179","ch":2,"n":179,"q":"Nhận định nào sau đây phân tích đúng nhất mối quan hệ giữa “độ”, “điểm nút” và “bước nhảy” trong quá trình phát triển của sự vật?","o":["Độ là khoảng giới hạn của sự thay đổi về lượng; điểm nút đánh dấu giới hạn mà tại đó sự thay đổi về lượng làm xuất hiện bước nhảy về chất.","Độ là khoảng thời gian sự vật duy trì chất cũ; điểm nút là trạng thái chất mới; bước nhảy là quá trình tích lũy lượng dẫn đến trạng thái đó.","Độ và điểm nút cùng chỉ giới hạn của sự thay đổi về lượng, còn bước nhảy là sự thay đổi dần dần về chất trong quá trình vận động.","Độ biểu hiện sự ổn định của chất, điểm nút biểu hiện sự thay đổi về chất, còn bước nhảy xác định mức độ thay đổi về lượng của sự vật."],"a":0},{"lv":4,"id":"c2-180","ch":2,"n":180,"q":"Nội dung nào sau đây là ý nghĩa phương pháp luận quan trọng nhất được rút ra từ quy luật lượng - chất?","o":["Tôn trọng quá trình tích lũy về lượng, tránh chủ quan nóng vội; đồng thời không bảo thủ khi điều kiện thực hiện bước nhảy đã chín muồi.","Coi sự thay đổi về lượng là quá trình chủ yếu, còn sự thay đổi về chất là cái tất yếu phải xảy ra.","Đòi hỏi phải có thái độ khách quan, khoa học và quyết tâm thực hiện bước nhảy.","Chủ động thực hiện tích lũy nhanh chóng về lượng và tìm mọi giải pháp để thực hiện bước nhảy thành công."],"a":0},{"lv":4,"id":"c2-181","ch":2,"n":181,"q":"Nhận định nào sau đây phản ánh đúng nhất mối quan hệ giữa sự thống nhất và đấu tranh của các mặt đối lập trong quy luật mâu thuẫn?","o":["Sự thống nhất và đấu tranh cùng tồn tại trong mâu thuẫn; trong đó thống nhất mang tính tương đối, còn đấu tranh mang tính tuyệt đối và là nguồn gốc của sự vận động, phát triển.","Sự thống nhất tạo nên trạng thái ổn định của sự vật, còn đấu tranh làm thay đổi trạng thái đó; hai mặt này có vai trò tương đương trong mọi giai đoạn vận động.","Sự thống nhất là điều kiện để các mặt đối lập cùng tồn tại, còn đấu tranh chỉ xuất hiện khi sự cân bằng giữa chúng bị phá vỡ.","Sự đấu tranh giữa các mặt đối lập làm thay đổi quan hệ giữa chúng, từ đó dẫn đến sự thống nhất mới khi mâu thuẫn được giải quyết."],"a":0},{"lv":4,"id":"c2-182","ch":2,"n":182,"q":"Nhận định nào sau đây phản ánh đúng nhất mối quan hệ giữa tính kế thừa và khuynh hướng phát triển trong quy luật phủ định của phủ định?","o":["Cái mới phủ định cái cũ không phải bằng cách xóa bỏ hoàn toàn, mà kế thừa những yếu tố tích cực; vì vậy sự phát triển vừa có tính kế thừa vừa thể hiện khuynh hướng tiến lên theo đường xoáy ốc.","Cái mới kế thừa những yếu tố phù hợp của cái cũ, nhờ đó quá trình phát triển có thể lặp lại một số đặc điểm trước đây nhưng ở trạng thái tương đối ổn định hơn.","Cái mới phủ định cái cũ và tiếp nhận những yếu tố còn giá trị, qua đó sự phát triển có thể diễn ra theo những chu kỳ tương đối giống nhau nhưng không nhất thiết tạo ra sự thay đổi về chất.","Cái mới kế thừa những yếu tố tích cực của cái cũ, đồng thời loại bỏ những yếu tố không còn phù hợp, vì vậy quá trình phát triển chủ yếu diễn ra theo hướng thay thế tuần tự các trạng thái trước đó."],"a":0},{"lv":5,"id":"c2-183","ch":2,"n":183,"q":"Theo nguyên lý về mối liên hệ phổ biến, khi đánh giá một vấn đề kinh tế - xã hội có nhiều yếu tố tác động đan xen, cách tiếp cận nào phù hợp nhất?","o":["Xác định các mối liên hệ chủ yếu, xem xét vai trò của từng yếu tố trong điều kiện cụ thể và đặt chúng trong mối quan hệ với toàn bộ hệ thống.","Xem xét đồng thời tất cả các yếu tố liên quan để bảo đảm không bỏ sót bất kỳ mối liên hệ nào giữa chúng.","Tập trung vào yếu tố có biểu hiện rõ nhất, sau đó đối chiếu với một số yếu tố khác để xác định mức độ tác động.","Phân tích từng yếu tố một cách độc lập, sau đó tổng hợp đánh giá các tác động tích cực và tiêu cực tới vấn đề được xem xét."],"a":0},{"lv":5,"id":"c2-184","ch":2,"n":184,"q":"Theo phương pháp luận của triết học Mác - Lênin, khi đánh giá một quá trình phát triển của đối tượng có giai đoạn chững lại hoặc xuất hiện bước lùi, nhận định nào nên được lựa chọn?","o":["Cần xem xét toàn bộ quá trình để xác định xu hướng phát triển, không đồng nhất bước lùi tạm thời với sự phủ định xu hướng tiến lên.","Sự chững lại hay những bước lùi cho thấy dấu hiệu cản trở quá trình phát triển của đối tượng, cần đánh giá lại một cách toàn diện quá trình này.","Phát triển chỉ được xác nhận khi kết quả của giai đoạn sau luôn cao hơn giai đoạn trước.","Mọi bước lùi đều là điều kiện cần thiết để tạo ra bước tiến mới."],"a":0},{"lv":5,"id":"c2-185","ch":2,"n":185,"q":"Theo phương pháp luận của quan điểm lịch sử - cụ thể, trước sự khác biệt về điều kiện phát triển giữa các địa phương, phương án nào phù hợp nhất khi xây dựng chính sách phát triển kinh tế - xã hội?","o":["Xây dựng một mô hình chính sách thống nhất, sau đó áp dụng đồng đều để bảo đảm tính nhất quán trong quản lý.","Xác định những nguyên tắc chung, đồng thời căn cứ vào điều kiện tự nhiên, kinh tế - xã hội và đặc điểm phát triển của từng địa phương để lựa chọn cách vận dụng phù hợp.","Trao quyền cho từng địa phương xây dựng chính sách riêng, hạn chế áp dụng các tiêu chí chung để phản ánh đầy đủ đặc điểm của từng nơi.","Lựa chọn mô hình đang đạt kết quả tốt ở địa phương phát triển hơn làm cơ sở để các địa phương khác từng bước áp dụng."],"a":1},{"lv":5,"id":"c2-186","ch":2,"n":186,"q":"Có quan điểm cho rằng: “Mỗi sự vật đều có những đặc điểm riêng, vì vậy từ một số trường hợp cụ thể không thể rút ra kết luận chung có giá trị nhận thức.” Nhận định nào sau đây đánh giá thuyết phục nhất ý kiến trên?","o":["Ý kiến này có cơ sở vì cái riêng luôn phong phú hơn cái chung, nên mọi sự khái quát đều có nguy cơ làm mất đi đặc điểm của sự vật.","Ý kiến này chưa đầy đủ, vì cái chung không tồn tại bên ngoài cái riêng; từ việc nghiên cứu những cái riêng có thể phát hiện những thuộc tính và mối liên hệ chung có tính bản chất.","Ý kiến này phù hợp vì mọi cái chung chỉ được nhận thức từ việc khái quát cái riêng với số lượng đủ nhiều.","Ý kiến này có thể chấp nhận vì cái chung chỉ phản ánh những đặc điểm giống nhau, còn bản chất của sự vật được quyết định bởi những đặc điểm riêng."],"a":1},{"lv":5,"id":"c2-187","ch":2,"n":187,"q":"Một sinh viên cho rằng: “Khi đã xác định được nguyên nhân dẫn đến một hiện tượng, chỉ cần tác động vào nguyên nhân đó là có thể kiểm soát kết quả.” Theo quan điểm duy vật biện chứng, đánh giá nào thuyết phục nhất?","o":["Quan điểm trên tương đối phù hợp, vì nguyên nhân là yếu tố sản sinh ra kết quả nên tác động vào nguyên nhân sẽ làm thay đổi kết quả.","Quan điểm trên chưa đầy đủ, vì kết quả còn phụ thuộc vào điều kiện tác động; cùng một nguyên nhân có thể tạo ra kết quả khác nhau khi điều kiện thay đổi.","Quan điểm trên chưa phù hợp, vì kết quả có tính độc lập tương đối nên không chịu sự chi phối của nguyên nhân trong quá trình vận động.","Quan điểm trên có thể áp dụng khi nguyên nhân giữ vai trò chủ yếu, còn các điều kiện đi kèm chỉ có ý nghĩa trong việc làm rõ kết quả."],"a":1},{"lv":5,"id":"c2-188","ch":2,"n":188,"q":"Trong bối cảnh trí tuệ nhân tạo (AI) phát triển nhanh chóng làm thay đổi thị trường lao động, để đảm bảo năng lực cạnh tranh nghề nghiệp lâu dài cho bản thân, hãy vận dụng mối quan hệ biện chứng giữa cái tất nhiên và cái ngẫu nhiên để đưa ra cách tiếp cận hợp lý nhất?","o":["Củng cố tri thức và năng lực chuyên môn làm nền tảng cho phát triển nghề nghiệp, đồng thời chủ động rèn luyện khả năng thích ứng để nắm bắt những cơ hội mới.","Tập trung vào những kỹ năng và chứng chỉ công nghệ đang có nhu cầu cao, xem đó là cơ sở chủ yếu để bảo đảm việc làm trong tương lai.","Duy trì trạng thái học tập hiện có, chú trọng kiến thức chuyên môn trong chương trình đào tạo và điều chỉnh nếu thị trường lao động có những thay đổi rõ rệt.","Vì nhu cầu của thị trường thay đổi liên tục nên tập trung vào việc nắm bắt các cơ hội việc làm xuất hiện trong ngắn hạn để tạo ra sự linh hoạt."],"a":0},{"lv":5,"id":"c2-189","ch":2,"n":189,"q":"Theo phương pháp luận của cặp phạm trù khả năng - hiện thực, khi một mục tiêu có nhiều khả năng thực hiện, cách lựa chọn nào phù hợp nhất?","o":["Chọn khả năng có triển vọng nhất, sau đó xác định các điều kiện cần thiết để thực hiện.","Dựa vào điều kiện hiện có, xem xét các khả năng và những điều kiện cần thiết để lựa chọn hướng phù hợp.","Ưu tiên khả năng có triển vọng cao nhất vì khả năng càng lớn thì càng dễ trở thành hiện thực.","Xác định khả năng mong muốn trước, sau đó tập trung nguồn lực để thực hiện mà không cần điều chỉnh theo điều kiện thực tế."],"a":1},{"lv":5,"id":"c2-190","ch":2,"n":190,"q":"Một hiện tượng bên ngoài có thể phản ánh chưa đầy đủ, thậm chí sai lệch về bản chất của sự vật. Trước tình huống đó, quan điểm nào nên được lựa chọn?","o":["Tin vào hiện tượng đang biểu hiện rõ nhất, vì hiện tượng luôn phản ánh một phần bản chất của sự vật.","Tạm thời loại bỏ hiện tượng khỏi quá trình nhận thức vì hiện tượng có thể không phản ánh đúng bản chất.","Kết hợp phân tích các hiện tượng với việc tìm hiểu những mối liên hệ bên trong để xác định bản chất, thay vì kết luận từ một biểu hiện riêng lẻ.","Chỉ dựa vào những mối liên hệ bên trong mà không cần xem xét các hiện tượng, vì nó mới là yếu tố quyết định bản chất của sự vật."],"a":2},{"lv":5,"id":"c2-191","ch":2,"n":191,"q":"Để thúc đẩy phát triển kinh tế số, kinh tế xanh và kinh tế tuần hoàn theo định hướng Văn kiện Đại hội XIV của Đảng (nội dung mới của nền kinh tế), theo phương pháp luận về mối quan hệ giữa nội dung và hình thức, chính sách nào sau đây là phù hợp nhất?","o":["Duy trì các quy định và mô hình quản lý hiện có để bảo đảm tính ổn định của nền kinh tế.","Tập trung cải cách thủ tục hành chính, coi đây là yếu tố chủ yếu thúc đẩy sự phát triển của các ngành kinh tế mới.","Tạo điều kiện để các ngành kinh tế mới phát triển theo cơ chế thị trường, hạn chế sự điều chỉnh về thể chế và quản lý.","Đổi mới thể chế và phương thức quản lý phù hợp với yêu cầu phát triển của các ngành kinh tế mới."],"a":3},{"lv":5,"id":"c2-192","ch":2,"n":192,"q":"Để đưa nước ta trở thành quốc gia phát triển, có công nghiệp hiện đại theo định hướng tại Văn kiện Đại hội XIV của Đảng, vận dụng quy luật lượng - chất, chính sách phát triển khoa học - công nghệ nào nên được ưu tiên?","o":["Tăng cường đầu tư để tiếp nhận công nghệ tiên tiến từ bên ngoài, qua đó nhanh chóng tạo chuyển biến về năng lực công nghệ mà không cần tích lũy nhiều về tri thức trong nước.","Duy trì việc ứng dụng công nghệ hiện có, ưu tiên ổn định sản xuất và chỉ đẩy mạnh đổi mới khi quy mô và năng lực sản xuất trong nước đạt mức cao hơn.","Tăng cường thu hút đầu tư trực tiếp của nước ngoài để nhanh chóng chuyển giao công nghệ hiện đại, tạo ra sự chuyển biến về chất của trình độ khoa học - công nghệ trong nước.","Đầu tư lâu dài cho giáo dục, đào tạo nhân lực và hạ tầng nghiên cứu, từng bước tích lũy tri thức để tạo điều kiện chuyển hóa thành năng lực công nghệ tự chủ."],"a":3},{"lv":5,"id":"c2-193","ch":2,"n":193,"q":"Đứng trước mâu thuẫn giữa việc doanh nghiệp áp dụng công nghệ trí tuệ nhân tạo (AI) để tăng năng suất lao động và nguy cơ người lao động bị mất việc làm, theo quy luật thống nhất và đấu tranh giữa các mặt đối lập, cách tiếp cận nào sau đây là hợp lý nhất?","o":["Ngăn cấm doanh nghiệp đưa công nghệ mới vào sản xuất để đảm bảo việc làm hiện có cho người lao động.","Nhận thấy ứng dụng công nghệ trong sản xuất là tất yếu, chấp nhận người lao động bị đào thải tự nhiên theo quy luật thị trường.","Đồng thời thúc đẩy đổi mới công nghệ và tổ chức đào tạo lại kỹ năng cho người lao động để thích ứng với quy trình sản xuất mới.","Chỉ áp dụng công nghệ khi người lao động hiện tại đã thích nghi với máy móc, công nghệ mới."],"a":2},{"lv":5,"id":"c2-194","ch":2,"n":194,"q":"Để thực hiện mục tiêu đổi mới căn bản, toàn diện giáo dục đại học trong kỷ nguyên số theo định hướng Văn kiện Đại hội XIV, theo phương pháp luận của quy luật phủ định của phủ định, giải pháp nào sau đây là tối ưu nhất?","o":["Loại bỏ phương pháp giảng dạy truyền thống trên lớp, thay thế 100% bằng việc học trực tuyến tự động qua trí tuệ nhân tạo.","Giữ nguyên phương pháp thuyết giảng truyền thống, coi việc đưa công nghệ vào giảng dạy là yếu tố hỗ trợ.","Kế thừa nền tảng giáo dục đại học chuẩn mực cốt lõi, đồng thời tích hợp phương thức giảng dạy số hiện đại để nâng cao chất lượng đào tạo.","Áp dụng ngay mô hình đại học số của nước ngoài vào hệ thống giáo dục trong nước để hiện đại hóa giáo dục đại học trong kỷ nguyên mới."],"a":2},{"lv":6,"id":"c2-195","ch":2,"n":195,"q":"Nếu anh (chị) được giao xây dựng kế hoạch phát triển toàn diện bản thân trong 4 năm đại học để đáp ứng yêu cầu nguồn nhân lực chất lượng cao thời kỳ mới, giải pháp tổng hợp nào sau đây tối ưu nhất?","o":["Tập trung tối đa vào kết quả học tập chính khóa, lấy điểm số chuyên môn làm tiêu chuẩn duy nhất định hình năng lực nghề nghiệp.","Thiết kế lộ trình tích hợp: kết hợp học chuyên môn, trau dồi ngoại ngữ - kỹ năng số và rèn luyện thể chất.","Kết hợp việc học tập chính khóa với việc đi làm sớm để tích lũy kinh nghiệm thực tế vì khả năng thực chiến là mục tiêu cuối cùng.","Chia nhỏ mục tiêu thành các giai đoạn biệt lập theo từng năm học (ngoại ngữ, chuyên ngành, kỹ năng) nhằm tránh phân tán nguồn lực."],"a":1},{"lv":6,"id":"c2-196","ch":2,"n":196,"q":"Nếu anh (chị) được giao xây dựng phương án xử lý mâu thuẫn giữa yêu cầu đổi mới và yêu cầu duy trì sự ổn định, dựa vào phương pháp luận của quy luật thống nhất và đấu tranh giữa các mặt đối lập, phương án tổng thể nào nên được lựa chọn?","o":["Ưu tiên duy trì ổn định, chỉ thúc đẩy đổi mới khi những điều kiện cần thiết đã trở nên rõ ràng.","Ưu tiên đổi mới để nhanh chóng tạo trạng thái mới, chấp nhận những biến động phát sinh trong quá trình chuyển đổi.","Xác định các mặt đối lập, làm rõ mâu thuẫn chủ yếu trong từng giai đoạn và lựa chọn cách giải quyết phù hợp với điều kiện cụ thể.","Duy trì sự cân bằng giữa đổi mới và ổn định, hạn chế tác động của các mặt đối lập để giữ tổ chức vận hành ổn định."],"a":2},{"lv":6,"id":"c2-197","ch":2,"n":197,"q":"Nếu anh (chị) là người quản lý Trung tâm khởi nghiệp công nghệ của trường đại học, phương án nào phù hợp nhất để đưa các ý tưởng nghiên cứu (khả năng) thành sản phẩm thương mại (hiện thực)?","o":["Tổ chức các hoạt động tìm kiếm và lựa chọn ý tưởng, sau đó để các nhóm nghiên cứu chủ động tìm nguồn lực và triển khai theo điều kiện của mình.","Ưu tiên cấp kinh phí cho các ý tưởng mới, đồng thời tạo điều kiện để nhóm nghiên cứu chủ động hoàn thiện sản phẩm và tìm kiếm thị trường.","Đánh giá tính khả thi của ý tưởng, xác định các điều kiện cần thiết, hỗ trợ hoàn thiện sản phẩm và kết nối với các nguồn lực phù hợp để từng bước đưa sản phẩm vào thực tế.","Tập trung hoàn thiện các ý tưởng trong phạm vi nhà trường, sau khi sản phẩm đạt mức hoàn chỉnh mới xem xét khả năng hợp tác với doanh nghiệp và nhà đầu tư."],"a":2},{"lv":6,"id":"c2-198","ch":2,"n":198,"q":"Nếu phải đề xuất một Kế hoạch tự học để đạt chuẩn đầu ra ngoại ngữ quốc tế trong 1 năm, theo phương pháp luận của quy luật lượng - chất, lộ trình nào sau đây là tối ưu nhất?","o":["Duy trì lịch học đều đặn mỗi ngày theo lộ trình từ cơ bản đến nâng cao, kết hợp luyện đề định kỳ để chuẩn bị cho kỳ thi đánh giá năng lực chính thức.","Dồn tối đa thời gian tự học cường độ cao vào tháng cuối cùng trước kỳ thi, tận dụng khả năng tập trung ngắn hạn để tạo sự đột phá nhanh về kết quả điểm số.","Tập trung rèn luyện các kỹ thuật và mẹo làm bài thi trắc nghiệm ngắn hạn, ưu tiên tối ưu hóa điểm số.","Phân bổ thời gian học linh hoạt, không đặt nặng mục tiêu theo từng giai đoạn, tin rằng việc tiếp xúc tự nhiên với tài liệu hàng ngày sẽ tự tạo ra sự tiến bộ."],"a":0},{"lv":6,"id":"c2-199","ch":2,"n":199,"q":"Nếu anh (chị) là thành viên ban xây dựng chương trình đào tạo đại học mới, phương án nào phù hợp nhất với yêu cầu tích lũy về lượng để tạo ra sự thay đổi về chất?","o":["Thiết kế chương trình theo từng học phần, tăng dần kiến thức nền tảng và kỹ năng mới qua các học kỳ, tạo cơ sở để sinh viên thực hiện các học phần chuyên ngành và đồ án tốt nghiệp.","Bố trí phần lớn học phần chuyên ngành vào giai đoạn đầu, giúp sinh viên sớm tiếp cận yêu cầu chuyên môn ở mức cao về sau.","Tăng thời lượng các học phần lý thuyết, nhằm bảo đảm sinh viên tích lũy được khối lượng kiến thức lớn trước khi chuyển sang thực hành.","Giảm các học phần cơ sở và lý thuyết, tăng thời lượng thực tập tại doanh nghiệp để sinh viên sớm tiếp cận các kỹ năng thực hành gắn với chuyên môn."],"a":0},{"lv":1,"id":"c2-200","ch":2,"n":200,"q":"Giai đoạn nhận thức diễn ra trên cơ sở sự tác động trực tiếp của các sự vật lên các giác quan của con người là giai đoạn nhận thức nào ?","o":["Nhận thức lý tính.","Nhận thức khoa học.","Nhận thức lý luận.","Nhận thức cảm tính."],"a":3},{"lv":1,"id":"c2-201","ch":2,"n":201,"q":"Hình thức nào là hình thức đầu tiên của giai đoạn nhận thức cảm tính?","o":["Khái niệm","Biểu tượng","Cảm giác","Tri giác"],"a":2},{"lv":1,"id":"c2-202","ch":2,"n":202,"q":"Đặc điểm chung của các hình thức nhận thức cảm tính là gì?","o":["Trực tiếp, bề ngoài.","Gián tiếp, bề ngoài.","Trực tiếp, bản chất.","Gián tiếp, bản chất."],"a":0},{"lv":1,"id":"c2-203","ch":2,"n":203,"q":"Theo quan niệm của Triết học Mác - Lênin, thực tiễn là gì?","o":["Hoạt động của con người.","Hoạt động vật chất của con người.","Hoạt động vật chất của con người có tính mục đích.","Hoạt động vật chất có mục đích, mang tính lịch sử xã hội nhằm cải tạo tự nhiên và xã hội."],"a":3},{"lv":1,"id":"c2-204","ch":2,"n":204,"q":"Chọn đáp án thích hợp vào dấu …:\"Thực tiễn là toàn bộ những ... có mục đích, mang tính lịch sử xã hội của con người nhằm cải tạo tự nhiên và xã hội\".","o":["Hoạt động.","Hoạt động vật chất.","Hoạt động có mục đích.","Hoạt động vật chất có mục đích, mang tính lịch sử - xã hội."],"a":3},{"lv":1,"id":"c2-205","ch":2,"n":205,"q":"Hãy lựa chọn câu trả lời đúng. Chân lý là gì?","o":["Suy luận của con người.","Tri thức đúng, phù hợp với hiện thực khách quan và được thực tiễn kiểm nghiệm.","Tri thức phù hợp với hiện thực.","Là cái được Thượng Đế định sẵn."],"a":1},{"lv":1,"id":"c2-206","ch":2,"n":206,"q":"Khái niệm nào dưới đây chỉ sự phản ánh hiện thực khách quan vào bộ não người một cách tích cực, năng động, sáng tạo dựa trên cơ sở thực tiễn và đưa ra tri thức đúng?","o":["Ý thức.","Nhận thức.","Chân lý.","Thực tiễn."],"a":1},{"lv":2,"id":"c2-207","ch":2,"n":207,"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, mục đích của nhận thức là gì?","o":["Thỏa mãn sự hiểu biết của con người.","Phục vụ nhu cầu thực tiễn của con người.","Phục vụ hoạt động lao động sản xuất.","Giúp con người hiểu bản chất của mình."],"a":1},{"lv":2,"id":"c2-208","ch":2,"n":208,"q":"Theo chủ nghĩa duy vật biện chứng, nguồn gốc \"duy nhất và cuối cùng\" của nhận thức là gì?","o":["Thế giới tâm linh.","Thế giới khách quan.","Thế giới sự vật cảm tính.","Tư duy con người."],"a":1},{"lv":2,"id":"c2-209","ch":2,"n":209,"q":"Nhận thức cảm tính được thực hiện dưới các hình thức nào?","o":["Khái niệm và phán đoán.","Cảm giác, tri giác và khái niệm.","Cảm giác, tri giác và biểu tượng.","Cảm giác, Suy luận, Phán đoán."],"a":2},{"lv":2,"id":"c2-210","ch":2,"n":210,"q":"Sự phản ánh trừu tượng, khái quát những đặc điểm chung, bản chất của các sự vật được gọi là giai đoạn nhận thức nào?","o":["Nhận thức cảm tính","Nhận thức lý tính.","Nhận thức kinh nghiệm.","Nhận thức Khoa học."],"a":1},{"lv":2,"id":"c2-211","ch":2,"n":211,"q":"Tư duy trừu tượng được thể hiện dưới các hình thức cơ bản nào?","o":["Khái niệm, Biểu tượng, Tri giác.","Suy luận, Biểu tượng, Tri giác.","Khái niệm, Suy luận, Phán đoán.","Cảm giác, Suy luận, Phán đoán."],"a":2},{"lv":2,"id":"c2-212","ch":2,"n":212,"q":"Hình thức hoạt động thực tiễn cơ bản nhất quy định đến các hình thức khác là hình thức nào?","o":["Hoạt động sản xuất vật chất.","Hoạt động chính trị xã hội.","Hoạt động quan sát và thực nghiệm khoa học.","Hoạt động tinh thần."],"a":0},{"lv":2,"id":"c2-213","ch":2,"n":213,"q":"Hoạt động thực tiễn là hoạt động chủ yếu, cơ bản dẫn đến sự ra đời của ý thức, vì:","o":["Hoạt động thực tiễn là quá trình con người sử dụng công cụ lao động tác động vào đối tượng hiện thực buộc chúng phải bộc lộ thuộc tính, kết cấu, bản chất… qua đó, con người nhận biết được nó.","Hoạt động thực tiễn là hoạt động cơ bản của con người.","Hoạt động thực tiễn là hoạt động giúp con người nhận thức và cải tạo thế giới.","Hoạt động thực tiễn là quá trình con người cải tạo tự nhiên bắt chúng phải bộc lộ thuộc tính, kết cấu, bản chất... qua đó con người nhận biết nó."],"a":0},{"lv":2,"id":"c2-214","ch":2,"n":214,"q":"Thực tiễn đóng vai trò gì đối với nhận thức?","o":["Là cơ sở, động lực, mục đích của nhận thức và là tiêu chuẩn để kiểm tra chân lý.","Là điểm khởi đầu của nhận thức.","Tồn tại song hành, hỗ trợ quá trình nhận thức.","Là đích đến của nhận thức."],"a":0},{"lv":2,"id":"c2-215","ch":2,"n":215,"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, bệnh giáo điều là do tuyệt đối hóa vai trò của yếu tố nào dưới đây?","o":["Vai trò của cảm tính.","Vai trò của lý tính.","Vai trò của kinh nghiệm.","Vai trò của lý luận."],"a":1},{"lv":2,"id":"c2-216","ch":2,"n":216,"q":"Chọn đáp án đúng điền vào chỗ trống: “Chân lý là những tri thức.... với hiện thực khách quan và được thực tiễn kiểm nghiệm”.","o":["Đầy đủ","Đúng đắn","Hợp lý","Phù hợp"],"a":3},{"lv":2,"id":"c2-217","ch":2,"n":217,"q":"Câu thành ngữ nào dưới đây phản ánh mối quan hệ giữa nhận thức và thực tiễn?","o":["Có công mài sắt, có ngày nên kim.","Nước chảy, đá mòn.","Gieo gió, gặt bão.","Đi một ngày đàng học một sàng khôn."],"a":3},{"lv":2,"id":"c2-218","ch":2,"n":218,"q":"Tiêu chuẩn để kiểm tra chân lý là gì?","o":["Tri thức được nhiều người công nhận.","Tri thức do các thế hệ trước để lại.","Lời nói của các vĩ nhân.","Thực tiễn."],"a":3},{"lv":3,"id":"c2-219","ch":2,"n":219,"q":"Phương án nào dưới đây thể hiện sự vận dụng quan điểm của chủ nghĩa duy vật biện chứng vào giải quyết những vấn đề phức tạp trong cuộc sống?","o":["Suy nghĩ để tìm ra giải pháp nhanh nhất.","Khảo sát thực tiễn và thu thập dữ liệu khách quan về vấn đề đó .","Tham khảo ý kiến và kinh nghiệm của những người đi trước .","Dựa vào sách vở, lý thuyết chuyên môn đã học."],"a":1},{"lv":3,"id":"c2-220","ch":2,"n":220,"q":"Một sinh viên học lý thuyết rất giỏi nhưng khi vận dụng kiến thức đó trong thực tiễn lại lúng túng. Vậy, sinh viên đó đang thiếu điều gì trong quá trình nhận thức theo quan điểm của Triết học Mác - Lênin?","o":["Tư duy trừu tượng.","Mối liên hệ biện chứng.","Mối liên hệ biện chứng giữa nhận thức và thực tiễn.","Tất cả các đáp án."],"a":2},{"lv":3,"id":"c2-221","ch":2,"n":221,"q":"Để tránh \"bệnh giáo điều\", cần thực hiện nguyên tắc nào theo quan điểm của Triết học Mác - Lênin?","o":["Dựa vào sách vở, lý thuyết đã học.","Đối chiếu lý thuyết với thực tiễn để kiểm chứng.","Dựa vào mọi lý thuyết khoa học.","Tất cả các đáp án trên."],"a":1},{"lv":3,"id":"c2-222","ch":2,"n":222,"q":"Việc áp dụng phương pháp \"học đi đôi với hành\" trong thực tiễn là sự vận dụng trực tiếp nguyên lý nào của lý luận nhận thức duy vật biện chứng?","o":["Nhận thức là quá trình phản ánh sáng tạo.","Thực tiễn là cơ sở, động lực và tiêu chuẩn của nhận thức.","Nhận thức bắt đầu từ trực quan sinh động đến tư duy trừu tượng.","Thực tiễn là cơ sở của quá trình nhận thức."],"a":1},{"lv":3,"id":"c2-223","ch":2,"n":223,"q":"Vì sao trong việc xây dựng và hoạch định các chính sách phát triển kinh tế - xã hội của nước ta, không thể chỉ dựa vào ý muốn chủ quan của nhà lãnh đạo? Hãy lựa chọn đáp án phù hợp nhất theo lý luận nhận thức duy vật biện chứng?","o":["Vì ý thức không tác động được vật chất.","Vì nhận thức phải xuất phát từ thực tiễn khách quan.","Vì lãnh đạo thường thiếu kinh nghiệm thực tiễn.","Vì sự tác động của nhiều yếu tố khách quan khác."],"a":1},{"lv":3,"id":"c2-224","ch":2,"n":224,"q":"Vận dụng lý luận nhận thức của chủ nghĩa Mác - Lênin vào quá trình nghiên cứu khoa học của sinh viên: Trong nghiên cứu mà các số liệu thực nghiệm thay đổi so với giả thuyết ban đầu, sinh viên cần phải làm gì?","o":["Giữ nguyên giả thuyết ban đầu vì nó đã được công nhận.","Loại bỏ dữ liệu mới để bảo vệ giả thuyết ban đầu.","Điều chỉnh, bổ sung hoặc thay đổi giả thuyết để phù hợp với thực tiễn.","Dừng nghiên cứu vì đề tài không khả thi."],"a":2},{"lv":3,"id":"c2-225","ch":2,"n":225,"q":"Phương án nào dưới đây khẳng định Lý luận nhận thức duy vật biện chứng có vai trò làm cơ sở phương pháp luận cho hoạt động nhận thức và thực tiễn?","o":["Là cơ sở phương pháp luận của hoạt động nhận thức.","Định hướng hoạt động thực tiễn và khẳng định khả năng nhận thức của con người.","Giúp hình thành tư duy khoa học, biện chứng, và coi thực tiễn là cơ sở, mục đích, tiêu chuẩn kiểm nghiệm chân lý.","Tất cả các đáp án."],"a":3},{"lv":3,"id":"c2-226","ch":2,"n":226,"q":"Để nâng cao hiệu quả trong quá trình học tập, sinh viên cần vận dụng quan điểm về nhận thức của Triết học Mác - Lênin như thế nào?","o":["Học mọi kiến thức và lý thuyết cơ bản mà giáo viên truyền đạt trên lớp.","Học lý thuyết song song với áp dụng vào bài tập và tình huống thực tiễn.","Học lý thuyết song song với học nhiều kiến thức liên nghành khác.","Tất cả các đáp án."],"a":1},{"lv":3,"id":"c2-227","ch":2,"n":227,"q":"Vận dụng quan điểm về nhận thức của Triết học Mác - Lênin trong thực tiễn cuộc sống, việc đưa ra mục tiêu phấn đấu trong tương lai của em, cần dựa trên những căn cứ nào?","o":["Tham khảo kinh nghiệm của những người đi trước.","Dựa vào mong muốn chủ quan của bản thân em.","Dựa vào năng lực của bản thân và phân tích các điều kiện khách quan.","Tất cả các đáp án."],"a":2},{"lv":3,"id":"c2-228","ch":2,"n":228,"q":"Câu nói: “Thất bại là mẹ thành công\" phản ánh nội dung triết học nào trong lý luận nhận thức duy vật biện chứng?","o":["Nhận thức là quá trình đi từ biết đến không biết.","Sai lầm trong nhận thức là một phần tất yếu của quá trình tìm kiếm chân lý.","Chỉ cần thất bại là sẽ có thành công.","Không cần quan tâm đến kết quả, chỉ cần cố gắng."],"a":1},{"lv":4,"id":"c2-229","ch":2,"n":229,"q":"Hãy phân tích mối quan hệ giữa nhận thức cảm tính và nhận thức lý tính để trả lời câu hỏi: “Tại sao nhận thức lý tính cao cấp hơn nhưng lại phụ thuộc vào nhận thức cảm tính”?","o":["Vì lý tính là sự suy luận, cảm tính là sự quan sát.","Vì lý tính khái quát được bản chất, nhưng phải dựa trên dữ liệu từ cảm tính cung cấp.","Vì cảm tính là nhận thức bề ngoài, lý tính là nhận thức cấp độ tư duy.","Vì con người không thể có lý tính nếu không có cảm giác."],"a":1},{"lv":4,"id":"c2-230","ch":2,"n":230,"q":"Tại sao chủ nghĩa duy vật biện chứng khẳng định nhận thức của con người là một quá trình \"vô tận\"?","o":["Vì thế giới vật chất luôn vận động và biến đổi không ngừng.","Vì khả năng của bộ não con người là hạn chế.","Vì chân lý tuyệt đối không tồn tại.","Tất cả các đáp án."],"a":0},{"lv":4,"id":"c2-231","ch":2,"n":231,"q":"Luận điểm nào dưới đây thể hiện rõ bản chất của lý luận nhận thức duy vật biện chứng theo quan điểm của triết học Mác – Lênin?","o":["Nhận thức là quá trình phản ánh tích cực, sáng tạo thế giới khách quan của con người trên cơ sở thực tiễn.","Thực tiễn vừa là nguồn gốc, động lực, mục đích, vừa là tiêu chuẩn kiểm nghiệm chân lý.","Nhận thức phát triển theo con đường từ cảm tính đến lý tính và trở lại thực tiễn.","Tất cả các đáp án."],"a":3},{"lv":4,"id":"c2-232","ch":2,"n":232,"q":"Phân tích vai trò của thực tiễn trong việc khắc phục tính phiến diện của nhận thức?","o":["Thực tiễn buộc con người phải thừa nhận sự thật.","Thực tiễn giúp con người mở rộng phạm vi tiếp xúc, từ đó tổng hợp, làm phong phú và kiểm chứng lại các tri thức đơn lẻ.","Thực tiễn chỉ mang tính chất phụ trợ cho lý luận.","Thực tiễn giúp tư duy của con người rõ ràng hơn."],"a":1},{"lv":4,"id":"c2-233","ch":2,"n":233,"q":"Trong quá trình nhận thức, \"bệnh kinh nghiệm\" và \"bệnh giáo điều\" đều là biểu hiện của tư duy nào?","o":["Tư duy biện chứng.","Tư duy siêu hình, phiến diện.","Tư duy sáng tạo.","Tư duy logic học."],"a":1},{"lv":4,"id":"c2-234","ch":2,"n":234,"q":"Tại sao khẳng định rằng: “chân lý mang tính cụ thể”?","o":["Vì chân lý chỉ đúng trong một thời điểm nhất định.","Vì chân lý phải gắn với không gian, thời gian và điều kiện cụ thể của sự vật.","Vì chân lý là do con người quy định.","Vì chân lý chỉ là sự thỏa thuận giữa các nhà khoa học."],"a":1},{"lv":4,"id":"c2-235","ch":2,"n":235,"q":"Câu nói của Lênin: “Từ trực quan sinh động đến tư duy trừu tượng, từ tư duy trừu tượng đến thực tiễn, đó là con đường biện chứng của nhận thức chân lý” phản ánh điều gì?","o":["Vai trò quyết định của thực tiễn trong quá trình nhận thức và kiểm nghiệm chân lý.","Nhận thức là quá trình thuần túy tư duy logic, không liên quan đến thực tiễn.","Sự phát triển nhận thức của con người phụ thuộc hoàn toàn vào thực tiễn.","Nhận thức do kinh nghiệm được tích lũy từ thực tiễn."],"a":0},{"lv":4,"id":"c2-236","ch":2,"n":236,"q":"Để một giả thuyết khoa học mới được thừa nhận, thì cần phải kiểm chứng bằng thí nghiệm và thực nghiệm. Điều này thể hiện quan điểm nào của triết học Mác - Lênin?","o":["Tuyệt đối hóa vai trò của thực tiễn.","Thực tiễn là tiêu chuẩn của chân lý.","Thực tiễn phụ thuộc vào lý luận.","Nhận thức không cần qua thực tiễn."],"a":1},{"lv":5,"id":"c2-237","ch":2,"n":237,"q":"Phương án nào dưới đây không phản ảnh đúng vai trò của thực tiễn với chân lý?","o":["Thực tiễn là tiêu chuẩn kiểm nghiệm chân lý.","Chính sách cần được triển khai, theo dõi, đánh giá và điều chỉnh dựa trên kết quả thực tế.","Nếu một chủ trương không mang lại hiệu quả thì cần kịp thời bổ sung, hoàn thiện.","Cái gì tồn tại trong thực tiễn thì đều là chân lý."],"a":3},{"lv":5,"id":"c2-238","ch":2,"n":238,"q":"Theo lý luận nhận thức duy vật biện chứng của Chủ nghĩa Mác - Lênin, giải pháp nào dưới đây là tối ưu nhất để phát triển nguồn nhân lực con người trong trường học?","o":["Ưu tiên việc truyền đạt kiến thức lý thuyết tổng hợp trong nhà trường.","Kết hợp giữa giáo dục tri thức, rèn luyện kỹ năng và hoạt động thực tiễn trong nhà trường.","Kết hợp giữa giáo dục đạo đức và ngoại ngữ trong nhà trường.","Đề cao phát triển kỹ năng mềm trong nhà trường."],"a":1},{"lv":5,"id":"c2-239","ch":2,"n":239,"q":"Tại sao phương pháp biện chứng lại được coi là công cụ sắc bén nhất để nhận thức chân lý?","o":["Vì nó nhìn nhận sự vật trong sự vận động, phát triển và mối liên hệ phổ biến.","Vì nó cho phép con người suy đoán mọi thứ.","Vì nó đơn giản và dễ hiểu.","Vì nó là phương pháp cổ xưa nhất."],"a":0},{"lv":6,"id":"c2-240","ch":2,"n":240,"q":"Vận dụng lý luận nhận thức duy vật biện chứng của chủ nghĩa Mác – Lênin, em hãy lựa chọn giải pháp tối ưu nhất giúp sinh viên giữ vững bản lĩnh chính trị, tư tưởng trong giai đoạn hiện nay?","o":["Chỉ tiếp nhận thông tin từ những trang thông tin chính thống, uy tín.","Kết hợp học tập lý luận chính trị với thực tiễn, rèn luyện tư duy khoa học và khả năng phân tích, đánh giá thông tin.","Hạn chế tiếp xúc với các quan điểm khác nhau trong xã hội.","Dựa vào kinh nghiệm cá nhân để hình thành nhận thức chính trị."],"a":1},{"lv":1,"id":"c3-1","ch":3,"n":1,"q":"Theo chủ nghĩa duy vật lịch sử, sản xuất là một loại hình hoạt động đặc trưng của con người và xã hội loài người, bao gồm:","o":["Sản xuất vật chất.","Sản xuất tinh thần.","Sản xuất ra bản thân con người.","Tất cả các đáp án đều đúng."],"a":3},{"lv":1,"id":"c3-2","ch":3,"n":2,"q":"Theo chủ nghĩa duy vật lịch sử, hoạt động nào dưới đây không nằm trong khái niệm sản xuất?","o":["Sản xuất vật chất.","Sản xuất tinh thần.","Sản xuất ra bản thân con người.","Hoạt động tích trữ của cải."],"a":3},{"lv":1,"id":"c3-3","ch":3,"n":3,"q":"Điền từ còn thiếu vào chỗ trống (...) trong câu sau: “...là cơ sở của sự tồn tại và phát triển của xã hội loài người, và xét đến cùng quyết định toàn bộ sự vận động, phát triển của đời sống xã hội”?","o":["Hoạt động tinh thần.","Sản xuất tinh thần.","Hoạt động vật chất.","Sản xuất vật chất."],"a":3},{"lv":1,"id":"c3-4","ch":3,"n":4,"q":"Phương thức sản xuất bao gồm:","o":["Lực lượng sản xuất, quan hệ sản xuất và cơ sở hạ tầng.","Lực lượng sản xuất và quan hệ sản xuất.","Lực lượng sản xuất, quan hệ sản xuất, cơ sở hạ tầng và kiến trúc thượng tầng.","Tất cả các đáp án đều không đúng."],"a":1},{"lv":1,"id":"c3-5","ch":3,"n":5,"q":"Tiêu chuẩn quan trọng nhất để phân biệt các thời đại kinh tế là:","o":["Thể chế chính trị.","Hình thức nhà nước.","Phương thức sản xuất.","Hình thức tôn giáo."],"a":2},{"lv":1,"id":"c3-6","ch":3,"n":6,"q":"Yếu tố nào dưới đây không thuộc phương thức sản xuất?","o":["Lực lượng sản xuất.","Quan hệ xã hội.","Quan hệ sản xuất.","Lực lượng sản xuất và quan hệ sản xuất."],"a":1},{"lv":1,"id":"c3-7","ch":3,"n":7,"q":"Phạm trù thể hiện mối quan hệ giữa con người với tự nhiên trong quá trình sản xuất là:","o":["Lực lượng sản xuất.","Quan hệ sản xuất.","Tư liệu sản xuất.","Phương thức sản xuất."],"a":0},{"lv":1,"id":"c3-8","ch":3,"n":8,"q":"Phạm trù thể hiện mối quan hệ giữa con người với con người trong quá trình sản xuất là:","o":["Lực lượng sản xuất.","Quan hệ sản xuất.","Tư liệu sản xuất.","Phương thức sản xuất."],"a":1},{"lv":1,"id":"c3-9","ch":3,"n":9,"q":"Chọn đáp án đúng điền vào chỗ trống: Theo chủ nghĩa duy vật lịch sử, cơ sở hạ tầng là phương diện … của xã hội.","o":["Kinh tế.","Chính trị.","Xã hội.","Văn hóa."],"a":0},{"lv":1,"id":"c3-10","ch":3,"n":10,"q":"Chọn đáp án đúng điền vào chỗ trống: Theo chủ nghĩa duy vật lịch sử, kiến trúc thượng tầng là phương diện… của xã hội.","o":["Kinh tế.","Chính trị - xã hội.","Sản xuất.","Tiêu dùng."],"a":1},{"lv":1,"id":"c3-11","ch":3,"n":11,"q":"Theo chủ nghĩa duy vật lịch sử, nguyên nhân sâu xa của sự phát triển của các hình thái kinh tế - xã hội trong lịch sử là:","o":["Ý muốn chủ quan của con người.","Sự phát triển của quan hệ sản xuất.","Ý muốn của Thượng Đế.","Sự phát triển của lực lượng sản xuất."],"a":3},{"lv":2,"id":"c3-12","ch":3,"n":12,"q":"Mối quan hệ \"song trùng\" của nền sản xuất vật chất mà C. Mác nhắc đến là quan hệ nào sau đây?","o":["Quan hệ giữa con người với tự nhiên và quan hệ giữa con người với sản phẩm của quá trình sản xuất vật chất.","Quan hệ giữa con người với tự nhiên và quan hệ giữa con người với tư liệu sản xuất.","Quan hệ giữa con người với tự nhiên và quan hệ giữa con người với con người trong quá trình sản xuất vật chất.","Quan hệ giữa người với người trong sản xuất vật chất và quan hệ giai cấp trong xã hội."],"a":2},{"lv":2,"id":"c3-13","ch":3,"n":13,"q":"Trong lực lượng sản xuất, nhân tố hàng đầu giữ vai trò quyết định là?","o":["Người lao động.","Công cụ lao động.","Tư liệu sản xuất.","Tư liệu lao động."],"a":0},{"lv":2,"id":"c3-14","ch":3,"n":14,"q":"Trong nền sản xuất Tư bản chủ nghĩa, bản chất mối quan hệ giữa người lao động với tư liệu sản xuất là gì?","o":["Người lao động làm chủ tư liệu sản xuất.","Người lao động phụ thuộc vào tư liệu sản xuất.","Người lao động và tư liệu sản xuất có quan hệ ngang bằng nhau.","Không có đáp án nào đúng."],"a":1},{"lv":2,"id":"c3-15","ch":3,"n":15,"q":"Trong tư liệu sản xuất, yếu tố nào được coi là yếu tố động nhất, cách mạng nhất?","o":["Người lao động.","Công cụ lao động.","Đối tượng lao động.","Tư liệu lao động."],"a":1},{"lv":2,"id":"c3-16","ch":3,"n":16,"q":"Theo chủ nghĩa duy vật lịch sử, trình độ của lực lượng sản xuất thể hiện ở:","o":["Trình độ công cụ lao động và người lao động.","Trình độ tổ chức và phân công lao động xã hội.","Trình độ ứng dụng khoa học và công nghệ vào sản xuất.","Tất cả các phương án đều đúng."],"a":3},{"lv":2,"id":"c3-17","ch":3,"n":17,"q":"Trong quan hệ sản xuất, quan hệ nào giữ vai trò quyết định?","o":["Quan hệ về sở hữu đối với tư liệu sản xuất.","Quan hệ về tổ chức, quản lý quá trình sản xuất.","Quan hệ về phân phối kết quả của quá trình sản xuất.","Tất cả các phương án đều sai."],"a":0},{"lv":2,"id":"c3-18","ch":3,"n":18,"q":"Sự hình thành, biến đổi và phát triển của quan hệ sản xuất bị quyết định bởi:","o":["Ý chí của con người.","Lực lượng siêu nhiên.","Trình độ phát triển của lực lượng sản xuất.","Trình độ phát triển của kiến trúc thượng tầng."],"a":2},{"lv":2,"id":"c3-19","ch":3,"n":19,"q":"Quy luật xã hội nào được coi là cơ bản nhất và giữ vai trò quyết định đối với sự vận động, phát triển của xã hội?","o":["Quy luật đấu tranh giai cấp.","Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất.","Quy luật cơ sở hạ tầng quyết định kiến trúc thượng tầng.","Quy luật tồn tại xã hội quyết định ý thức xã hội."],"a":1},{"lv":2,"id":"c3-20","ch":3,"n":20,"q":"Nếu quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất, thì:","o":["Thúc đẩy sự phát triển của lực lượng sản xuất.","Kìm hãm sự phát triển của lực lượng sản xuất.","Không thay đổi sự phát triển của lực lượng sản xuất.","Vừa kìm hãm, vừa thúc đẩy sự phát triển của lực lượng sản xuất."],"a":0},{"lv":2,"id":"c3-21","ch":3,"n":21,"q":"Quan hệ sản xuất không phù hợp với trình độ phát triển của lực lượng sản xuất được biểu hiện ở:","o":["Quan hệ sản xuất lỗi thời, lạc hậu hơn.","Quan hệ sản xuất tiến bộ, vượt trước một cách giả tạo.","Xây dựng quan hệ sản xuất thiếu đồng bộ.","Tất cả các đáp án đều đúng."],"a":3},{"lv":2,"id":"c3-22","ch":3,"n":22,"q":"Theo chủ nghĩa duy vật lịch sử, trong cơ sở hạ tầng của xã hội thì yếu tố nào giữ vai trò quyết định?","o":["Quan hệ sản xuất tàn dư.","Quan hệ sản xuất thống trị.","Quan hệ sản xuất mầm mống.","Tất cả các phương án đều đúng."],"a":1},{"lv":2,"id":"c3-23","ch":3,"n":23,"q":"Trong kiến trúc thượng tầng, yếu tố nào thường biến đổi nhanh khi cơ sở hạ tầng thay đổi?","o":["Đạo đức.","Tôn giáo.","Nhà nước.","Tất cả các phương án đều sai."],"a":2},{"lv":2,"id":"c3-24","ch":3,"n":24,"q":"Thực chất của mối quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng là:","o":["Quan hệ giữa đời sống vật chất và đời sống tinh thần của xã hội.","Quan hệ giữa kinh tế và chính trị.","Quan hệ giữa vật chất và tinh thần.","Quan hệ giữa tồn tại xã hội với ý thức xã hội."],"a":3},{"lv":2,"id":"c3-25","ch":3,"n":25,"q":"Chủ nghĩa duy vật lịch sử khẳng định cơ sở hạ tầng quyết định kiến trúc thượng tầng, bởi vì:","o":["Quan hệ vật chất quyết định quan hệ tinh thần và thể chế.","Tính tất yếu kinh tế xét đến cùng quyết định tính tất yếu chính trị - xã hội.","Quan hệ vật chất quyết định quan hệ tinh thần và tính tất yếu kinh tế xét đến cùng quyết định tính tất yếu chính trị - xã hội.","Do vai trò sức mạnh vật chất của bộ máy tổ chức – thể chế."],"a":2},{"lv":2,"id":"c3-26","ch":3,"n":26,"q":"Kiến trúc thượng tầng tác động trở lại cơ sở hạ tầng nhằm:","o":["Củng cố, hoàn thiện và bảo vệ cơ sở hạ tầng sinh ra nó, thực chất là bảo vệ lợi ích kinh tế của giai cấp thống trị.","Ngăn chặn cơ sở hạ tầng mới, xoá bỏ tàn dư cơ sở hạ tầng cũ.","Định hướng, tổ chức, xây dựng chế độ kinh tế.","Tất cả các phương án."],"a":3},{"lv":2,"id":"c3-27","ch":3,"n":27,"q":"Yếu tố nào sau đây không thuộc cấu trúc của hình thái kinh tế - xã hội?","o":["Lực lượng sản xuất.","Quan hệ sản xuất.","Điều kiện tự nhiên.","Kiến trúc thượng tầng."],"a":2},{"lv":2,"id":"c3-28","ch":3,"n":28,"q":"Nhân tố nào trong kiến trúc thượng tầng có tác động trực tiếp nhất và mạnh mẽ nhất tới cơ sở hạ tầng kinh tế của xã hội?","o":["Đạo đức.","Tôn giáo.","Nhà nước.","Giáo hội."],"a":2},{"lv":2,"id":"c3-29","ch":3,"n":29,"q":"Theo chủ nghĩa duy vật lịch sử, sự phát triển của các hình thái kinh tế - xã hội trong lịch sử do yếu tố nào quy định?","o":["Ý muốn chủ quan của con người.","Sự phát triển của quan hệ sản xuất.","Sự phát triển của lực lượng sản xuất.","Tất cả các đáp án đều đúng."],"a":2},{"lv":3,"id":"c3-30","ch":3,"n":30,"q":"Trong thực tiễn đổi mới ở Việt Nam, việc phát triển kinh tế thị trường định hướng xã hội chủ nghĩa phản ánh nguyên lý nào của học thuyết hình thái kinh tế - xã hội?","o":["Quan hệ sản xuất quyết định lực lượng sản xuất.","Lực lượng sản xuất quyết định quan hệ sản xuất.","Ý thức xã hội quyết định tồn tại xã hội.","Chính trị quyết định kinh tế."],"a":1},{"lv":3,"id":"c3-31","ch":3,"n":31,"q":"Khi nghiên cứu sự phát triển của một xã hội, nhà nghiên cứu trước hết cần phải xem xét trình độ công cụ lao động, khoa học - kỹ thuật và năng lực của người lao động. Cách tiếp cận này dựa trên quan điểm nào dưới đây?","o":["Sản xuất vật chất giữ vai trò quyết định đối với đời sống xã hội.","Ý thức xã hội quyết định tồn tại xã hội.","Nhà nước quyết định sự phát triển kinh tế.","Đạo đức quyết định phương thức sản xuất."],"a":0},{"lv":3,"id":"c3-32","ch":3,"n":32,"q":"Khi phân tích sự thay thế phương thức sản xuất phong kiến bằng tư bản chủ nghĩa, theo quan điểm duy vật lịch sử của chủ nghĩa Mác – Lênin, yếu tố nào giữ vai trò quyết định?","o":["Sự phát triển của lực lượng sản xuất, đặc biệt là những biến đổi trong công cụ lao động, kỹ thuật sản xuất và trình độ tổ chức lao động, làm nảy sinh yêu cầu về một quan hệ sản xuất mới phù hợp hơn.","Sự thay đổi trong ý thức xã hội, đặc biệt là sự phát triển của các tư tưởng tiến bộ, quan điểm về tự do cá nhân và quyền kinh doanh trong xã hội tư bản.","Sự biến đổi của kiến trúc thượng tầng chính trị, thông qua các cuộc cách mạng xã hội nhằm thiết lập nhà nước và thể chế phù hợp với giai cấp tư sản.","Sự phát triển của các yếu tố văn hóa, giáo dục và đời sống tinh thần, tạo điều kiện hình thành những giá trị mới thay thế hệ tư tưởng phong kiến."],"a":0},{"lv":3,"id":"c3-33","ch":3,"n":33,"q":"Theo quan điểm duy vật lịch sử của chủ nghĩa Mác – Lênin, nếu một quốc gia phát triển khoa học - công nghệ nhưng quan hệ sản xuất không phù hợp thì hệ quả chủ yếu có thể xảy ra là gì?","o":["Lực lượng sản xuất tiếp tục phát triển mạnh mẽ vì khoa học – công nghệ luôn là yếu tố quyết định duy nhất đối với sự phát triển kinh tế – xã hội.","Sự không phù hợp giữa quan hệ sản xuất và lực lượng sản xuất sẽ tạo ra sự kìm hãm phát triển, làm giảm hiệu quả sử dụng công nghệ và đặt ra yêu cầu thay đổi quan hệ sản xuất cho phù hợp hơn.","Sự phát triển của khoa học – công nghệ sẽ tự động làm thay đổi toàn bộ quan hệ sản xuất mà không cần có sự điều chỉnh về thể chế, quản lý và tổ chức xã hội.","Những hạn chế trong phát triển kinh tế chủ yếu xuất phát từ sự chậm thay đổi của ý thức xã hội, do đó chỉ cần thay đổi nhận thức của con người mà không cần cải biến quan hệ sản xuất."],"a":1},{"lv":3,"id":"c3-34","ch":3,"n":34,"q":"Trong quá trình đẩy mạnh công nghiệp hóa, hiện đại hóa ở Việt Nam, chủ trương ưu tiên phát triển giáo dục, đào tạo và nâng cao chất lượng nguồn nhân lực thể hiện sự vận dụng trực tiếp quy luật nào của chủ nghĩa duy vật lịch sử?","o":["Sự biến đổi của cơ sở hạ tầng tất yếu kéo theo sự cải biến của kiến trúc thượng tầng.","Sự phát triển của nhân tố trung tâm trong lực lượng sản xuất làm nảy sinh yêu cầu khách quan phải hoàn thiện các quan hệ kinh tế tương ứng.","Sự tác động trở lại của kiến trúc thượng tầng là nhân tố quyết định tốc độ phát triển của phương thức sản xuất.","Sự thay đổi của hình thái ý thức xã hội là điều kiện tiên quyết để xuất hiện phương thức sản xuất mới."],"a":1},{"lv":3,"id":"c3-35","ch":3,"n":35,"q":"Theo học thuyết hình thái kinh tế – xã hội của chủ nghĩa duy vật lịch sử, nguyên nhân có tính quy luật chủ yếu dẫn đến sự khủng hoảng và tan rã của mô hình xã hội chủ nghĩa ở Liên Xô là gì?","o":["Sự không phù hợp của quan hệ sản xuất với trình độ phát triển của lực lượng sản xuất, làm mâu thuẫn cơ bản trong phương thức sản xuất trở nên gay gắt và kìm hãm sự phát triển xã hội.","Ý thức xã hội phát triển vượt trước tồn tại xã hội nên quyết định sự biến đổi của phương thức sản xuất.","Tồn tại xã hội hoàn toàn độc lập với ý thức xã hội, do đó sự biến đổi của xã hội không chịu sự tác động của nhân tố tinh thần.","Sự biến đổi của kiến trúc thượng tầng là nguyên nhân quyết định trực tiếp sự thay thế hình thái kinh tế - xã hội."],"a":0},{"lv":3,"id":"c3-36","ch":3,"n":36,"q":"Theo quan điểm của triết học Mác – Lênin về lực lượng sản xuất, nếu một doanh nghiệp đầu tư khoa học - công nghệ hiện đại nhưng không chú trọng đào tạo, nâng cao trình độ cho người lao động thì hệ quả chủ yếu là gì?","o":["Năng suất lao động luôn tăng mạnh nhờ công nghệ hiện đại.","Quan hệ sản xuất tự động trở nên phù hợp với trình độ phát triển của lực lượng sản xuất.","Lực lượng sản xuất không phát huy được đầy đủ tiềm năng do người lao động chưa đáp ứng yêu cầu của công nghệ.","Tồn tại xã hội không còn ảnh hưởng đến ý thức xã hội."],"a":2},{"lv":3,"id":"c3-37","ch":3,"n":37,"q":"Theo quan điểm của triết học Mác – Lênin, việc Việt Nam đẩy mạnh hội nhập kinh tế quốc tế và mở rộng quan hệ hợp tác với các quốc gia để phát triển kinh tế phản ánh luận điểm nào dưới đây?","o":["Ý thức xã hội quyết định sự phát triển của tồn tại xã hội.","Sự phát triển của lực lượng sản xuất đòi hỏi quan hệ sản xuất và các quan hệ kinh tế phải được mở rộng, hoàn thiện cho phù hợp.","Chính trị luôn giữ vai trò quyết định trực tiếp đối với sự phát triển kinh tế.","Văn hóa là nhân tố quyết định sự phát triển của lực lượng sản xuất."],"a":1},{"lv":3,"id":"c3-38","ch":3,"n":38,"q":"Theo quan điểm của triết học Mác – Lênin về mối quan hệ giữa lực lượng sản xuất và quan hệ sản xuất, việc đẩy mạnh hiện đại hóa nông nghiệp làm cho năng suất lao động tăng và trình độ của lực lượng sản xuất được nâng cao. Điều này đặt ra yêu cầu gì đối với quan hệ sản xuất?","o":["Giữ nguyên quan hệ sản xuất hiện có, không cần thay đổi khi lực lượng sản xuất phát triển.","Coi văn hóa là nhân tố quyết định trực tiếp đối với sự phát triển của lực lượng sản xuất.","Xem ý thức xã hội là yếu tố quyết định sự phát triển của lực lượng sản xuất.","Điều chỉnh, hoàn thiện quan hệ sản xuất để bảo đảm sự phù hợp với trình độ phát triển của lực lượng sản xuất."],"a":3},{"lv":3,"id":"c3-39","ch":3,"n":39,"q":"Theo quan điểm của triết học Mác – Lênin về mối quan hệ giữa cơ sở hạ tầng và kiến trúc thượng tầng, việc đổi mới chương trình đào tạo đại học để đáp ứng yêu cầu phát triển nguồn nhân lực trong bối cảnh mới phản ánh nội dung nào dưới đây?","o":["Kiến trúc thượng tầng có tính độc lập tương đối và tác động trở lại cơ sở hạ tầng, góp phần thúc đẩy sự phát triển kinh tế – xã hội.","Lực lượng sản xuất quyết định hoàn toàn sự thay đổi của mọi yếu tố trong đời sống xã hội.","Quan hệ sản xuất quyết định trực tiếp sự phát triển của giáo dục và đào tạo.","Tất cả các đáp án."],"a":0},{"lv":3,"id":"c3-40","ch":3,"n":40,"q":"Trong quá trình phát triển kinh tế, một quốc gia tập trung đổi mới công nghệ, nâng cao trình độ người lao động và cải tiến công cụ sản xuất. Theo quan điểm của triết học Mác – Lênin, quốc gia đó đang tác động chủ yếu đến yếu tố nào của phương thức sản xuất?","o":["Quan hệ sản xuất.","Lực lượng sản xuất.","Kiến trúc thượng tầng.","Quan hệ chính trị - xã hội."],"a":1},{"lv":3,"id":"c3-41","ch":3,"n":41,"q":"Trong bối cảnh cuộc Cách mạng công nghiệp lần thứ tư, sự phát triển của trí tuệ nhân tạo, công nghệ số và tự động hóa làm thay đổi phương thức lao động, công cụ sản xuất và trình độ ứng dụng khoa học – kỹ thuật. Theo quan điểm của chủ nghĩa duy vật lịch sử, sự thay đổi này trước hết biểu hiện sự phát triển của yếu tố nào?","o":["Lực lượng sản xuất.","Quan hệ sản xuất.","Kiến trúc thượng tầng xã hội.","Ý thức xã hội."],"a":0},{"lv":3,"id":"c3-42","ch":3,"n":42,"q":"Trong quá trình phát triển kinh tế - xã hội, một quốc gia tiến hành hoàn thiện hệ thống pháp luật, đổi mới cơ chế quản lý kinh tế và xây dựng các chính sách thúc đẩy các quan hệ sản xuất phát triển. Theo quan điểm của chủ nghĩa duy vật lịch sử, hoạt động này thể hiện luận điểm nào dưới đây?","o":["Kiến trúc thượng tầng tác động trở lại cơ sở hạ tầng.","Cơ sở hạ tầng quyết định kiến trúc thượng tầng.","Kiến trúc thượng tầng giữ vai trò quyết định đối với cơ sở hạ tầng.","Ý thức xã hội quyết định sự vận động của đời sống kinh tế."],"a":0},{"lv":3,"id":"c3-43","ch":3,"n":43,"q":"Trong quá trình phát triển xã hội, khi cơ cấu kinh tế và các quan hệ sản xuất có sự biến đổi, kéo theo sự thay đổi của bộ máy nhà nước, hệ thống pháp luật và các quan điểm chính trị. Theo quan điểm của chủ nghĩa duy vật lịch sử, nguyên nhân sâu xa của sự biến đổi trong kiến trúc thượng tầng là gì?","o":["Sự biến đổi của cơ sở hạ tầng.","Sự thay đổi trong nhận thức, tư tưởng của cá nhân.","Sự tác động ngẫu nhiên của các sự kiện lịch sử.","Sự quyết định của các yếu tố tinh thần đối với đời sống xã hội."],"a":0},{"lv":3,"id":"c3-44","ch":3,"n":44,"q":"Trong quá trình phát triển kinh tế - xã hội, một quốc gia ban hành hệ thống pháp luật và chính sách quản lý không còn phù hợp với cơ cấu kinh tế hiện có, làm cản trở hoạt động sản xuất, kinh doanh và sự phát triển của xã hội. Theo quan điểm của chủ nghĩa duy vật lịch sử, tình huống trên phản ánh luận điểm nào dưới đây?.","o":["Kiến trúc thượng tầng cần phù hợp với cơ sở hạ tầng để thúc đẩy sự phát triển của xã hội.","Kiến trúc thượng tầng giữ vai trò quyết định đối với cơ sở hạ tầng.","Cơ sở hạ tầng hoàn toàn phụ thuộc vào kiến trúc thượng tầng.","Cơ sở hạ tầng và kiến trúc thượng tầng tồn tại độc lập, không tác động lẫn nhau."],"a":0},{"lv":3,"id":"c3-45","ch":3,"n":45,"q":"Trong quá trình hội nhập quốc tế, Việt Nam vừa phát triển nền kinh tế thị trường định hướng xã hội chủ nghĩa, vừa xây dựng và hoàn thiện Nhà nước pháp quyền xã hội chủ nghĩa. Theo quan điểm của chủ nghĩa duy vật lịch sử, ý nghĩa phương pháp luận quan trọng nhất của chủ trương này là gì?","o":["Chỉ ưu tiên phát triển kinh tế, các lĩnh vực khác sẽ tự phát triển.","Chỉ cần hoàn thiện hệ thống chính trị là đủ để phát triển đất nước.","Phải đồng thời phát triển cơ sở hạ tầng và xây dựng kiến trúc thượng tầng phù hợp, phát huy vai trò định hướng, quản lý và thúc đẩy sự phát triển kinh tế - xã hội.","Kiến trúc thượng tầng có thể thay thế hoàn toàn vai trò của cơ sở hạ tầng."],"a":2},{"lv":3,"id":"c3-46","ch":3,"n":46,"q":"Nhà nước ban hành chính sách bảo tồn và phát huy các giá trị văn hóa dân tộc nhằm góp phần phát triển du lịch, nâng cao đời sống nhân dân và thúc đẩy phát triển kinh tế - xã hội. Theo quan điểm của chủ nghĩa duy vật lịch sử, tình huống trên phản ánh nội triết học nào dưới đây?","o":["Kiến trúc thượng tầng có tính độc lập tương đối và tác động trở lại cơ sở hạ tầng theo hướng thúc đẩy sự phát triển kinh tế - xã hội.","Lực lượng sản xuất là nhân tố quyết định trực tiếp sự phát triển của kiến trúc thượng tầng.","Chính trị là nhân tố quyết định sự phát triển của nền kinh tế.","Văn hóa giữ vai trò quyết định đối với sự phát triển của cơ sở hạ tầng."],"a":0},{"lv":3,"id":"c3-47","ch":3,"n":47,"q":"Trong quá trình đổi mới đất nước, việc đổi mới tư duy lý luận, bổ sung và phát triển các quan điểm, chủ trương nhằm đáp ứng yêu cầu phát triển kinh tế - xã hội được xem là một nhiệm vụ chính trị quan trọng của Đảng. Theo quan điểm của Triết học Mác - Lênin, tình huống trên phản ánh nội dung nào dưới đây?","o":["Lực lượng sản xuất quyết định sự biến đổi của quan hệ sản xuất.","Ý thức xã hội quyết định sự tồn tại và phát triển của xã hội.","Chính trị quyết định hoàn toàn sự phát triển của kinh tế.","Kiến trúc thượng tầng phải được điều chỉnh, đổi mới phù hợp với sự biến đổi của cơ sở hạ tầng."],"a":3},{"lv":3,"id":"c3-48","ch":3,"n":48,"q":"Khi nghiên cứu về sự phát triển của các xã hội trong lịch sử, chủ nghĩa Mác - Lênin khẳng định rằng: “Mỗi hình thái kinh tế - xã hội có sự thống nhất giữa lực lượng sản xuất, quan hệ sản xuất và kiến trúc thượng tầng”. Vậy, ý nghĩa phương pháp luận quan trọng nhất của quan điểm này là gì?","o":["Có thể áp dụng một mô hình phát triển xã hội giống nhau cho mọi quốc gia.","Cần xem xét sự phát triển xã hội trong tính lịch sử - cụ thể, dựa trên điều kiện kinh tế, xã hội của từng quốc gia.","Chỉ cần thay đổi kiến trúc thượng tầng là có thể thay đổi toàn bộ xã hội.","Sự phát triển xã hội hoàn toàn phụ thuộc vào yếu tố tinh thần."],"a":1},{"lv":3,"id":"c3-49","ch":3,"n":49,"q":"Có ý kiến cho rằng: “Muốn xây dựng một xã hội phát triển chỉ cần thay đổi hệ thống chính trị và pháp luật, không cần quan tâm đến trình độ phát triển của lực lượng sản xuất”. Theo học thuyết hình thái kinh tế - xã hội, nhận định trên là đúng hay sai?","o":["Đúng, vì kiến trúc thượng tầng quyết định toàn bộ sự phát triển xã hội.","Đúng, vì ý thức và chính trị có thể thay thế vai trò của kinh tế.","Sai, vì sự phát triển xã hội trước hết phải dựa trên sự phát triển của phương thức sản xuất, trong đó lực lượng sản xuất giữ vai trò quyết định.","Sai, vì quan hệ sản xuất không có vai trò trong sự phát triển xã hội."],"a":2},{"lv":3,"id":"c3-50","ch":3,"n":50,"q":"Ý nghĩa khoa học của học thuyết hình thái kinh tế - xã hội được thể hiện rõ nét nhất ở luận điểm nào sau đây?","o":["Chứng minh rằng mọi quốc gia đều phải trải qua các hình thái kinh tế - xã hội theo một trình tự hoàn toàn giống nhau.","Khẳng định sự phát triển xã hội là quá trình ngẫu nhiên, phụ thuộc chủ yếu vào ý chí của các nhà lãnh đạo.","Chỉ ra rằng sự phát triển của xã hội loài người là một quá trình lịch sử - tự nhiên, chịu sự chi phối của những quy luật khách quan.","Cho rằng các yếu tố chính trị và tư tưởng không có bất kỳ ảnh hưởng nào đến sự vận động của xã hội."],"a":2},{"lv":3,"id":"c3-51","ch":3,"n":51,"q":"Thực tiễn nghiên cứu và vận dụng học thuyết hình thái kinh tế - xã hội của chủ nghĩa Mác - Lênin vào quá trình phát triển của một quốc gia cần phải dựa trên yếu tố cơ bản nào?","o":["Có thể áp dụng nguyên mẫu mô hình phát triển của một quốc gia khác vì các hình thái kinh tế - xã hội đều vận động theo cùng một cách thức.","Cần thay đổi kiến trúc thượng tầng chính trị là có thể tạo ra sự thay đổi căn bản của toàn bộ đời sống xã hội.","Cần xuất phát từ điều kiện lịch sử cụ thể, trình độ phát triển của lực lượng sản xuất và yêu cầu hoàn thiện quan hệ sản xuất phù hợp.","Vì kinh tế giữ vai trò quyết định nên có thể xem nhẹ vai trò của khoa học, văn hóa, chính trị và pháp luật."],"a":2},{"lv":3,"id":"c3-52","ch":3,"n":52,"q":"Một quốc gia áp dụng nguyên mẫu mô hình phát triển kinh tế - xã hội của một nước khác mà không xem xét đến điều kiện lịch sử, trình độ phát triển kinh tế và đặc điểm văn hóa của mình. Theo học thuyết hình thái kinh tế - xã hội, hạn chế cơ bản của cách tiếp cận này là gì?","o":["Chưa nhận thức đầy đủ tính phổ biến của các quy luật phát triển xã hội nên không thể áp dụng kinh nghiệm quốc tế.","Vi phạm nguyên tắc phương pháp luận về việc phải xuất phát từ điều kiện lịch sử - cụ thể và sự phù hợp giữa quan hệ sản xuất với lực lượng sản xuất.","Phủ nhận hoàn toàn vai trò của kiến trúc thượng tầng trong sự phát triển của xã hội.","Không đánh giá đúng vai trò quyết định tuyệt đối của chính trị đối với sự phát triển kinh tế."],"a":1},{"lv":4,"id":"c3-53","ch":3,"n":53,"q":"Có quan điểm cho rằng: “Trong xã hội hiện đại, sự phát triển của khoa học, công nghệ và tri thức đã làm cho sản xuất vật chất không còn giữ vai trò quyết định đối với sự tồn tại và phát triển của xã hội.” Theo quan điểm của chủ nghĩa duy vật lịch sử, đánh giá nào sau đây là phù hợp nhất?","o":["Đồng ý, vì tri thức và khoa học hiện nay đã trở thành yếu tố quyết định sự phát triển xã hội.","Đồng ý, vì đời sống tinh thần ngày càng phát triển nên có thể thay thế vai trò của sản xuất vật chất.","Không đồng ý, vì sản xuất vật chất là cơ sở của sự tồn tại xã hội, quyết định sự hình thành và phát triển của các quan hệ xã hội; khoa học, công nghệ chỉ phát huy vai trò thông qua quá trình sản xuất vật chất.","Không đồng ý, vì sản xuất vật chất chỉ ảnh hưởng đến kinh tế, không tác động đến chính trị, văn hóa và các lĩnh vực xã hội khác."],"a":2},{"lv":4,"id":"c3-54","ch":3,"n":54,"q":"Một nhà nghiên cứu nhận định: “Sự thay đổi của phương thức sản xuất trong lịch sử chủ yếu bắt nguồn từ sự thay đổi của quan hệ sở hữu; khi quan hệ sở hữu thay đổi thì phương thức sản xuất tất yếu thay đổi theo.” Nhận định trên được đánh giá như thế nào theo quan điểm của chủ nghĩa duy vật lịch sử?","o":["Đúng, vì quan hệ sở hữu là toàn bộ nội dung của quan hệ sản xuất và quyết định trực tiếp phương thức sản xuất.","Đúng, vì quan hệ sản xuất quyết định sự phát triển của lực lượng sản xuất trong mọi điều kiện lịch sử.","Chưa chính xác, vì sự biến đổi của phương thức sản xuất bắt nguồn từ sự phát triển của lực lượng sản xuất, làm nảy sinh yêu cầu điều chỉnh quan hệ sản xuất; trong đó quan hệ sở hữu chỉ là một bộ phận của quan hệ sản xuất.","Sai, vì quan hệ sản xuất không có bất kỳ vai trò nào trong sự vận động của phương thức sản xuất."],"a":2},{"lv":4,"id":"c3-55","ch":3,"n":55,"q":"Theo chủ nghĩa duy vật lịch sử, nhận định nào sau đây đúng nhất về vai trò của công cụ lao động trong lực lượng sản xuất?","o":["Công cụ lao động là yếu tố quan trọng nhất, quyết định trực tiếp toàn bộ sự phát triển của lực lượng sản xuất.","Công cụ lao động là tiêu chuẩn cơ bản nhất để đánh giá sự phát triển của xã hội vì nó quyết định phương thức sản xuất.","Công cụ lao động là yếu tố động của lực lượng sản xuất, phản ánh trình độ chinh phục tự nhiên của con người nhưng chỉ phát huy tác dụng thông qua người lao động.","Công cụ lao động giữ vai trò trung gian trong sản xuất, còn sự phát triển của lực lượng sản xuất chủ yếu phụ thuộc vào quan hệ sản xuất."],"a":2},{"lv":4,"id":"c3-56","ch":3,"n":56,"q":"Trong bối cảnh toàn cầu hóa kinh tế, một quốc gia tiếp nhận nhanh công nghệ, vốn và phương thức quản lý mới nhưng duy trì cơ chế kinh tế không còn phù hợp. Theo quan điểm của chủ nghĩa duy vật lịch sử, vấn đề đặt ra là gì?","o":["Cần thay đổi toàn bộ hệ tư tưởng xã hội để thích ứng với toàn cầu hóa.","Cần điều chỉnh quan hệ sản xuất để phù hợp với sự phát triển của lực lượng sản xuất do toàn cầu hóa thúc đẩy.","Cần ưu tiên phát triển kiến trúc thượng tầng vì đây là yếu tố quyết định sự vận động của kinh tế.","Cần loại bỏ vai trò của quan hệ sản xuất vì toàn cầu hóa làm cho kinh tế vận động tự do hoàn toàn."],"a":1},{"lv":4,"id":"c3-57","ch":3,"n":57,"q":"Động lực sâu xa của sự thay thế các hình thái kinh tế – xã hội trong lịch sử là gì?","o":["Sự thay đổi của các tư tưởng chính trị.","Mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất.","Sự thay đổi của phong tục, tập quán xã hội.","Sự thay đổi trong nhận thức của con người."],"a":1},{"lv":4,"id":"c3-58","ch":3,"n":58,"q":"Có ý kiến cho rằng: \"Chỉ cần thay đổi kiến trúc thượng tầng thì nền kinh tế sẽ phát triển, không phụ thuộc vào cơ sở hạ tầng.\" Theo chủ nghĩa duy vật lịch sử, đánh giá nào dưới đây là đúng nhất?","o":["Đồng ý, vì kiến trúc thượng tầng quyết định trực tiếp cơ sở hạ tầng.","Đồng ý, vì thay đổi kiến trúc thượng tầng luôn làm kinh tế phát triển.","Không đồng ý, vì kiến trúc thượng tầng chỉ phản ánh cơ sở hạ tầng.","Không đồng ý, vì kiến trúc thượng tầng chỉ tác động trở lại cơ sở hạ tầng và chỉ phát huy hiệu quả khi phù hợp với cơ sở hạ tầng."],"a":3},{"lv":4,"id":"c3-59","ch":3,"n":59,"q":"Có quan điểm cho rằng: \"Sự chuyển biến từ chủ nghĩa tư bản lên chủ nghĩa xã hội chủ yếu là kết quả của ý chí chính trị và cải cách thể chế.\" Theo chủ nghĩa duy vật lịch sử, đánh giá nào dưới đây là phù hợp nhất?","o":["Không đồng ý, vì sự thay thế chủ nghĩa tư bản chỉ trở thành tất yếu khi mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất phát triển đến trình độ nhất định.","Đồng ý, vì ý chí chính trị là nhân tố quyết định sự thay đổi của mọi hình thái kinh tế – xã hội.","Đồng ý, vì cải cách thể chế có thể thay thế quy luật phát triển khách quan của lịch sử.","Không đồng ý, vì mọi biến đổi xã hội chỉ do đấu tranh giai cấp quyết định."],"a":0},{"lv":4,"id":"c3-60","ch":3,"n":60,"q":"Nhận định nào dưới đây phù hợp nhất với quan điểm của chủ nghĩa duy vật lịch sử về vai trò của chính trị đối với kinh tế?","o":["Chính trị có thể thay thế vai trò trò quyết định của cơ sở hạ tầng đối với sự phát triển kinh tế.","Chính trị là yếu tố độc lập, không chịu sự quy định của cơ sở hạ tầng.","Chính trị thuộc kiến trúc thượng tầng, chịu sự quy định của cơ sở hạ tầng nhưng có tính độc lập tương đối và tác động trở lại sự phát triển kinh tế.","Chính trị chỉ phản ánh sự phát triển kinh tế, không có khả năng tác động trở lại."],"a":2},{"lv":4,"id":"c3-61","ch":3,"n":61,"q":"Có ý kiến cho rằng: \"Chỉ cần nắm quyền lực chính trị thì có thể tạo ra mọi biến đổi kinh tế, bất kể điều kiện kinh tế hiện có.\" Theo chủ nghĩa duy vật lịch sử, đánh giá nào đúng nhất?","o":["Đồng ý, vì chính trị quyết định trực tiếp sự phát triển kinh tế.","Không đồng ý, vì chính trị chỉ phát huy vai trò khi phù hợp với cơ sở hạ tầng; nó tác động trở lại nhưng không thay thế vai trò quyết định của cơ sở hạ tầng.","Đồng ý, vì kiến trúc thượng tầng luôn giữ vai trò quyết định đối với cơ sở hạ tầng.","Không đồng ý, vì chính trị không có ảnh hưởng đến sự phát triển kinh tế."],"a":1},{"lv":4,"id":"c3-62","ch":3,"n":62,"q":"Theo chủ nghĩa duy vật lịch sử, nhận định nào giải thích đúng nhất cơ sở lý luận của những thành tựu trong công cuộc đổi mới ở Việt Nam?","o":["Thành công chủ yếu do thay đổi hệ tư tưởng xã hội.","Thành công là kết quả của việc chính trị giữ vai trò quyết định tuyệt đối đối với kinh tế.","Thành công gắn với việc điều chỉnh quan hệ sản xuất phù hợp hơn với trình độ phát triển của lực lượng sản xuất.","Thành công chủ yếu do văn hóa trở thành nhân tố quyết định sự phát triển kinh tế."],"a":2},{"lv":4,"id":"c3-63","ch":3,"n":63,"q":"Khi nghiên cứu một hình thái kinh tế - xã hội, yếu tố nào sau đây cần được xem là cơ sở để giải thích bản chất và sự vận động của nó theo quan điểm của triết học Mác - Lênin?","o":["Hệ thống quan điểm tư tưởng chi phối đời sống xã hội.","Các thiết chế chính trị và tổ chức quản lý xã hội.","Phương thức sản xuất với sự thống nhất giữa lực lượng sản xuất và quan hệ sản xuất.","Các đặc điểm văn hóa, tâm lý và truyền thống của cộng đồng."],"a":2},{"lv":5,"id":"c3-64","ch":3,"n":64,"q":"Trong quá trình phát triển xã hội, vì sao không thể đồng nhất sự phát triển của lực lượng sản xuất với sự phát triển của phương thức sản xuất?","o":["Vì lực lượng sản xuất chỉ phản ánh quan hệ giữa con người với tự nhiên, còn phương thức sản xuất chỉ phản ánh quan hệ giữa con người với con người.","Vì lực lượng sản xuất là một bộ phận của phương thức sản xuất, còn phương thức sản xuất bao gồm cả lực lượng sản xuất và quan hệ sản xuất.","Vì phương thức sản xuất chỉ phụ thuộc vào ý thức xã hội của con người.","Vì lực lượng sản xuất không có vai trò quyết định trong sự vận động của xã hội."],"a":1},{"lv":5,"id":"c3-65","ch":3,"n":65,"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nhận định nào sau đây là đúng nhất về vai trò quyết định của phương thức sản xuất đối với sự phát triển xã hội?","o":["Phương thức sản xuất quyết định toàn bộ mọi biểu hiện của đời sống xã hội một cách trực tiếp và tức thời.","Phương thức sản xuất quyết định sự vận động và biến đổi của xã hội trong tính tổng thể, nhưng sự tác động đó thông qua các quan hệ xã hội khác nhau.","Quan hệ sản xuất quyết định hoàn toàn sự phát triển của lực lượng sản xuất vì nó quy định mục đích của sản xuất.","Lực lượng sản xuất chỉ giữ vai trò quyết định trong xã hội nguyên thủy, còn các xã hội sau do kiến trúc thượng tầng quyết định."],"a":1},{"lv":5,"id":"c3-66","ch":3,"n":66,"q":"Theo phương pháp luận của chủ nghĩa duy vật lịch sử, sai lầm nào cần tránh khi vận dụng quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất?","o":["Điều chỉnh quan hệ sản xuất nhằm khai thác tiềm năng phát triển của lực lượng sản xuất trên cơ sở những điều kiện lịch sử - xã hội cụ thể.","Thừa nhận khả năng quan hệ sản xuất có thể tác động thúc đẩy hoặc kìm hãm sự phát triển của lực lượng sản xuất tùy thuộc vào mức độ phù hợp.","Thiết lập một kiểu quan hệ sản xuất mới với trình độ phát triển cao hơn nhằm tạo ra sự phát triển tất yếu của lực lượng sản xuất, bất chấp điều kiện vật chất hiện có.","Nhận thức sự phù hợp giữa quan hệ sản xuất và lực lượng sản xuất là một quá trình vận động, điều chỉnh thường xuyên trong lịch sử."],"a":2},{"lv":5,"id":"c3-67","ch":3,"n":67,"q":"Sai lầm lý luận nào xảy ra khi tuyệt đối hóa vai trò của kiến trúc thượng tầng?","o":["Chủ nghĩa duy vật kinh tế giản đơn.","Chủ nghĩa duy tâm lịch sử, coi tư tưởng chính trị quyết định sự vận động xã hội.","Quan điểm duy vật biện chứng.","Quan điểm lịch sử cụ thể."],"a":1},{"lv":5,"id":"c3-68","ch":3,"n":68,"q":"Theo phương pháp luận của chủ nghĩa duy vật lịch sử, khi vận dụng nguyên lý về mối quan hệ giữa cơ sở hạ tầng và kiến trúc thượng tầng để phân tích thực tiễn xã hội, quan điểm nào sau đây là phù hợp nhất?","o":["Coi cơ sở hạ tầng giữ vai trò quyết định đối với kiến trúc thượng tầng, vì vậy sự biến đổi của các quan hệ kinh tế là điều kiện đủ để giải thích toàn bộ sự vận động của đời sống xã hội.","Coi kiến trúc thượng tầng có khả năng định hướng và điều chỉnh các quan hệ xã hội, do đó trong nhiều trường hợp có thể giữ vai trò quyết định đối với sự biến đổi của cơ sở hạ tầng.","Xem xét sự quy định của cơ sở hạ tầng đối với kiến trúc thượng tầng trong tính biện chứng với sự tác động trở lại của kiến trúc thượng tầng, đồng thời đặt quá trình này trong những điều kiện lịch sử - xã hội cụ thể.","Coi cơ sở hạ tầng và kiến trúc thượng tầng là hai phương diện có vai trò tương đương trong việc quyết định sự vận động của hình thái kinh tế – xã hội, vì cả hai đều phản ánh cấu trúc của xã hội."],"a":2},{"lv":5,"id":"c3-69","ch":3,"n":69,"q":"Trong việc vận dụng học thuyết hình thái kinh tế – xã hội của chủ nghĩa Mác – Lênin vào thực tiễn, sai lầm nghiêm trọng nhất là gì?","o":["Nhận thức các quy luật xã hội trong điều kiện lịch sử cụ thể.","Kết hợp giữa phát triển kinh tế với phát triển chính trị, văn hóa, xã hội.","Coi quy luật phát triển xã hội là bất biến, áp dụng một mô hình phát triển giống nhau cho mọi quốc gia.","Xuất phát từ thực tiễn để điều chỉnh chính sách phát triển."],"a":2},{"lv":5,"id":"c3-70","ch":3,"n":70,"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nhận định nào dưới đây phản ánh đúng nhất vì sao quan hệ sản xuất được xem là bộ phận cốt lõi của cơ sở hạ tầng?","o":["Vì quan hệ sản xuất là yếu tố quyết định trực tiếp sự phát triển của lực lượng sản xuất và quy định toàn bộ kết cấu xã hội.","Vì quan hệ sản xuất phản ánh quan hệ kinh tế cơ bản giữa người với người trong quá trình sản xuất, là cơ sở hình thành nền tảng kinh tế của một xã hội nhất định.","Vì quan hệ sản xuất bao gồm các quan hệ về sở hữu, quản lý và phân phối nên có khả năng thay thế vai trò của lực lượng sản xuất trong sự phát triển phương thức sản xuất.","Vì quan hệ sản xuất là biểu hiện kinh tế được thể chế hóa trong pháp luật và thiết chế chính trị, do đó thuộc về kiến trúc thượng tầng của xã hội."],"a":1},{"lv":6,"id":"c3-71","ch":3,"n":71,"q":"Nếu được giao xây dựng mô hình phát triển kinh tế - xã hội bền vững trong bối cảnh Cách mạng công nghiệp lần thứ tư, phương án nào thể hiện đúng phương pháp luận của học thuyết hình thái kinh tế - xã hội theo quan điểm của chủ nghĩa duy vật lịch sử?","o":["Ưu tiên phát triển khoa học – công nghệ hiện đại như yếu tố quyết định duy nhất của sự phát triển xã hội.","Kết hợp phát triển lực lượng sản xuất hiện đại với từng bước hoàn thiện quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất.","Vận dụng nguyên mẫu mô hình phát triển của các quốc gia tiên tiến để rút ngắn quá trình phát triển.","Tập trung tối đa vào tăng trưởng kinh tế trước mắt, sau đó mới giải quyết các vấn đề xã hội."],"a":1},{"lv":6,"id":"c3-72","ch":3,"n":72,"q":"Trong quá trình hoàn thiện nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam, chính sách nào phản ánh đúng nhất việc vận dụng quy luật quan hệ sản xuất phải phù hợp với trình độ phát triển của lực lượng sản xuất?","o":["Mở rộng sở hữu nhà nước trong mọi lĩnh vực để bảo đảm định hướng xã hội chủ nghĩa.","Ưu tiên phát triển lực lượng sản xuất, còn quan hệ sản xuất sẽ có cơ chế tự thích ứng mà không cần cải cách thể chế.","Hoàn thiện thể chế nhằm đa dạng hóa hình thức sở hữu, phát triển các thành phần kinh tế và điều chỉnh quan hệ sản xuất theo yêu cầu phát triển lực lượng sản xuất.","Duy trì ổn định quan hệ sản xuất hiện hành nhằm tránh biến động kinh tế - xã hội."],"a":2},{"lv":6,"id":"c3-73","ch":3,"n":73,"q":"Theo học thuyết hình thái kinh tế - xã hội, nếu được giao dự báo xu hướng phát triển của Việt Nam đến năm 2045, nhận định nào dưới đây có cơ sở lý luận vững chắc nhất?","o":["Phát triển đồng bộ lực lượng sản xuất, hoàn thiện quan hệ sản xuất và đổi mới kiến trúc thượng tầng phù hợp với yêu cầu của thời kỳ quá độ lên chủ nghĩa xã hội.","Đẩy nhanh phát triển lực lượng sản xuất, đồng thời điều chỉnh quan hệ sản xuất khi xuất hiện mâu thuẫn lớn làm cản trở tăng trưởng.","Ưu tiên hoàn thiện kiến trúc thượng tầng nhằm tạo động lực dẫn dắt sự phát triển của lực lượng sản xuất và quan hệ sản xuất.","Tập trung hoàn thiện quan hệ sản xuất trước để định hướng sự phát triển của lực lượng sản xuất trong giai đoạn tiếp theo."],"a":0},{"lv":6,"id":"c3-74","ch":3,"n":74,"q":"Nếu được giao nhiệm vụ là thành viên Ban Chỉ đạo Chuyển đổi số quốc gia, mô hình nào dưới đây phản ánh đúng nhất việc vận dụng học thuyết hình thái kinh tế – xã hội vào quá trình chuyển đổi số ở Việt Nam?","o":["Ưu tiên phát triển lực lượng sản xuất số thông qua đầu tư công nghệ và hạ tầng; việc hoàn thiện quan hệ sản xuất được thực hiện theo tiến độ phát triển kinh tế.","Kết hợp cải cách thể chế, phát triển nguồn nhân lực và ứng dụng công nghệ số nhằm tạo động lực thúc đẩy tăng trưởng kinh tế.","Phân tích điều kiện lịch sử – cụ thể, phát triển đồng bộ lực lượng sản xuất số, hoàn thiện quan hệ sản xuất và đổi mới kiến trúc thượng tầng trên cơ sở tổng kết thực tiễn.","Tiếp thu mô hình chuyển đổi số của các quốc gia phát triển, đồng thời điều chỉnh chính sách để phù hợp với điều kiện kinh tế trong nước."],"a":2},{"lv":1,"id":"c3-75","ch":3,"n":75,"q":"Sự phân chia giai cấp trong xã hội bắt đầu từ hình thái kinh tế - xã hội nào?","o":["Cộng sản nguyên thủy.","Chiếm hữu nô lệ.","Phong kiến.","Tư bản chủ nghĩa."],"a":1},{"lv":1,"id":"c3-76","ch":3,"n":76,"q":"Nguyên nhân quyết định trực tiếp của sự ra đời giai cấp trong lịch sử xã hội là gì?","o":["Do chiến tranh, thần linh, Thượng Đế tạo ra.","Do sự chênh lệch về khả năng của các tập đoàn người.","Do sự xuất hiện chế độ tư hữu về tư liệu sản xuất.","Do sự phân hóa giữa giàu và nghèo trong xã hội."],"a":2},{"lv":1,"id":"c3-77","ch":3,"n":77,"q":"Cơ sở hình thành và phân chia giai cấp trong xã hội là do nguyên nhân nào?","o":["Chiếm hữu tư nhân về tư liệu sản xuất.","Chiến tranh của các bộ lạc.","Sản xuất nông nghiệp phát triển.","Tất cả các đáp án đều đúng."],"a":0},{"lv":1,"id":"c3-78","ch":3,"n":78,"q":"“Cuộc đấu tranh của quần chúng lao động bị áp bức, bóc lột chống lại giai cấp áp bức, bóc lột nhằm lật đổ ách thống trị của chúng” thuộc khái niệm nào dưới đây?","o":["Cải cách xã hội.","Đảo chính.","Đấu tranh giai cấp.","Liên minh giai cấp."],"a":2},{"lv":1,"id":"c3-79","ch":3,"n":79,"q":"Hình thức cộng đồng người nào hình thành khi xã hội bắt đầu có sự phân chia thành giai cấp?","o":["Thị tộc","Bộ lạc","Bộ tộc","Dân tộc"],"a":2},{"lv":1,"id":"c3-80","ch":3,"n":80,"q":"Sự hình thành dân tộc phổ biến trong lịch sử gắn với xã hội nào?","o":["Xã hội phong kiến.","Sự hình thành và phát triển của chủ nghĩa tư bản.","Phong trào công nhân và cách mạng vô sản.","Xã hội cổ đại."],"a":1},{"lv":1,"id":"c3-81","ch":3,"n":81,"q":"Chọn đáp án đúng điền vào chỗ trống:… là một cộng đồng người ổn định được hình thành trong lịch sử trên cơ sở một lãnh thổ thống nhất, một ngôn ngữ thống nhất, một nền kinh tế thống nhất, một nền văn hóa và tâm lý, tính cách thống nhất, với một nhà nước và pháp luật thống nhất.","o":["Thị tộc","Bộ lạc","Bộ tộc","Dân tộc"],"a":3},{"lv":1,"id":"c3-82","ch":3,"n":82,"q":"Đặc điểm hình thành Dân tộc ở Phương Tây:","o":["Giống như các dân tộc ở Phương Đông.","Gắn liền với sự hình thành và phát triển của chủ nghĩa tư bản.","Ra đời từ thời kỳ nguyên thủy.","Ra đời cùng với thời kỳ phong kiến."],"a":1},{"lv":1,"id":"c3-83","ch":3,"n":83,"q":"Đặc điểm hình thành Dân tộc ở Phương Đông:","o":["Ra đời sớm hơn ở Phương Tây và không gắn với sự ra đời của chủ nghĩa tư bản.","Ra đời giống như các dân tộc ở Phương Tây.","Ra đời từ thời kỳ nguyên thủy.","Ra đời cùng với sự hình thành và phát triển của chủ nghĩa tư bản."],"a":0},{"lv":2,"id":"c3-84","ch":3,"n":84,"q":"Đâu không phải là đặc trưng cơ bản của một giai cấp?","o":["Giai cấp là những tập đoàn người có địa vị kinh tế - xã hội khác nhau trong một hệ thống sản xuất xã hội nhất định trong lịch sử.","Dấu hiệu chủ yếu quy đinh địa vị kinh tế-xã hội của các giai cấp là các mối quan hệ kinh tế - vật chất giữa các tập đoàn người trong phương thức sản xuất.","Thực chất của quan hệ giai cấp là quan hệ giữa bóc lột và bị bóc lột.","Giai cấp là những tập đoàn người khác nhau về sở thích, ngôn ngữ."],"a":3},{"lv":2,"id":"c3-85","ch":3,"n":85,"q":"Trong các đặc trưng của giai cấp liệt kê dưới đây, đặc trưng nào đóng vai trò quan trọng nhất, chi phối các đặc trưng còn lại?","o":["Khác nhau về địa vị trong hệ thống tổ chức xã hội?","Tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác.","Khác nhau về quan hệ sở hữu tư liệu sản xuất xã hội.","Khác nhau về vai trò trong tổ chức xã hội."],"a":2},{"lv":2,"id":"c3-86","ch":3,"n":86,"q":"Mâu thuẫn đối kháng giữa các giai cấp là do:","o":["Sự khác nhau về tư tưởng, lối sống.","Sự đối lập về lợi ích cơ bản – lợi ích kinh tế.","Sự khác nhau giữa giàu và nghèo.","Sự khác nhau về mức thu nhập."],"a":1},{"lv":2,"id":"c3-87","ch":3,"n":87,"q":"Theo chủ nghĩa duy vật lịch sử, giai cấp nắm giữ quyền lực nhà nước là giai cấp nào?","o":["Có tư tưởng cách mạng và tiên tiến nhất.","Đại biểu cho ý chí của cộng đồng xã hội.","Nắm giữ tư liệu sinh hoạt chủ yếu của xã hội.","Nắm giữ tư liệu sản xuất chủ yếu của xã hội."],"a":3},{"lv":2,"id":"c3-88","ch":3,"n":88,"q":"Sự ra đời của giai cấp trong lịch sử có ý nghĩa như thế nào?","o":["Là một bước tiến của lịch sử.","Là một sai lầm của lịch sử.","Là một phạm trù của lịch sử.","Là một dấu ấn của lịch sử."],"a":0},{"lv":2,"id":"c3-89","ch":3,"n":89,"q":"Vai trò của đấu tranh giai cấp trong lịch sử nhân loại:","o":["Là động lực cơ bản của sự phát triển xã hội.","Là một động lực trực tiếp, quan trọng của sự phát triển xã hội trong các xã hội có giai cấp.","Thay thế các hình thái kinh tế - xã hội từ thấp đến cao.","Lật đổ và thay đổi người cầm quyền."],"a":1},{"lv":2,"id":"c3-90","ch":3,"n":90,"q":"Nội dung nào dưới đây không phải là vai trò của đấu tranh giai cấp trong xã hội có giai cấp?","o":["Nhằm mục đích thay đổi người cầm quyền.","Đấu tranh giai cấp là động lực trực tiếp, quan trọng của lịch sử.","Đấu tranh giai cấp là động lực để phát triển của xã hội có đối kháng giai cấp.","Đấu tranh giai cấp có tác dụng cải tạo xã hội, xoá bỏ các lực lượng xã hội phản động và cải tạo bản thân các giai cấp cách mạng."],"a":0},{"lv":2,"id":"c3-91","ch":3,"n":91,"q":"Đấu tranh giai cấp trong thời kỳ quá độ từ chủ nghĩa tư bản lên chủ nghĩa xã hội bao gồm những nội dung nào?","o":["Đấu tranh giai cấp diễn ra trong bối cảnh phức tạp.","Không cần đấu tranh giai cấp, xã hội sẽ tự phát triển.","Cuộc đấu tranh giai cấp của giai cấp vô sản diễn ra trong những điều kiện mới, với nội dung mới và có những hình thức mới.","Tất cả các đáp án đều đúng."],"a":2},{"lv":2,"id":"c3-92","ch":3,"n":92,"q":"Cuộc đấu tranh giai cấp của giai cấp vô sản là:","o":["Chống lại xã hội phong kiến, xã hội cũ.","Nhằm mục đích cuối cùng là thiết lập quyền thống trị của giai cấp vô sản, cải tạo xã hội cũ, xây dựng thành công xã hội mới.","Cuộc đấu tranh gay go, quyết liệt nhất nhằm thiết lập nền chuyên chính vô sản, cải tạo triệt để xã hội cũ, xoá bỏ mọi đối kháng giai cấp, xây dựng thành công xã hội cộng sản chủ nghĩa và đồng thời là cuộc đấu tranh giai cấp cuối cùng trong lịch sử.","Nhằm thay đổi người cầm quyền."],"a":2},{"lv":2,"id":"c3-93","ch":3,"n":93,"q":"Đặc điểm nào sau đây đóng vai trò quan trọng nhất, quy định đặc trưng của cộng đồng dân tộc?","o":["Lãnh thổ và kinh tế.","Kinh tế và văn hóa.","Lãnh thổ và ngôn ngữ.","Kinh tế và ngôn ngữ."],"a":0},{"lv":2,"id":"c3-94","ch":3,"n":94,"q":"Theo quan điểm của triết học Mác - Lênin, nguyên nhân khách quan của đấu tranh giai cấp là gì?","o":["Do một lý thuyết khoa học về giai cấp thúc đẩy quần chúng nhân dân nổi dậy.","Do sự lôi kéo của một thủ lĩnh có uy tín trong nhân dân phát động và lãnh đạo.","Do sự nghèo khổ của quần chúng nhân dân.","Do mâu thuẫn giữa trình độ phát triển của lực lượng sản xuất xã hội với quan hệ sản xuất đã trở nên lỗi thời."],"a":3},{"lv":2,"id":"c3-95","ch":3,"n":95,"q":"Chọn một phương án sai: Theo chủ nghĩa duy vật lịch sử, nhà nước…","o":["Xuất hiện và tồn tại trong những xã hội có đối kháng giai cấp.","Xuất hiện và tồn tại trong một giai đoạn phát triển nhất định của xã hội loài người.","Ra đời cùng sự xuất hiện của con người.","Là sản phẩm và biểu hiện của những mâu thuẫn đối kháng giai cấp không thể điều hòa được."],"a":2},{"lv":2,"id":"c3-96","ch":3,"n":96,"q":"Chọn đáp án SAI về mối quan hệ giữa giai cấp, dân tộc và nhân loại theo quan điểm của triết học Mác – Lênin.","o":["Trong xã hội có giai cấp, lợi ích nhân loại không tách rời với lợi ích giai cấp, lợi ích dân tộc và bị chi phối bởi lợi ích giai cấp và dân tộc.","Sự tồn tại của nhân loại là tiền đề, là điều kiện tất yếu thường xuyên của sự tồn tại dân tộc và giai cấp.","Sự phát triển về mọi mặt của nhân loại tạo ra những điều kiện thuận lợi cho cuộc đấu tranh giải phóng dân tộc và giai cấp.","Nhân loại đứng trên giai cấp và dân tộc, còn giai cấp và dân tộc có mối quan hệ biện chứng tác động qua lại lẫn nhau."],"a":3},{"lv":2,"id":"c3-97","ch":3,"n":97,"q":"Chọn đáp án SAI về mối quan hệ giữa giai cấp và dân tộc.","o":["Giai cấp quyết định dân tộc nhưng đồng thời vấn đề dân tộc có ảnh hưởng lớn đến vấn đề giai cấp.","Đấu tranh giải phóng dân tộc là điều kiện, tiền đề cho đấu tranh giải phóng giai cấp.","Giai cấp và dân tộc có mối quan hệ biện chứng, tác động qua lại lẫn nhau.","Giai cấp và dân tộc là những phạm trù chỉ các quan hệ xã hội khác nhau nên không có quan hệ với nhau."],"a":3},{"lv":2,"id":"c3-98","ch":3,"n":98,"q":"Trong các đặc trưng của giai cấp thì đặc trưng nào bao trùm và chi phối các đặc trưng khác?","o":["Khác nhau về quan hệ sở hữu tư liệu sản xuất của xã hội.","Khác nhau về vai trò trong tổ chức, quản lý sản xuất.","Khác nhau về cách thức hưởng thụ phần của cải xã hội.","Khác nhau về địa vị trong phương thức sản xuất."],"a":0},{"lv":3,"id":"c3-99","ch":3,"n":99,"q":"Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam, giai cấp công nhân có sự biến đổi mạnh mẽ về cơ cấu ngành nghề, tăng nhanh số lượng lao động trong các ngành công nghiệp công nghệ cao. Hiện tượng này phản ánh trực tiếp sự vận động của cơ cấu giai cấp dưới tác động của nhân tố nào sau đây?","o":["Sự áp đặt ý chí chính trị từ kiến trúc thượng tầng xã hội.","Sự biến mất của chế độ sở hữu tư nhân về tư liệu sản xuất.","Quá trình công nghiệp hóa, hiện đại hóa và Cách mạng công nghiệp lần thứ tư.","Xu hướng hòa nhập của các giai cấp vào một tập đoàn duy nhất."],"a":2},{"lv":3,"id":"c3-100","ch":3,"n":100,"q":"Sau năm 1986, Việt Nam chuyển dịch từ nền kinh tế kế hoạch hóa tập trung bao cấp sang kinh tế thị trường định hướng xã hội chủ nghĩa. Sự xuất hiện của tầng lớp doanh nhân bên cạnh giai cấp công nhân và nông dân là minh chứng thực tế cho luận điểm nào của triết học Mác - Lênin?","o":["Sự biến đổi của kết cấu giai cấp bị quyết định bởi sự biến đổi của cơ cấu kinh tế nhiều thành phần.","Đấu tranh giai cấp đã kết thúc và chuyển sang trạng thái hợp tác.","Giai cấp công nhân đã chuyển giao vai trò lãnh đạo cách mạng cho tầng lớp doanh nhân.","Nhà nước xã hội chủ nghĩa đã hoàn thành mục tiêu xóa bỏ bóc lột giai cấp."],"a":0},{"lv":3,"id":"c3-101","ch":3,"n":101,"q":"Dự án “Đường dây 500kV mạch 3 Quảng Trạch - Phố Nối” hoàn thành thần tốc năm 2024 có đóng góp to lớn của các kỹ sư, chuyên gia công nghệ (trí thức) phối hợp cùng lực lượng công nhân ngành điện lực. Xét dưới góc độ triết học, sự hợp tác này biểu hiện thực tiễn cho nội dung nào?","o":["Sự xóa nhòa ranh giới lao động chân tay và lao động trí óc trong thời kỳ quá độ.","Khối liên minh giữa giai cấp công nhân và tầng lớp trí thức trong thời kỳ quá độ.","Sự tan rã của kết cấu giai cấp cũ dưới áp lực của kinh tế thị trường.","Sự hình thành một kiểu giai cấp mới thay thế giai cấp công nhân truyền thống."],"a":1},{"lv":3,"id":"c3-102","ch":3,"n":102,"q":"Để thực hiện “Chương trình mục tiêu quốc gia phát triển kinh tế - xã hội vùng đồng bào dân tộc thiểu số và miền núi giai đoạn 2021 - 2030”, Nhà nước Việt Nam đã đầu tư mạnh mẽ vào cơ sở hạ tầng giao thông và giáo dục tại Tây Bắc và Tây Nguyên. Chính sách này vận dụng nguyên lý nào của chủ nghĩa duy vật lịch sử về mối quan hệ giai cấp - dân tộc?","o":["Giải quyết vấn đề dân tộc phải bắt đầu từ việc xóa bỏ áp bức giai cấp bằng bạo lực.","Đồng hóa các nền văn hóa của đồng bào thiểu số vào một khuôn mẫu văn hóa duy nhất của Quốc gia.","Giải quyết vấn đề dân tộc gắn liền với nâng cao đời sống vật chất và tinh thần của các cộng đồng dân cư.","Tách rời sự phát triển kinh tế khỏi các đặc trưng văn hóa - tâm lý dân tộc."],"a":2},{"lv":3,"id":"c3-103","ch":3,"n":103,"q":"Luận điểm của Chủ tịch Hồ Chí Minh khẳng định: “Nước độc lập mà dân không được hưởng hạnh phúc, tự do, thì độc lập cũng chẳng có nghĩa lý gì” phản ánh sự vận dụng sáng tạo mối quan hệ nào sau đây vào thực tiễn cách mạng Việt Nam?","o":["Sự thống nhất biện chứng giữa giải phóng dân tộc và giải phóng giai cấp, giải phóng con người.","Sự tách biệt giữa độc lập chủ quyền quốc gia và quyền tự do cá nhân.","Vai trò quyết định của lợi ích nhân loại đối với lợi ích giai cấp thống trị.","Sự phủ nhận vai trò của nhà nước pháp quyền trong việc quản lý và điều hành xã hội."],"a":0},{"lv":3,"id":"c3-104","ch":3,"n":104,"q":"Lịch sử thế giới ghi nhận nhiều dân tộc ở Châu Âu hình thành gắn liền với sự phát triển của chủ nghĩa tư bản. Tuy nhiên, dân tộc Việt Nam ra đời từ rất sớm (thời kỳ Văn Lang - Âu Lạc) trước khi phương thức sản xuất tư bản chủ nghĩa xuất hiện. Yếu tố thực tiễn khách quan nào quyết định tính đặc thù này?","o":["Sự giao thương kinh tế mạnh mẽ bằng đường biển với các quốc gia phương Tây trong quá khứ.","Nhu cầu thường xuyên về trị thủy (làm thủy lợi sông Hồng) và đấu tranh chống ngoại xâm.","Sự phân chia giai cấp đối kháng quyết liệt tương tự như xã hội chiếm hữu nô lệ Hy Lạp.","Sự ra đời sớm của hệ tư tưởng triết học vô thần làm mất đi vai trò của tôn giáo."],"a":1},{"lv":3,"id":"c3-105","ch":3,"n":105,"q":"Việc Đảng và Nhà nước ta khuyến khích phát triển kinh tế tư nhân, coi kinh tế tư nhân là một động lực quan trọng của nền kinh tế thị trường định hướng xã hội chủ nghĩa tại Đại hội XIII thực chất là sự vận dụng quy luật nào vào kết cấu giai cấp Việt Nam?","o":["Xóa bỏ các giai cấp bóc lột để tiến thẳng lên chủ nghĩa cộng sản.","Phủ nhận vai trò chủ đạo của thành phần kinh tế nhà nước.","Hợp nhất giai cấp công nhân vào giai cấp tư sản để xóa bỏ mâu thuẫn đối kháng.","Vận dụng quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất để định hình kết cấu giai cấp đa dạng."],"a":3},{"lv":3,"id":"c3-106","ch":3,"n":106,"q":"Các ngày lễ hội truyền thống như Giỗ Tổ Hùng Vương, Tết Nguyên Đán được tổ chức trang trọng trên cả nước và trong cộng đồng kiều bào ở nước ngoài là minh chứng cho đặc trưng nào của cộng đồng dân tộc Việt Nam?","o":["Sự bền vững về văn hóa, tâm lý, tính cách và ý thức nguồn cội dân tộc.","Tính thống nhất về địa giới hành chính và phân chia giai cấp.","Sự phụ thuộc của đời sống tinh thần vào công nghệ kỹ thuật phương Tây.","Xu hướng hòa tan văn hóa bản địa vào xu thế toàn cầu hóa toàn diện."],"a":0},{"lv":3,"id":"c3-107","ch":3,"n":107,"q":"Hiện nay, nhiều công nhân tại các khu công nghiệp lớn ở Thái Nguyên, Bắc Ninh, Vĩnh Phúc…tích cực tham gia học tập ban đêm để nâng cao trình độ công nghệ thông tin và ngoại ngữ. Hành động tự giác này của người lao động hướng tới việc giải quyết vấn đề gì trong cơ cấu giai cấp?","o":["Chuyển dịch hoàn toàn từ giai cấp công nhân sang tầng lớp trí thức để thoát ly sản xuất.","Tự nâng cao trình độ tri thức hóa của giai cấp công nhân, thích ứng với lực lượng sản xuất hiện đại.","Thoát ly sự quản lý và phân công lao động của Nhà nước pháp quyền xã hội chủ nghĩa.","Phủ nhận chế độ làm chủ tập thể của nhân dân lao động."],"a":1},{"lv":3,"id":"c3-108","ch":3,"n":108,"q":"Trong bối cảnh toàn cầu hóa, biến đổi khí hậu đã gây ra hiện tượng xâm nhập mặn nghiêm trọng tại Đồng bằng sông Cửu Long. Việt Nam đã chủ động hợp tác với các quốc gia thuộc tiểu vùng sông Mê Công để chia sẻ nguồn nước. Việc này thể hiện sự vận dụng mối quan hệ nào?","o":["Sự áp đặt của lợi ích quốc gia lớn đối với lợi ích của quốc gia nhỏ hơn.","Sự kết hợp hài hòa giữa lợi ích dân tộc (an ninh nguồn nước) và lợi ích nhân loại (bảo vệ môi trường sinh thái toàn cầu).","Sự triệt tiêu mâu thuẫn giai cấp trong quan hệ ngoại giao quốc tế.","Vai trò tự quyết của Việt Nam trước các vấn đề an ninh phi truyền thống."],"a":1},{"lv":3,"id":"c3-109","ch":3,"n":109,"q":"Trong tác phẩm “Sáng kiến vĩ đại”, V.I.Lênin đưa ra định nghĩa giai cấp. Nếu một kỹ sư công nghệ tại một nhà máy liên doanh FDI sở hữu cổ phần nhỏ của công ty nhưng vai trò chính vẫn là trực tiếp vận hành hệ thống máy móc, xét về mặt lý luận, thuộc tính nào quyết định địa vị giai cấp của người này?","o":["Tỷ lệ cổ phần nhỏ mà họ sở hữu trong công ty.","Mức lương và các khoản thưởng phúc lợi nhận được hàng tháng.","Xuất thân gia đình của họ trong quá khứ.","Quan hệ thực tế của họ đối với việc quản lý và vận hành trực tiếp lực lượng sản xuất."],"a":3},{"lv":3,"id":"c3-110","ch":3,"n":110,"q":"Giai đoạn kinh tế Việt Nam trước năm 1986 (thời kỳ Bao cấp) duy trì chế độ sở hữu toàn dân và tập thể thuần nhất, triệt tiêu kinh tế tư nhân. Xét dưới góc độ duy vật lịch sử, sai lầm này dẫn đến hậu quả gì về mặt kết cấu giai cấp?","o":["Thúc đẩy mâu thuẫn giai cấp phát triển, tạo ra bạo lực cách mạng.","Tạo ra sự phù hợp giữa quan hệ sản xuất và trình độ lực lượng sản xuất.","Triệt tiêu động lực kinh tế của các giai cấp, tầng lớp, làm xơ cứng và suy giảm tính năng động xã hội.","Xóa bỏ hiệu quả sự khác biệt giữa lao động chân tay và trí óc."],"a":2},{"lv":3,"id":"c3-111","ch":3,"n":111,"q":"Đại dịch COVID-19 bùng phát đã thúc đẩy Việt Nam triển khai ứng dụng quản lý dân cư, tiêm chủng quốc gia (VNeID). Công nghệ này được chia sẻ và sử dụng thống nhất trên toàn lãnh thổ cho mọi công dân không phân biệt thành phần dân tộc. Hiện tượng này chứng minh cho thuộc tính nào của dân tộc?","o":["Sự đồng hóa hành chính của nhà nước đối với các dân tộc thiểu số.","Sự thống nhất về mặt quản lý nhà nước và pháp luật đối với toàn bộ cộng đồng dân tộc.","Sự triệt tiêu bản sắc văn hóa riêng của các tộc người.","Củng cố tính chất biệt lập về văn hóa của các vùng miền trong cả nước."],"a":1},{"lv":3,"id":"c3-112","ch":3,"n":112,"q":"Khi Việt Nam tham gia vào Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP), chúng ta chấp nhận các tiêu chuẩn khắt khe về lao động và môi trường. Hành động này phản ánh việc giải quyết mối quan hệ nào trong thực tiễn?","o":["Sự chủ động hội nhập, hài hòa lợi ích giai cấp, lợi ích dân tộc với các chuẩn mực chung của nhân loại.","Sự hy sinh lợi ích quốc gia để phục vụ cho lợi ích toàn cầu.","Sự mâu thuẫn giữa hệ tư tưởng xã hội chủ nghĩa và hệ tư tưởng tư bản chủ nghĩa.","Sự tách biệt giữa luật pháp quốc gia và luật pháp quốc tế."],"a":0},{"lv":3,"id":"c3-113","ch":3,"n":113,"q":"Các chính sách như miễn học phí cho học sinh trường nội trú vùng cao, hỗ trợ vay vốn ưu đãi cho đồng bào dân tộc thiểu số phát triển sản xuất nông nghiệp ứng dụng công nghệ cao hướng đến mục tiêu cốt lõi nào sau đây?","o":["Tạo ra sự phức tạp trong bộ máy hành chính nhà nước ở địa phương.","Khắc phục sự chênh lệch về trình độ phát triển kinh tế - xã hội, hướng đến và bảo đảm sự bình đẳng thực tế giữa các dân tộc.","Khuyến khích các dân tộc thiểu số tách ra thành lập các khu vực tự trị riêng biệt.","Xóa bỏ tính đặc thù về văn hóa và ngôn ngữ của các dân tộc thiểu số."],"a":1},{"lv":3,"id":"c3-114","ch":3,"n":114,"q":"Thực tiễn quá trình liên minh giai cấp ở Việt Nam hiện nay cho thấy, việc xây dựng các “Hợp tác xã nông nghiệp kiểu mới” đòi hỏi sự hợp tác giữa người nông dân, các doanh nghiệp thu mua và các nhà khoa học nông nghiệp công nghệ cao. Bản chất của mối quan hệ này là gì?","o":["Sự cạnh tranh ngày càng khốc liệt giữa các thành phần kinh tế trong nước.","Sự áp đặt mệnh lệnh hành chính của cơ quan quản lý nhà nước cấp tỉnh.","Sự suy giảm vai trò của kinh tế tập thể ở khu vực nông thôn mới.","Sự liên minh giữa giai cấp công nhân, giai cấp nông dân và tầng lớp trí thức trên cơ sở thống nhất lợi ích kinh tế thực tiễn."],"a":3},{"lv":3,"id":"c3-115","ch":3,"n":115,"q":"Một nhóm thanh niên Việt Nam tự hào chia sẻ các video clip giới thiệu trang phục áo dài và ẩm thực truyền thống… lên nền tảng mạng xã hội toàn cầu TikTok thu hút hàng triệu lượt xem quốc tế. Hành động này phản ánh phương thức vận dụng thực tiễn nào sau đây?","o":["Phủ nhận xu hướng toàn cầu hóa để quay về lối sống cô lập, tự cung tự cấp.","Giữ gìn và phát huy bản sắc văn hóa dân tộc thông qua các phương tiện truyền thông hiện đại của thời đại 4.0.","Sự sùng bái thái quá công nghệ nước ngoài gây phương hại đến an ninh tư tưởng.","Quá trình đồng hóa văn hóa Việt Nam vào văn hóa phương Tây."],"a":1},{"lv":3,"id":"c3-116","ch":3,"n":116,"q":"Tại một số tỉnh miền núi phía Bắc, việc Nhà nước giao đất giao rừng lâu dài cho các hộ gia đình đồng bào dân tộc thiểu số quản lý và phát triển kinh tế trang trại đã làm thay đổi căn bản điều gì trong đời sống của họ xét theo định nghĩa giai cấp?","o":["Tạo động lực tự giác trong lao động, hướng đến xóa đói giảm nghèo bền vững.","Thay đổi hoàn toàn ngôn ngữ và phong tục tập quán lâu đời của dòng họ.","Loại bỏ vai trò quản lý hành chính của chính quyền các cấp.","Thay đổi phương thức sản xuất, nhanh chóng biến người nông dân thành giai cấp công nhân hiện đại."],"a":0},{"lv":3,"id":"c3-117","ch":3,"n":117,"q":"Trong thời kỳ quá độ, các mâu thuẫn giữa giai cấp công nhân và giai cấp tư sản ở Việt Nam được giải quyết chủ yếu thông qua phương thức nào sau đây để bảo đảm sự ổn định chính trị?","o":["Sử dụng bạo lực vũ trang để làm giảm hiệu quả các chủ doanh nghiệp tư nhân.","Quốc hữu hóa tài sản của các nhà đầu tư nước ngoài.","Hợp tác và đấu tranh trong khuôn khổ pháp luật của Nhà nước pháp quyền xã hội chủ nghĩa.","Khu biệt hóa và tách biệt hóa lợi ích giữa giai cấp công nhân với giai cấp tư sản."],"a":2},{"lv":3,"id":"c3-118","ch":3,"n":118,"q":"Việc thành lập các trường phổ thông dân tộc nội trú, bán trú tại các địa bàn đặc biệt khó khăn vùng đồng bào dân tộc thiểu số thể hiện sự quan tâm của Đảng và Nhà nước ta trong việc giải quyết đặc trưng nào của dân tộc?","o":["Tạo ra sự đồng nhất về trình độ học vấn giữa thành thị và nông thôn.","Nâng cao trình độ dân trí, phát triển nguồn nhân lực tại chỗ, củng cố nền tảng văn hóa dân tộc.","Thay thế triệt để ngôn ngữ truyền thống của các tộc người bằng chữ quốc ngữ.","Hạn chế quyền tự do di cư của đồng bào thiểu số sang các tỉnh khác."],"a":1},{"lv":3,"id":"c3-119","ch":3,"n":119,"q":"Khi phân tích sự biến đổi của giai cấp nông nhân Việt Nam hiện nay, hiện tượng một bộ phận lớn lao động nông thôn chuyển dịch ra các thành phố lớn làm việc trong các công ty, nhà máy phản ánh xu hướng thực tiễn nào?","o":["Sự bần cùng hóa của người nông dân dưới tác động của thiên tai.","Dấu hiệu của sự rạn nứt khối liên minh công - nông - trí thức.","Quá trình vô sản hóa và chuyển dịch cơ cấu lao động từ nông nghiệp sang công nghiệp.","Sự suy giảm vai trò của sản xuất nông nghiệp truyền thống ở Việt Nam."],"a":2},{"lv":3,"id":"c3-120","ch":3,"n":120,"q":"Việc Việt Nam kiên quyết bảo vệ chủ quyền biên giới quốc gia, phân giới cắm mốc hoàn chỉnh với các nước láng giềng (Trung Quốc, Lào, Campuchia) là sự vận dụng thực tiễn đặc trưng nào của dân tộc?","o":["Sự thống nhất tuyệt đối về hệ thống ngôn ngữ quốc tế.","Sự xác lập và bảo vệ chủ quyền độc lập trên một vùng lãnh thổ thống nhất.","Sự ngăn chặn và dần triệt tiêu giao thương kinh tế qua biên giới.","Việc áp dụng chung một hệ tư tưởng tôn giáo giữa các nước láng giềng."],"a":1},{"lv":3,"id":"c3-121","ch":3,"n":121,"q":"Nhiều trí thức trẻ Việt Nam sau khi hoàn thành chương trình đào tạo thạc sĩ, tiến sĩ tại nước ngoài đã tự nguyện trở về nước đầu tư khởi nghiệp trong lĩnh vực công nghệ xanh, nông nghiệp tuần hoàn. Hiện tượng thực tiễn này phản ánh điều gì?","o":["Ý thức trách nhiệm dân tộc sâu sắc của tầng lớp trí thức đối với sự nghiệp xây dựng đất nước.","Sự suy giảm niềm tin của trí thức vào sự phát triển của khoa học phương Tây.","Sự dự báo về sụp đổ của nền kinh tế tư bản chủ nghĩa trên quy mô toàn cầu.","Sức mạnh của các biện pháp hành chính do Nhà nước ban hành."],"a":0},{"lv":4,"id":"c3-122","ch":3,"n":122,"q":"Hãy phân tích mâu thuẫn cơ bản trong định nghĩa giai cấp của V.I.Lênin dưới góc độ kinh tế: “tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác, do chỗ họ có địa vị khác nhau trong một chế độ kinh tế - xã hội nhất định”. Sự khác biệt về địa vị này được quyết định sâu xa nhất bởi yếu tố nào?","o":["Vai trò quản lý trực tiếp quy trình công nghệ của nhà máy.","Cách thức phân phối và thụ hưởng của cải xã hội ít hay nhiều.","Trình độ học vấn và văn bằng chuyên môn của người lao động.","Quan hệ sở hữu đối với tư liệu sản xuất chủ yếu của xã hội."],"a":3},{"lv":4,"id":"c3-123","ch":3,"n":123,"q":"Khi nghiên cứu sự khác biệt căn bản giữa quá trình hình thành dân tộc ở Châu Âu và tính độc đáo trong sự hình thành dân tộc Việt Nam, nhận định nào sau đây là đúng nhất?","o":["Ở Châu Âu, dân tộc ra đời sớm hơn sự xuất hiện của phương thức sản xuất tư bản chủ nghĩa; ở Việt Nam dân tộc hình thành gắn liền với sự ra đời của chủ nghĩa tư bản.","Ở Châu Âu, dân tộc hình thành gắn liền với quá trình xóa bỏ chế độ phong kiến, phát triển chủ nghĩa tư bản; ở Việt Nam dân tộc ra đời rất sớm do nhu cầu trị thủy và chống ngoại xâm.","Cả hai quá trình đều hoàn toàn giống nhau về động lực kinh tế và sự phân chia giai cấp đối kháng quyết liệt.","Sự ra đời của dân tộc Việt Nam hoàn toàn là kết quả mang tính ngẫu nhiên của các sắc lệnh hành chính triều đình phong kiến."],"a":1},{"lv":4,"id":"c3-124","ch":3,"n":124,"q":"Khi phân tích kết cấu xã hội - giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở nước ta, nhận định nào dưới đây phản ánh đúng bản chất của kết cấu này?","o":["Là một kết cấu đơn nhất, thuần nhất chỉ gồm giai cấp công nhân và nông dân đã được đồng hóa.","Là một kết cấu hoàn toàn ổn định tĩnh tại, không có sự chuyển dịch lao động giữa các nhóm xã hội.","Là một kết cấu đa dạng, phức tạp và có sự biến đổi mạnh mẽ do sự tồn tại của nền kinh tế nhiều thành phần.","Là kết cấu đối kháng quyết liệt về mặt lợi ích giống như trong thời kỳ xã hội chiếm hữu nô lệ."],"a":2},{"lv":4,"id":"c3-125","ch":3,"n":125,"q":"Trong bối cảnh hiện nay ở Việt Nam, yếu tố nào quyết định sứ mệnh lịch sử lãnh đạo cách mạng của giai cấp này thông qua Đảng Cộng sản Việt Nam?","o":["Số lượng công nhân đông đảo nhất trong cơ cấu dân số cả nước.","Đại diện cho phương thức sản xuất tiến bộ, lực lượng sản xuất hiện đại và có hệ tư tưởng khoa học soi đường.","Khả năng tài chính và nguồn vốn đầu tư vượt trội so với các giai cấp khác.","Sự tách biệt về tính chất và môi trường làm việc của công nhân đối với các giai cấp tầng lớp khác."],"a":1},{"lv":4,"id":"c3-126","ch":3,"n":126,"q":"Nhận định nào dưới đây làm rõ bản chất luận điểm của Hồ Chí Minh về mối quan hệ giữa cách mạng vô sản ở chính quốc và cách mạng giải phóng dân tộc ở thuộc địa như “đôi cánh của một con chim”.?","o":["Cách mạng ở thuộc địa luôn bị động và phụ thuộc một chiều vào sự thắng lợi của cách mạng ở chính quốc.","Cách mạng ở thuộc địa và chính quốc không có bất kỳ mối liên hệ nào về mặt lợi ích giai cấp.","Giải phóng giai cấp ở chính quốc là mục tiêu duy nhất quyết định mọi biến động lịch sử toàn cầu.","Hai cuộc cách mạng có mối quan hệ bình đẳng, hỗ trợ, tác động biện chứng lẫn nhau; cách mạng thuộc địa có thể chủ động giành thắng lợi trước cách mạng chính quốc."],"a":3},{"lv":4,"id":"c3-127","ch":3,"n":127,"q":"Phân tích nguồn gốc sâu xa của sự hình thành giai cấp trong lịch sử, sự phát triển của công cụ sản xuất bằng kim loại cuối thời kỳ nguyên thủy có tác động thế nào đến quan hệ xã hội?","o":["Thúc đẩy phân công lao động xã hội, tăng năng suất lao động, tạo ra của cải dư thừa tương đối và dẫn đến sự xuất hiện chế độ tư hữu.","Làm giảm năng suất lao động xã hội, buộc con người phải quay lại lối sống hái lượm hoang dã.","Xóa bỏ sự phân biệt giữa lao động trí óc và lao động chân tay.","Tạo ra sự bình đẳng về mặt phân phối tài sản giữa các thành viên trong cộng đồng."],"a":0},{"lv":4,"id":"c3-128","ch":3,"n":128,"q":"Trong bối cảnh kinh tế thị trường ở nước ta hiện nay, đặc trưng “Dân tộc là một cộng đồng thống nhất về kinh tế” được thể hiện rõ nhất qua hiện tượng nào?","o":["Sự áp đặt mức giá chung cho tất cả các loại hàng hóa ở mọi vùng miền bởi Nhà nước.","Sự hình thành thị trường dân tộc thống nhất, giao thương hàng hóa tự do, phá bỏ ranh giới cát cứ địa phương.","Việc mọi thành viên dân tộc đều được chia đều một khoản thu nhập quốc dân bằng nhau.","Sự ngăn chặn những hoạt động thương mại của các thành viên cộng động với các quốc gia khác trên thế giới."],"a":1},{"lv":4,"id":"c3-129","ch":3,"n":129,"q":"Khi phân tích sự tác động biện chứng giữa giai cấp và dân tộc, nhận định nào dưới đây phản ánh đúng thế giới quan duy vật lịch sử?","o":["Dân tộc toàn quyền quyết định sự hình thành và tiêu vong của giai cấp.","Giai cấp quyết định dân tộc, vấn đề dân tộc có ảnh hưởng quan trọng đến cuộc đấu tranh giai cấp.","Giai cấp và dân tộc là hai phạm trù độc lập, không có bất kỳ sự tác động qua lại nào.","Việc giải phóng dân tộc có thể thực hiện triệt để mà không cần quan tâm đến địa vị của giai cấp lãnh đạo."],"a":1},{"lv":4,"id":"c3-130","ch":3,"n":130,"q":"Tại sao trong lịch sử, giai cấp nông dân Việt Nam là lực lượng cách mạng đông đảo và kiên quyết nhất nhưng lại không thể tự mình lãnh đạo cuộc cách mạng giải phóng dân tộc đi đến thành công cuối cùng?","o":["Vì họ thiếu lòng yêu nước và ý chí đấu tranh chống ngoại xâm.","Vì họ luôn bị áp bức bóc lột ít hơn so với giai cấp công nhân.","Vì họ không đại diện cho phương thức sản xuất tiên tiến và không có hệ tư tưởng độc lập, khoa học.","Vì họ từ chối liên minh với giai cấp công nhân và tầng lớp trí thức."],"a":2},{"lv":4,"id":"c3-131","ch":3,"n":131,"q":"Hãy phân tích ý nghĩa phương pháp luận của việc nghiên cứu các hình thức cộng đồng người trong lịch sử (Thị tộc - Bộ lạc - Bộ tộc - Dân tộc). Tiến trình này chứng minh điều gì?","o":["Sự vận động của xã hội loài người là một quá trình lịch sử - tự nhiên chịu sự quyết định của sự phát triển lực lượng sản xuất và quan hệ sản xuất.","Sự phát triển xã hội luôn phụ thuộc vào ý chí chủ quan của các nhà tư tưởng vĩ đại.","Sự quay trở lại tất yếu của loài người về lối sống thị tộc ban đầu để bảo vệ môi trường.","Tính chất ngẫu nhiên, không có quy luật của các hình thức liên kết cộng đồng người trong lịch sử."],"a":0},{"lv":4,"id":"c3-132","ch":3,"n":132,"q":"Mâu thuẫn giai cấp chủ yếu ở Việt Nam hiện nay đang được giải quyết nhằm phục vụ cho mục tiêu chiến lược nào của đất nước?","o":["Ngăn chặn sự hình thành và phát triển của thành phần kinh tế tư nhân hướng đến xây dựng nền kinh tế nhà nước phát triển cao.","Thiết lập nền chuyên chính vô sản bằng phương pháp bạo lực vũ trang trong nội bộ nhân dân.","Đóng cửa nền kinh tế, hạn chế hội nhập quốc tế để tự bảo vệ đất nước trước những nguy cơ bên ngoài.","Thực hiện thắng lợi sự nghiệp công nghiệp hóa, hiện đại hóa, xây dựng xã hội “Dân giàu, nước mạnh, dân chủ, công bằng, văn minh”."],"a":3},{"lv":5,"id":"c3-133","ch":3,"n":133,"q":"Đánh giá tính đúng đắn của việc vận dụng thế giới quan duy vật lịch sử vào việc phản bác luận điệu xuyên tạc của các thế lực thù địch lợi dụng vấn đề “quyền tự quyết dân tộc” để kích động tư tưởng ly khai, đòi thành lập “nhà nước tự trị” tại vùng đồng bào dân tộc thiểu số ở Tây Nguyên và Tây Bắc. Nhận định nào dưới đây là thuyết phục nhất?","o":["Đồng ý một phần với những luận điệu ly khai vì mỗi tộc người nhỏ đều cần có một không gian phát triển riêng.","Luận điệu ly khai là phản khoa học và phản thực tiễn, phá vỡ khối đại đoàn kết toàn dân tộc, đi ngược lại lợi ích sinh tồn, phát triển lâu đời của chính các tộc người đó và quốc gia Việt Nam thống nhất.","Quyền tự quyết dân tộc chỉ có giá trị khi quốc gia đó rơi vào trạng thái khủng hoảng kinh tế toàn diện.","Nhà nước Việt Nam nên chấp nhận sự chia cắt lãnh thổ để giữ gìn hòa bình và giảm thiểu sự chống phá của các thế lực thù địch bên ngoài."],"a":1},{"lv":5,"id":"c3-134","ch":3,"n":134,"q":"Một số học giả phương Tây cho rằng: Trong nền kinh tế hiện đại, sự xuất hiện của tầng lớp “công nhân cổ trắng” (làm việc văn phòng, lương cao, sở hữu cổ phần) đã làm cho học thuyết giai cấp của triết học Mác lỗi thời, ranh giới giai cấp đã hoàn toàn biến mất. Từ thế giới quan duy vật lịch sử, anh (chị) đánh giá quan điểm này như thế nào?","o":["Quan điểm này hoàn toàn đúng vì công nhân văn phòng hiện nay đã trở thành những nhà tư bản thực thụ.","Đồng ý một nửa vì ranh giới giai cấp chỉ còn tồn tại ở những nước kém phát triển trong nông nghiệp.","Học thuyết giai cấp của Mác cần được thay thế bằng lý thuyết phân tầng xã hội dựa trên dấu ấn cá nhân.","Quan điểm này sai lầm; sự thay đổi về mức lương hay tính chất công việc (lao động trí óc) không làm thay đổi địa vị thực tế của họ là người bán sức lao động và bị chủ tư bản chiếm đoạt giá trị thặng dư."],"a":3},{"lv":5,"id":"c3-135","ch":3,"n":135,"q":"Đánh giá tầm quan trọng của tư tưởng Hồ Chí Minh về tính chủ động của cách mạng giải phóng dân tộc ở thuộc địa trước các điều chỉnh của thực tiễn lịch sử. Nhận định nào sau đây làm rõ ý nghĩa phương pháp luận của tư tưởng này đối với công cuộc phát triển đất nước hiện nay?","o":["Việt Nam cần tập trung phát triển nội lực, không nên quan tâm đến các nguồn lực và xu thế toàn cầu.","Khẳng định giá trị của tinh thần tự lực tự cường, khơi dậy khát vọng phát triển đất nước phồn vinh, hạnh phúc, kết hợp sức mạnh dân tộc với sức mạnh thời đại.","Chứng minh rằng cách mạng Việt Nam nên đi sau và chỉ cần học hỏi mô hình của các nước lớn.","Phủ nhận hoàn toàn vai trò của các khối liên minh kinh tế quốc tế đối với sự phát triển đất nước."],"a":1},{"lv":5,"id":"c3-136","ch":3,"n":136,"q":"Đánh giá chính sách bảo tồn tiếng nói và chữ viết của các dân tộc thiểu số tại Việt Nam (như việc phát sóng các chương trình truyền hình bằng tiếng Êđê, Khmer, H’ Mông trên sóng VTV5). Việc này phản ánh quan điểm nào của Đảng và Nhà nước ta về vấn đề dân tộc?","o":["Sự tốn kém tài chính không cần thiết làm chậm quá trình hiện đại hóa đất nước.","Sự thừa nhận tính chất cát cứ, biệt lập của các vùng miền tộc người.","Tôn trọng sự đa dạng văn hóa, bảo đảm quyền bình đẳng, giữ gìn bản sắc độc đáo của các tộc người trong chỉnh thể dân tộc Việt Nam thống nhất.","Chính sách mang tính nhất thời nhằm xoa dịu các xung đột sắc tộc trong thực tiễn."],"a":2},{"lv":5,"id":"c3-137","ch":3,"n":137,"q":"Từ thế giới quan duy vật lịch sử, anh (chị) đánh giá thế nào về quan điểm cho rằng: Toàn cầu hóa và hội nhập quốc tế sâu rộng sẽ làm biến mất hoàn toàn ranh giới quốc gia, bản sắc văn hóa dân tộc sẽ bị hòa tan vào văn hóa toàn cầu?","o":["Quan điểm này sai lầm, phiến diện; toàn cầu hóa làm tăng sự tương tác nhưng cũng khơi dậy ý thức tự khẳng định bản sắc dân tộc; bản sắc văn hóa độc đáo chính là thực lực để dân tộc hội nhập mà không bị hòa tan.","Hoàn toàn đúng vì thế giới sẽ trở thành một chỉnh thể đồng nhất về mọi mặt.","Toàn cầu hóa chỉ ảnh hưởng đến các quốc gia kém phát triển về công nghệ và yếu thế về mặt kinh tế, đặc biệt là sức mạnh quân sự quốc phòng.","Các quốc gia nên chủ động xóa bỏ ngôn ngữ truyền thống để chuyển sang dùng tiếng Anh thống nhất toàn cầu."],"a":0},{"lv":6,"id":"c3-138","ch":3,"n":138,"q":"Nếu được giao nhiệm vụ xây dựng đề án “Phát triển nguồn nhân lực chất lượng cao phù hợp với biến đổi cơ cấu giai cấp công nhân Việt Nam trong bối cảnh chuyển đổi số toàn diện”, định hướng giải pháp tổng thể nào sau đây thể hiện tư duy sáng tạo và đúng phương pháp luận triết học nhất?","o":["Chỉ đầu tư kinh phí mua sắm các thiết bị công nghệ hiện đại của nước ngoài về trang bị cho các nhà máy mà không cần đào tạo công nhân nhằm tiết kiệm thời gian và chi phí.","Giảm bớt thời gian đào tạo lý thuyết để tăng thời gian thực hành công nghệ giúp công nhân nhanh chóng tham gia vào thị trường lao động.","Khuyến khích các doanh nghiệp sa thải và ngừng tuyển dụng đối với lao động lớn tuổi để tuyển dụng lao động trẻ có sẵn kỹ năng công nghệ.","Xây dựng chương trình đào tạo tích hợp nâng cao đồng bộ cả về kỹ năng công nghệ (kỹ năng cứng), kỹ năng mềm, kỹ năng số gắn liền với bồi dưỡng bản lĩnh chính trị, đạo đức nghề nghiệp và tác phong công nghiệp cho người lao động."],"a":3},{"lv":6,"id":"c3-139","ch":3,"n":139,"q":"Nhằm giải quyết bài toán phát triển kinh tế bền vững gắn với giữ gìn bản sắc văn hóa của đồng bào các dân tộc thiểu số tại vùng núi phía Bắc Việt Nam hiện nay, anh (chị) hãy đề xuất mô hình sáng tạo nào sau đây phù hợp nhất?","o":["Di dời toàn bộ đồng bào thiểu số xuống vùng đồng bằng để nhanh chóng hòa nhịp với lối sống văn minh đô thị.","Phát triển mô hình “Du lịch sinh thái - văn hóa cộng đồng bản địa” do chính người dân làm chủ dưới sự hỗ trợ về vốn, công nghệ và định hướng thị trường của Nhà nước và doanh nghiệp.","Nghiêm cấm mọi hoạt động giao thương kinh tế với bên ngoài để bảo tồn nguyên vẹn trạng thái tự nhiên của bản làng.","Tập trung chuyển đổi toàn bộ đất rừng phòng hộ thành các khu công nghiệp chế xuất quy mô lớn để thu hút đầu tư nước ngoài và giải quyết nhu cầu việc làm tại chỗ chô đồng bào dân tộc thiểu số."],"a":1},{"lv":1,"id":"c3-140","ch":3,"n":140,"q":"Nguyên nhân sâu xa của sự xuất hiện nhà nước là:","o":["Do sự phát triển của lực lượng sản xuất dẫn đến sự dư thừa tương đối của cải, xuất hiện chế độ tư hữu.","Do mâu thuẫn giai cấp trong xã hội gay gắt không thể điều hòa được.","Do sự phát triển tự nhiên của xã hội.","Do Thượng đế tạo ra."],"a":0},{"lv":1,"id":"c3-141","ch":3,"n":141,"q":"Nguyên nhân trực tiếp của sự xuất hiện nhà nước là:","o":["Do sự phát triển của lực lượng sản xuất dẫn đến sự dư thừa tương đối của cải, xuất hiện chế độ tư hữu.","Do mâu thuẫn giai cấp trong xã hội gay gắt không thể điều hòa được.","Do sự phát triển tự nhiên của xã hội.","Do Thượng đế tạo ra."],"a":1},{"lv":1,"id":"c3-142","ch":3,"n":142,"q":"Sự ra đời và tồn tại của nhà nước là do:","o":["Nguyện vọng của giai cấp thống trị.","Nguyện vọng của mỗi quốc gia dân tộc.","Tất yếu khách quan và do nguyên nhân kinh tế.","Sự phát triển của xã hội."],"a":2},{"lv":1,"id":"c3-143","ch":3,"n":143,"q":"Nguồn gốc sâu xa của cách mạng xã hội là do:","o":["Mâu thuẫn giữa sự tiến bộ của lực lượng sản xuất với tính ổn định, lạc hậu của quan hệ sản xuất.","Mâu thuẫn giai cấp và đấu tranh giai cấp.","Tự thân xã hội phát triển.","Do Thượng Đế sắp đặt."],"a":0},{"lv":1,"id":"c3-144","ch":3,"n":144,"q":"Nguồn gốc trực tiếp của cách mạng xã hội là do:","o":["Mâu thuẫn giữa sự tiến bộ của lực lượng sản xuất với tính ổn định, lạc hậu của quan hệ sản xuất.","Mâu thuẫn giữa giai cấp thống trị và giai cấp bị thống trị trong xã hội, do đấu tranh giai cấp.","Tự thân xã hội phát triển.","Do Thượng Đế sắp đặt."],"a":1},{"lv":1,"id":"c3-145","ch":3,"n":145,"q":"“Sự biến đổi có tính chất bước ngoặt và căn bản về chất trong mọi lĩnh vực đời sống xã hội, là phương thức thay thế hình thái kinh tế xã hội này bằng hình thái kinh tế - xã hội cao hơn” được gọi là gì?","o":["Cách mạng khoa học và công nghệ.","Cách mạng xã hội.","Đấu tranh giai cấp.","Tất cả các phương án đều sai."],"a":1},{"lv":1,"id":"c3-146","ch":3,"n":146,"q":"Theo triết học Mác – Lênin, động lực cách mạng là:","o":["Những giai cấp và những lực lượng đối lập cần phải đánh đổ của cách mạng.","Những giai cấp có lợi ích gắn bó chặt chẽ và lâu dài đối với cách mạng, có tính tự giác, tích cực, chủ động, kiên quyết, triệt để cách mạng, có khả năng lôi cuốn, tập hợp các giai cấp, tầng lớp khác tham gia phong trào cách mạng.","Giai cấp có hệ tư tưởng tiến bộ, đại diện cho xu hướng phát triển của xã hội, cho phương thức sản xuất tiến bộ.","Tất cả các đáp án đều đúng."],"a":1},{"lv":1,"id":"c3-147","ch":3,"n":147,"q":"Theo triết học Mác – Lênin, đối tượng của cách mạng xã hội là:","o":["Những giai cấp và những lực lượng đối lập cần phải đánh đổ của cách mạng.","Những giai cấp có lợi ích gắn bó chặt chẽ và lâu dài đối với cách mạng, có tính tự giác, tích cực, chủ động, kiên quyết, triệt để cách mạng, có khả năng lôi cuốn, tập hợp các giai cấp, tầng lớp khác tham gia phong trào cách mạng.","Giai cấp có hệ tư tưởng tiến bộ, đại diện cho xu hướng phát triển của xã hội, cho phương thức sản xuất tiến bộ.","Tất cả các đáp án đều đúng."],"a":0},{"lv":2,"id":"c3-148","ch":3,"n":148,"q":"Theo triết học Mác – Lênin, sự ra đời và tồn tại của nhà nước nhằm:","o":["Điều hòa mâu thuẫn giai cấp.","Giải quyết mâu thuẫn giai cấp.","Bảo vệ lợi ích của mọi giai cấp trong xã hội.","Bảo vệ trật tự xã hội theo ý chí và lợi ích của giai cấp thống trị kinh tế."],"a":3},{"lv":2,"id":"c3-149","ch":3,"n":149,"q":"Đáp án nào sau đây nêu đúng nhất bản chất của nhà nước?","o":["Là cơ quan quyền lực của giai cấp.","Là bộ máy quản lý xã hội.","Công cụ thống trị áp bức của giai cấp thống trị đối với toàn bộ xã hội, cơ quan trọng tài phân xử, hòa giải các xung đột xã hội.","Cơ quan phúc lợi chung của toàn xã hội."],"a":2},{"lv":2,"id":"c3-150","ch":3,"n":150,"q":"Theo triết học Mác – Lênin, bộ máy tổ chức quyền lực và thực thi quyền lực đặc biệt của xã hội trong điều kiện xã hội có đối kháng giai cấp là:","o":["Nhà nước","Giáo hội","Các đảng phái","Các đoàn thể xã hội"],"a":0},{"lv":2,"id":"c3-151","ch":3,"n":151,"q":"Đặc trưng cơ bản của nhà nước theo quan điểm của chủ nghĩa duy vật lịch sử là:","o":["Quản lý cư dân trên một vùng lãnh thổ nhất định.","Có hệ thống các cơ quan quyền lực chuyên nghiệp mang tính cưỡng chế đối với mọi thành viên.","Có hệ thống thuế khóa để nuôi bộ máy chính quyền.","Tất cả các đáp án."],"a":3},{"lv":2,"id":"c3-152","ch":3,"n":152,"q":"Chọn đáp án đúng nhất: Các chức năng cơ bản của nhà nước là:","o":["Chức năng thống trị chính trị giai cấp (trấn áp bạo lực, chức năng giai cấp) và chức năng xã hội (tổ chức xây dựng); chức năng đối nội và chức năng đối ngoại.","Chức năng đối nội và chức năng đối ngoại; chức năng kinh tế.","Chức năng thống trị xã hội và chức năng xã hội; chức năng giáo dục.","Tất cả các đáp án đều sai."],"a":0},{"lv":2,"id":"c3-153","ch":3,"n":153,"q":"Thứ tự các kiểu nhà nước tồn tại trong lịch sử xã hội:","o":["Nhà nước phong kiến, nhà nước chủ nô, nhà nước tư bản, nhà nước vô sản.","Nhà nước vô sản, nhà nước phong kiến, nhà nước chủ nô, nhà nước tư bản.","Nhà nước chủ nô, nhà nước phong kiến, nhà nước tư bản, nhà nước vô sản.","Nhà nước chủ nô, nhà nước phong kiến, nhà nước vô sản, nhà nước tư sản."],"a":2},{"lv":2,"id":"c3-154","ch":3,"n":154,"q":"Trong các kiểu nhà nước sau, nhà nước nào khác về bản chất so với các kiểu nhà nước còn lại?","o":["Nhà nước chiếm hữu nô lệ.","Nhà nước phong kiến.","Nhà nước tư bản.","Nhà nước vô sản."],"a":3},{"lv":2,"id":"c3-155","ch":3,"n":155,"q":"Nền chuyên chính vô sản (nhà nước vô sản) có chức năng cơ bản là:","o":["Chống lại giai cấp phong kiến và chế độ cũ.","Xây dựng một trật tự xã hội mới, thủ tiêu chế độ người áp bức bóc lột người, đập tan sự phản kháng của các thế lực phản động đã bị đánh đổ nhưng chưa bị tiêu diệt vẫn ngoan cố chống lại chính quyền do giai cấp vô sản lãnh đạo.","Thực hiện trấn áp bạo lực với các giai cấp, tầng lớp khác trong xã hội.","Chỉ thực hiện chức năng tổ chức xây dựng mà không cần thực hiện chức năng thống trị chính trị giai cấp."],"a":1},{"lv":2,"id":"c3-156","ch":3,"n":156,"q":"Chọn đáp án đúng nhất: Thực chất của nhà nước vô sản là:","o":["Nhà nước do giai cấp nông dân và tầng lớp trí thức nắm quyền, lãnh đạo.","Nhà nước do giai cấp vô sản nắm quyền, lãnh đạo.","Nhà nước do giai cấp vô sản lãnh đạo, liên minh với giai cấp nông dân, tầng lớp trí thức tiến bộ, và các tầng lớp nhân dân lao động khác đại diện và bảo vệ quyền lợi của giai cấp và của toàn thể nhân dân lao động.","Nhà nước do tầng lớp trí thức nắm quyền, lãnh đạo."],"a":2},{"lv":2,"id":"c3-157","ch":3,"n":157,"q":"Theo chủ nghĩa duy vật lịch sử, mối quan hệ giữa chức năng đối nội và chức năng đối ngoại của nhà nước là:","o":["Là hai mặt của một thực thể thống nhất, hỗ trợ và tác động lẫn nhau nhằm thực hiện đường lối đối nội và đường lối đối ngoại của giai cấp thống trị.","Chức năng đối nội và chức năng đối ngoại chỉ có mối quan hệ bề ngoài, không bản chất.","Chức năng đối ngoại quan trọng hơn và giữ vai trò chủ yếu.","Tất cả các đáp án đều không đúng."],"a":0},{"lv":2,"id":"c3-158","ch":3,"n":158,"q":"Nhà nước trong thời kỳ quá độ lên chủ nghĩa xã hội là nhà nước nào?","o":["Nhà nước dân chủ cộng hòa.","Nhà nước dân chủ tư sản.","Nhà nước chuyên chính vô sản.","Nhà nước dân chủ nhân dân."],"a":2},{"lv":2,"id":"c3-159","ch":3,"n":159,"q":"Tính chất của cách mạng xã hội được xác định bởi:","o":["Mâu thuẫn cơ bản và nhiệm vụ giải quyết mâu thuẫn kinh tế với mâu thuẫn chính trị xã hội tương ứng.","Giai cấp cầm quyền xác định.","Thượng đế, thần linh.","Sự phát triển tự nhiên của xã hội."],"a":0},{"lv":2,"id":"c3-160","ch":3,"n":160,"q":"Điều kiện khách quan để cách mạng xã hội diễn ra là:","o":["Năng lực tổ chức thực hiện nhiệm vụ cách mạng, khả năng tập hợp lực lượng cách mạng của giai cấp lãnh đạo cách mạng.","Thời điểm đặc biệt khi điều kiện khách quan và nhân tố chủ quan của cách mạng xã hội đã chín muồi, đó là lúc thuận lợi nhất có thể bùng nổ cách mạng, có ý nghĩa quyết định đối với thành công của cách mạng.","Điều kiện, hoàn cảnh kinh tế - xã hội, chính trị bên ngoài tác động đến, là tiền đề diễn ra các cuộc cách mạng xã hội.","Khi ý chí, niềm tin, trình độ giác ngộ và nhận thức của lực lượng cách mạng một lòng hướng vào thực hiện mục tiêu và nhiệm vụ cách mạng."],"a":2},{"lv":2,"id":"c3-161","ch":3,"n":161,"q":"Đâu không phải là điều kiện chủ quan để cách mạng xã hội diễn ra?","o":["Năng lực tổ chức thực hiện nhiệm vụ cách mạng, khả năng tập hợp lực lượng cách mạng của giai cấp lãnh đạo cách mạng đã đạt đến độ chin muồi.","Khi ý chí, niềm tin, trình độ giác ngộ và nhận thức của lực lượng cách mạng một lòng hướng vào thực hiện mục tiêu và nhiệm vụ cách mạng.","Lực lượng và những yếu tố của xã hội cũ đang suy yếu.","Tất cả các đáp án."],"a":2},{"lv":2,"id":"c3-162","ch":3,"n":162,"q":"Các phương pháp cách mạng được sử dụng trong cách mạng xã hội là:","o":["Diễn biến hòa bình.","Đảo chính","Bạo lực cách mạng và phương pháp hòa bình.","Tự diễn biến, tự chuyển hóa."],"a":2},{"lv":3,"id":"c3-163","ch":3,"n":163,"q":"Quyết định số 749/QĐ-TTg của Thủ tướng Chính phủ phê duyệt “Chương trình Chuyển đổi số quốc gia đến năm 2025, định hướng đến năm 2030” nhằm xây dựng Chính phủ số, kinh tế số và xã hội số. Dưới góc độ triết học Mác - Lênin, việc Nhà nước Việt Nam chủ động ban hành và tổ chức thực hiện chương trình này là sự vận dụng chức năng nào của nhà nước?","o":["Chức năng thống trị chính trị thuần túy nhằm kiểm soát hoạt động của các chủ thể kinh tế tư nhân.","Chức năng đối ngoại nhằm chuyển giao toàn bộ nghĩa vụ quản lý công nghệ cho các tổ chức quốc tế đa phương.","Chức năng cưỡng chế pháp lý để xóa bỏ ngay lập tức các quan hệ sản xuất truyền thống phi công nghệ.","Chức năng xã hội của nhà nước trong việc tổ chức, quản lý và kiến tạo các điều kiện thúc đẩy lực lượng sản xuất phát triển phù hợp với xu thế thời đại."],"a":3},{"lv":3,"id":"c3-164","ch":3,"n":164,"q":"Việc Bộ Công an và các cơ quan hành chính nhà nước quyết liệt triển khai Đề án 06 về “Phát triển ứng dụng dữ liệu về dân cư, định danh và xác thực điện tử phục vụ chuyển đổi số quốc gia giai đoạn 2022 - 2025, tầm nhìn đến năm 2030” nhằm tích hợp các thủ tục hành chính trực tiếp phản ánh chức năng nào của nhà nước?","o":["Chức năng thống trị chính trị nhằm triệt tiêu hoàn toàn quyền tự do cư trú của công dân.","Chức năng đối ngoại để đồng bộ hóa hệ thống dữ liệu quốc gia với cơ sở dữ liệu của các liên minh quân sự thế giới.","Chức năng xã hội trong việc hiện đại hóa quản lý cư dân, nâng cao hiệu lực, hiệu quả của bộ máy hành chính phục vụ nhân dân và phát triển kinh tế - xã hội.","Chức năng trấn áp bạo lực đối với toàn bộ các hoạt động sản xuất kinh doanh tự do của nhân dân."],"a":2},{"lv":3,"id":"c3-165","ch":3,"n":165,"q":"Luật Thực hiện dân chủ ở cơ sở năm 2022 (có hiệu lực từ 01/7/2023) quy định rõ phương châm: “Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng”. Việc ban hành đạo luật này thể hiện sự vận dụng trực tiếp nguyên lý triết học nào về Nhà nước pháp quyền xã hội chủ nghĩa ở nước ta?","o":["Khẳng định quyền quyết định tối cao và duy nhất thuộc về bộ máy chuyên chế chuyên nghiệp của nhà nước.","Bản chất dân chủ của Nhà nước pháp quyền XHCN Việt Nam là nhà nước của nhân dân, do nhân dân, vì nhân dân; phát huy quyền làm chủ thực tế của quần chúng nhân dân trong quản lý nhà nước và xã hội.","Việc chuyển giao toàn bộ chức năng trấn áp tội phạm từ nhà nước sang các tổ chức tự trị tự phát của nhân dân.","Sự đồng nhất hoàn toàn cơ chế dân chủ gián tiếp tư sản với chế độ tập trung dân chủ vô sản."],"a":1},{"lv":3,"id":"c3-166","ch":3,"n":166,"q":"Nghị quyết số 27-NQ/TW của Ban Chấp hành Trung ương Đảng khóa XIII xác định mục tiêu trọng tâm: “Tiếp tục xây dựng và hoàn thiện Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam của Nhân dân, do Nhân dân, vì Nhân dân do Đảng Cộng sản Việt Nam lãnh đạo”. Điểm nào dưới đây phản ánh đúng việc vận dụng nguyên tắc tổ chức quyền lực trong nhà nước pháp quyền ở nước ta?","o":["Áp dụng hoàn toàn mô hình “Tam quyền phân lập” độc lập và đối trọng tuyệt đối giữa các cơ quan nhà nước.","Chuyển giao toàn bộ quyền lực hành pháp cho các tổ chức kinh tế tư nhân tự điều hành.","Giải tán hệ thống cơ quan tư pháp để tập trung toàn bộ quyền lực vào một cá nhân duy nhất đứng đầu.","Quyền lực nhà nước là thống nhất, có sự phân công, phối hợp, kiểm soát giữa các cơ quan nhà nước trong việc thực hiện các quyền lập pháp, hành pháp, tư pháp."],"a":3},{"lv":3,"id":"c3-167","ch":3,"n":167,"q":"Điểm khác biệt căn bản về mặt bản chất giữa cấu trúc quyền lực trong Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam với nhà nước pháp quyền tư sản ở phương Tây là:","o":["Nhà nước pháp quyền tư sản hướng tới bảo vệ lợi ích của tuyệt đại đa số quần chúng nhân dân lao động; còn nhà nước ta bảo vệ lợi ích của tập đoàn thiểu số bóc lột.","Nhà nước pháp quyền tư sản không sử dụng hệ thống luật pháp hành chính; còn nhà nước ta hoàn toàn không sử dụng các biện pháp bạo lực pháp lý.","Nhà nước pháp quyền tư sản tổ chức theo nguyên tắc “Tam quyền phân lập”; còn Nhà nước pháp quyền XHCN Việt Nam tổ chức theo nguyên tắc quyền lực nhà nước là thống nhất dưới sự lãnh đạo của Đảng, có sự phân công, phối hợp và kiểm soát nhằm mục tiêu tối cao bảo vệ lợi ích của nhân dân.","Nhà nước pháp quyền tư sản không mang tính giai cấp chính trị; còn nhà nước ta chỉ thực hiện duy nhất chức năng đối ngoại."],"a":2},{"lv":3,"id":"c3-168","ch":3,"n":168,"q":"Nghị quyết Trung ương 4 (khóa XII, XIII) và tinh thần chỉ đạo hướng tới Đại hội XIV của Đảng nhấn mạnh việc kiên quyết đấu tranh ngăn chặn, đẩy lùi sự suy thoái về tư tưởng chính trị, đạo đức, lối sống, những biểu hiện “tự diễn biến”, “tự chuyển hóa” trong nội bộ cán bộ, đảng viên. Vận dụng kiến thức đã học về “Nhân tố chủ quan trong cách mạng xã hội và bảo vệ chế độ”, anh (chị) lựa chọn đáp án nào?","o":["Đây là hiện tượng bình thường, không ảnh hưởng đến sự tồn vong của HTKT-XH xã hội chủ nghĩa.","“Tự diễn biến”, “tự chuyển hóa” thực chất là sự tha hóa về mặt ý thức chính trị, làm suy yếu bản lĩnh cách mạng từ bên trong bộ máy quyền lực nhà nước.","Đây là xu thế tích cực thúc đẩy quá trình hòa nhập nhanh chóng với hệ tư tưởng tư sản quốc tế.","Việc nhà nước áp dụng bạo lực hành chính để giải tán toàn bộ các ban chỉ đạo kiểm tra đảng cấp cơ sở."],"a":1},{"lv":3,"id":"c3-169","ch":3,"n":169,"q":"Hiện nay, Đảng ta chủ trương xây dựng Nhà nước Việt Nam phát triển theo hướng nào?","o":["Nhà nước tư sản","Nhà nước pháp quyền","Nhà nước pháp quyền xã hội chủ nghĩa","Nhà nước quân chủ"],"a":2},{"lv":3,"id":"c3-170","ch":3,"n":170,"q":"Nhà nước Việt Nam thuộc hình thức nào trong các hình thức nhà nước liệt kê sau đây?","o":["Cộng hòa dân chủ","Cộng hòa dân chủ nhân dân","Xô Viết","Cộng hòa đại nghị"],"a":1},{"lv":3,"id":"c3-171","ch":3,"n":171,"q":"Bộ máy cai trị của nhà nước bao gồm:","o":["Lực lượng vũ trang chuyên nghiệp và bộ máy hành chính.","Bộ máy hành chính và pháp luật của nó.","Quân đội, cảnh sát, tòa án.","Lực lượng vũ trang chuyên nghiệp và hệ thống pháp luật."],"a":0},{"lv":3,"id":"c3-172","ch":3,"n":172,"q":"Muốn cho cách mạng xã hội nổ ra và giành thắng lợi, ngoài tình thế cách mạng cần phải có:","o":["Sự khủng hoảng trong xã hội.","Nhân tố chủ quan.","Sự giác ngộ và tích cực của quần chúng nhân dân.","Sự chín muồi của nhân tố chủ quan và sự kết hợp đúng đắn giữa nhân tố chủ quan với nhân tố khách quan."],"a":3},{"lv":3,"id":"c3-173","ch":3,"n":173,"q":"Xu hướng của cách mạng xã hội trên thế giới hiện nay là?","o":["Xu hướng đối thoại, hòa giải đang là xu hướng chủ đạo hiện nay.","Xu hướng giữ vững độc lập tự chủ của quốc gia dân tộc, không phụ thuộc và không can thiệp vào công việc nội bộ của nhau, đấu tranh cho dân chủ, hòa bình và tiến bộ xã hội đang diễn ra mạnh mẽ.","Các quốc gia, dân tộc sẽ đi tới một xã hội dân chủ, tự do, công bằng, văn minh theo cách đi của mình thông qua các chính sách phát triển kinh tế - xã hội, văn hóa, giáo dục, y tế và khoa học - công nghệ.","Tất cả các đáp đều đúng."],"a":3},{"lv":3,"id":"c3-174","ch":3,"n":174,"q":"Nhiệm vụ trọng tâm của cuộc đấu tranh giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay là gì?","o":["Thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội.","Là cuộc đấu tranh giữa các nhân tố thúc đẩy đất nước theo định hướng xã hội chủ nghĩa với các nhân tố tác động nhằm cản trở đất nước theo mục tiêu độc lập dân tộc và chủ nghĩa xã hội.","Xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh.","Tất cả các đáp án."],"a":3},{"lv":3,"id":"c3-175","ch":3,"n":175,"q":"Tiêu chuẩn quan trọng nhất để đánh giá tiến bộ xã hội là?","o":["Sự trong sạch, vững mạnh của bộ máy nhà nước .","Sự phát triển của phương thức sản xuất.","Trình độ văn hóa của người dân.","Chất lượng cuộc sống của người dân."],"a":1},{"lv":4,"id":"c3-176","ch":3,"n":176,"q":"Tìm đáp án sai: Theo chủ nghĩa duy vật lịch sử, mối quan hệ giữa chức năng thống trị chính trị của giai cấp và chức năng xã hội của nhà nước là?","o":["Chức năng thống trị chính trị của giai cấp thống trị giữ địa vị quyết định, chi phối và định hướng chức năng xã hội của nhà nước.","Chức năng xã hội của nhà nước có vai trò rất quan trọng đối với sự duy trì trật tự xã hội. Nếu chính quyền nhà nước nào không chú ý tới chức năng xã hội thì sẽ nhanh chóng đi tới sự sụp đổ.","Chức năng thống trị chính trị của giai cấp và chức năng xã hội của nhà nước chỉ có mối quan hệ bề ngoài, không bản chất.","Chức năng thống trị chính trị và chức năng xã hội của nhà nước luôn có mối quan hệ biện chứng, tác động hữu cơ với nhau."],"a":2},{"lv":4,"id":"c3-177","ch":3,"n":177,"q":"Đáp án nào không phải là đặc trưng cơ bản của nhà nước theo quan điểm của chủ nghĩa duy vật lịch sử?","o":["Quản lý cư dân trên một vùng lãnh thổ nhất định.","Đảm bảo lợi ích cho toàn thể các giai cấp và tầng lớp trong xã hội.","Có hệ thống các cơ quan quyền lực chuyên nghiệp mang tính cưỡng chế đối với mọi thành viên.","Có hệ thống thuế khóa để nuôi bộ máy chính quyền."],"a":1},{"lv":4,"id":"c3-178","ch":3,"n":178,"q":"Xu hướng phát triển của nhà nước trong chủ nghĩa cộng sản là gì?","o":["Củng cố vững chắc quyền lực giai cấp.","Chuyển hóa thành nhà nước cộng sản.","Chuyển hóa thành nhà nước toàn cầu.","Nhà nước tự tiêu vong."],"a":3},{"lv":4,"id":"c3-179","ch":3,"n":179,"q":"Tại sao sử dụng phương pháp bạo lực cách mạng được coi là tất yếu trong xã hội có đối kháng giai cấp?","o":["Vì có lợi, ít gây đau khổ cho con người.","Vì giai cấp thống trị lỗi thời không bao giờ tự nguyện từ bỏ địa vị thống trị của mình.","Vì có lợi cho giai cấp cầm quyền đàn áp giai cấp bị thống trị.","Tất cả các đáp án đều sai."],"a":1},{"lv":4,"id":"c3-180","ch":3,"n":180,"q":"Phân tích mối quan hệ biện chứng giữa “tính giai cấp” và “tính xã hội” của Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam được thể hiện thông qua các quy định mới của Luật Bảo hiểm xã hội năm 2024 (giảm điều kiện thời gian đóng BHXH tối thiểu để hưởng lương hưu xuống 15 năm, mở rộng đối tượng thụ hưởng)?","o":["Tính giai cấp mâu thuẫn hoàn toàn và triệt tiêu tính xã hội trong hoạt động lập pháp.","Luật Bảo hiểm xã hội chỉ phản ánh tính xã hội thuần túy, hoàn toàn không mang bản chất giai cấp chính trị.","Việc nhà nước áp dụng bạo lực hành chính buộc toàn bộ doanh nghiệp FDI phải chuyển giao tài sản cho công nhân tự quản lý.","Tính giai cấp quyết định định hướng chính trị của Luật; tính xã hội là phương thức thực thi định hướng đó thông qua các chính sách an sinh cụ thể, chăm lo lợi ích cho đông đảo người lao động, tạo nền tảng ổn định xã hội."],"a":3},{"lv":4,"id":"c3-181","ch":3,"n":181,"q":"Ngày 1/11/1963, tại miền Nam Việt Nam diễn ra cuộc đảo chính quân sự lật đổ chính quyền độc tài gia đình trị Ngô Đình Diệm do một nhóm tướng lĩnh quân đội Sài Gòn thực hiện dưới sự giật dây của Mỹ. Hãy phân tích sự kiện này dưới góc độ lý luận cách mạng xã hội để chỉ ra sự khác biệt bản chất giữa “đảo chính” và “cách mạng xã hội”?","o":["Đảo chính làm thay đổi căn bản bản chất giai cấp của chính quyền nhà nước và lật đổ hoàn toàn quan hệ sản xuất cũ lỗi thời.","Đảo chính là phương pháp hòa bình không dùng bạo lực; còn cách mạng xã hội bắt buộc phải dùng các biện pháp thỏa hiệp kinh tế.","Đảo chính không làm thay đổi bản chất giai cấp của nhà nước và không thay thế hình thái kinh tế - xã hội cũ; còn cách mạng xã hội là sự biến đổi căn bản về chất, lật đổ giai cấp lỗi thời để đưa giai cấp tiên tiến lên nắm quyền, thay thế HTKT-XH.","Đảo chính là phong trào tự phát của tuyệt đại đa số quần chúng nhân dân lao động nghèo đói ở nông thôn."],"a":2},{"lv":5,"id":"c3-182","ch":3,"n":182,"q":"Anh (chị) hãy đánh giá tính khoa học và giá trị phương pháp luận của lý luận của chủ nghĩa Mác - Lênin về sự “tiêu vong” của nhà nước trong tiến trình lịch sử nhân loại?","o":["Đây là ảo tưởng duy tâm phi thực tế vì nhà nước là thực thể vĩnh viễn và không bao giờ biến mất trong mọi chế độ xã hội.","Nhận định này cổ súy cho các phong trào bạo loạn ly khai vô chính phủ chống phá các nhà nước pháp quyền hiện đại.","Việc nhà nước vô sản chủ động giải tán bộ máy bạo lực quân sự ngay trong thời kỳ quá độ đầy biến động.","Đây là nhận định khoa học vì nhà nước là phạm trù lịch sử, sẽ tự tiêu vong khi giai cấp bị xóa bỏ hoàn toàn."],"a":3},{"lv":5,"id":"c3-183","ch":3,"n":183,"q":"Trong tiến trình cải cách bộ máy hành chính nhà nước hiện nay, định hướng “Xây dựng Chính phủ liêm chính, kiến tạo phát triển, hành động, phục vụ Nhân dân” được Đảng và Nhà nước ta quán triệt sâu sắc. Từ lý luận của chủ nghĩa duy vật lịch sử, anh (chị) đánh giá định hướng này như thế nào?","o":["Định hướng này chưa phù hợp vì nhà nước chỉ cần tập trung duy nhất vào chức năng trấn áp bạo lực chính trị.","Đây là định hướng đúng đắn nhằm chủ động kiến tạo thể chế thuận lợi, thúc đẩy cơ sở hạ tầng kinh tế phát triển.","Định hướng này làm suy yếu vai trò chuyên chính chính trị của giai cấp lãnh đạo cách mạng vô sản.","Việc chuyển giao toàn bộ quyền hành pháp và lập pháp cho các tổ chức phi chính phủ đa quốc gia tự quản lý."],"a":1},{"lv":5,"id":"c3-184","ch":3,"n":184,"q":"Các thế lực thù địch thường tuyên truyền luận điệu đòi “phi chính trị hóa lực lượng vũ trang” (quân đội, công an phải đứng trung lập, ngoài chính trị, không cần đặt dưới sự lãnh đạo của Đảng Cộng sản Việt Nam). Đứng trên lập trường bản chất giai cấp của nhà nước, anh (chị) hãy đánh giá và phản bác luận điệu này như thế nào?","o":["Luận điệu này phù hợp với nguyên tắc phi giai cấp của lực lượng vũ trang trong nhà nước pháp quyền hiện đại.","Đây là mô hình tổ chức quân đội tiên tiến nhằm bảo đảm tính độc lập tuyệt đối của cơ quan lập pháp.","Đây là âm mưu mị dân nhằm tước bỏ công cụ bạo lực sắc bén bảo vệ Đảng, Nhà nước và Nhân dân.","Việc tách lực lượng vũ trang khỏi sự lãnh đạo của Đảng là điều kiện tiên quyết để hội nhập quốc tế."],"a":2},{"lv":5,"id":"c3-185","ch":3,"n":185,"q":"Trong các nhận định sau về nguồn gốc của nhà nước, nhận định nào phản ánh đầy đủ nhất quan điểm của chủ nghĩa Mác – Lênin?","o":["Nhà nước xuất hiện chủ yếu do xã hội phát triển đến trình độ cao, đòi hỏi phải có một tổ chức chuyên biệt để điều hành các công việc chung.","Nhà nước ra đời từ nhu cầu thỏa thuận giữa các thành viên trong xã hội nhằm bảo đảm trật tự và bảo vệ lợi ích chung.","Nhà nước xuất hiện khi xã hội phát triển đến một trình độ nhất định, gắn với sự xuất hiện chế độ tư hữu, sự phân chia xã hội thành các giai cấp có lợi ích đối kháng và mâu thuẫn giai cấp phát triển đến mức không thể điều hòa.","Nhà nước hình thành chủ yếu do sự phát triển của quyền lực chính trị, khi cộng đồng xã hội cần một bộ máy cưỡng chế đủ mạnh để duy trì sự ổn định."],"a":2},{"lv":5,"id":"c3-186","ch":3,"n":186,"q":"Đặt kiểu nhà nước và hình thức nhà nước trong cùng một hệ thống phân loại. Kết luận nào sau đây chính xác nhất?","o":["Kiểu nhà nước được xác định chủ yếu bởi hình thức chính thể; do đó, các nhà nước có cùng chính thể về cơ bản thuộc cùng một kiểu nhà nước.","Hình thức nhà nước phản ánh trực tiếp bản chất kinh tế của nhà nước, còn kiểu nhà nước chủ yếu phản ánh cách thức tổ chức bộ máy quyền lực.","Kiểu nhà nước phản ánh bản chất giai cấp và cơ sở kinh tế – xã hội của nhà nước; hình thức nhà nước phản ánh cách thức tổ chức và phương pháp thực hiện quyền lực nhà nước.","Kiểu nhà nước và hình thức nhà nước đều phản ánh bản chất giai cấp nên về cơ bản có thể sử dụng hai khái niệm này thay thế cho nhau."],"a":2},{"lv":6,"id":"c3-187","ch":3,"n":187,"q":"Để giải quyết hài hòa mâu thuẫn giữa phát triển kinh tế và bảo vệ môi trường hướng tới mục tiêu Net Zero 2050, anh (chị) đề xuất mô hình phối hợp nào thể hiện sự vận dụng tối ưu chức năng xã hội của nhà nước?","o":["Xây dựng Mô hình đối tác công - tư xanh (Green PPP) kết hợp sự kiến tạo thể chế của Nhà nước, đầu tư đổi mới của Doanh nghiệp và giám sát của Cộng đồng.","Chuyển giao toàn bộ cơ chế điều tiết môi trường cho hệ thống tín chỉ carbon phái sinh do các quỹ đầu tư quốc tế tự vận hành.","Áp dụng thuế tiêu thụ đặc biệt ở mức tối đa lên tất cả các ngành công nghiệp chế tạo nhằm ép buộc thu hẹp quy mô sản xuất.","Ưu tiên tập trung ngân sách cho các ngành khai khoáng truyền thống để tích lũy tài chính vĩ mô trước khi xử lý ô nhiễm."],"a":0},{"lv":6,"id":"c3-188","ch":3,"n":188,"q":"Để khơi dậy sức mạnh nguồn nhân lực chất lượng cao phục vụ chuyển đổi số và công nghiệp bán dẫn trong kỷ nguyên mới, phương án tổng thể nào phản ánh việc vận dụng sáng tạo lý luận về “Nhân tố chủ quan và vai trò của quần chúng trong lịch sử”?","o":["Tập trung toàn bộ nguồn lực tài chính vào việc mua bản quyền sáng chế công nghệ tiên tiến từ các tập đoàn đa quốc gia.","Xây dựng mô hình liên kết ba bên \"Nhà nước - Nhà trường - Doanh nghiệp\" gắn với bồi dưỡng bản lĩnh chính trị và khát vọng cống hiến cho thế hệ trẻ.","Chuyển hoàn toàn mô hình đào tạo nhân lực bán dẫn sang cơ chế xã hội hóa tự phát do thị trường lao động tự điều tiết.","Ưu tiên cử một số ít chuyên gia xuất sắc đi đào tạo biệt lập ở nước ngoài để về đảm nhận các vị trí quản lý vĩ mô."],"a":1},{"lv":1,"id":"c3-189","ch":3,"n":189,"q":"Điền đáp án đúng vào chỗ trống sau: Khái niệm … dùng để chỉ phương diện sinh hoạt vật chất và các điều kiện sinh hoạt vật chất của xã hội.","o":["Lực lượng sản xuất","Kiến trúc thượng tầng.","Tồn tại xã hội.","Quan hệ sản xuất."],"a":2},{"lv":1,"id":"c3-190","ch":3,"n":190,"q":"Các yếu tố cấu thành tồn tại xã hội bao gồm:","o":["Phương thức sản xuất và điều kiện tự nhiên – hoàn cảnh địa lý.","Phương thức sản xuất, điều kiện tự nhiên – hoàn cảnh địa lý và dân cư.","Phương thức sản xuất, xã hội và dân cư.","Điều kiện tự nhiên - hoàn cảnh địa lý và dân cư."],"a":1},{"lv":1,"id":"c3-191","ch":3,"n":191,"q":"Khái niệm ý thức xã hội dùng để chỉ:","o":["Phương diện sinh hoạt vật chất của xã hội.","Phương diện sinh hoạt tinh thần của một giai cấp.","Phương diện sinh hoạt tinh thần của đời sống xã hội, nảy sinh từ tồn tại xã hội và phản ánh tôn tại xã hội trong những giai đoạn nhất định.","Những đặc trưng về tâm lý, tính cách của một cộng đồng dân tộc."],"a":2},{"lv":1,"id":"c3-192","ch":3,"n":192,"q":"Hình thái ý thức xã hội nào sau đây ra đời từ khi xã hội chưa phân chia giai cấp?","o":["Ý thức triết học.","Ý thức tôn giáo.","Ý thức chính trị.","Ý thức pháp quyền."],"a":1},{"lv":2,"id":"c3-193","ch":3,"n":193,"q":"Chọn đáp án đúng về đặc điểm hệ tư tưởng.","o":["Hệ tư tưởng ra đời trực tiếp từ tâm lý xã hội.","Hệ tư tưởng là hệ thống những quan điểm, hệ thống hóa, khái quát hóa thành lý luận, thành các học thuyết chính trị - xã hội phản ánh lợi ích của một giai cấp nhất định.","Trong xã hội có giai cấp thì chỉ có hệ tư tưởng biểu hiện tính giai cấp của ý thức xã hội.","Hệ tư tưởng không ảnh hưởng đến sự phát triển của khoa học."],"a":1},{"lv":2,"id":"c3-194","ch":3,"n":194,"q":"Đâu là nhận định đúng về ý thức xã hội thông thường?","o":["Những tri thức, quan niệm được hình thành trực tiếp trong các hoạt động hàng ngày của con người; chưa được hệ thống hoá, chưa được hợp thức và khái quát hoá.","Những tri thức, quan niệm được hình thành trực tiếp trong các hoạt động hàng ngày của con người; đã được tổng hợp, hệ thống hoá và khái quát hoá thành các học thuyết.","Những tư tưởng, quan điểm của con người trong cuộc sống, đã được tổng hợp, hệ thống hoá và khái quát hoá thành các học thuyết.","Những tư tưởng, quan điểm của con người trong cuộc sống; chưa được hệ thống hoá, chưa được hợp thức và khái quát hoá."],"a":0},{"lv":2,"id":"c3-195","ch":3,"n":195,"q":"Chọn đáp án đúng theo quan điểm triết học Mác - Lênin về đặc điểm tâm lý xã hội.","o":["Tâm lý xã hội là sự phản ánh mang tính kinh nghiệm, yếu tố trí tuệ và đan xen yếu tố tình cảm.","Tâm lý xã hội là sự phản ánh gián tiếp có tính tự phát, thường ghi lại những mặt bề ngoài tồn tại xã hội.","Tâm lý xã hội mang tính phong phú và phức tạp, nhưng không tuân theo các quy luật tâm lý.","Tâm lý xã hội không có vai trò quan trọng trong ý thức xã hội."],"a":1},{"lv":2,"id":"c3-196","ch":3,"n":196,"q":"Chọn đáp án đúng nhất về tâm lý xã hội.","o":["Tâm lý xã hội cho biết những mối liên hệ khách quan, bản chất, tất yếu mang tính quy luật của các sự vật và quá trình xã hội.","Tâm lý xã hội phản ánh một cách trực tiếp và tự phát những điều kiện sinh hoạt hằng ngày của con người.","Tâm lý xã hội phản ánh một cách trực tiếp và tự giác những điều kiện sinh hoạt hằng ngày của con người.","Tâm lý xã hội không bao gồm tư tưởng của xã hội hình thành dưới tác động trực tiếp của cuộc sống hằng ngày."],"a":1},{"lv":2,"id":"c3-197","ch":3,"n":197,"q":"Chọn đáp án đúng về vai trò của tồn tại xã hội trong quan hệ biện chứng với ý thức xã hội.","o":["Ý thức xã hội hoàn toàn phụ thuộc một cách thụ động vào tồn tại xã hội.","Tồn tại xã hội quyết định ý thức xã hội.","Khi tồn tại xã hội đã thay đổi thì toàn bộ các yếu tố cấu thành ý thức xã hội biến đổi theo cùng tồn tại xã hội.","Tồn tại xã hội có vai trò quyết định đối với các hình thái ý thức xã hội một cách đơn giản, trực tiếp, không qua các khâu trung gian."],"a":1},{"lv":2,"id":"c3-198","ch":3,"n":198,"q":"Chọn đáp án đúng nhất về tính độc lập tương đối của ý thức xã hội.","o":["Các hình thái ý thức xã hội trong quá trình phản ánh hiện thực có tác động trở lại tồn tại xã hội như nhau.","Ý thức xã hội luôn luôn lạc hậu hơn so với tồn tại xã hội vì không phản ánh kịp hoạt động thực tiễn.","Không thể giải thích một tư tưởng nào đó nếu chỉ dựa vào những quan hệ kinh tế hiện có mà không chú ý đến các giai đoạn phát triển tư tướng đó.","Ý thức xã hội tác động trở lại tồn tại xã hội theo hai chiều hướng hoặc thúc đẩy hoặc kìm hãm; mức độ tác động đó chỉ phụ thuộc vào điều kiện lịch sử cụ thể."],"a":2},{"lv":2,"id":"c3-199","ch":3,"n":199,"q":"Yếu tố nào sau đây là yếu tố cơ bản nhất của tồn tại xã hội?","o":["Điều kiện tự nhiên.","Dân số.","Phương thức sản xuất vật chất.","Năng suất lao động."],"a":2},{"lv":2,"id":"c3-200","ch":3,"n":200,"q":"Ý thức xã hội bao gồm các hình thái ý thức xã hội cơ bản nào?","o":["Ý thức chính trị, ý thức pháp quyền, ý thức đạo đức, ý thức văn hóa, ý thức tôn giáo, ý thức khoa học, ý thức triết học.","Ý thức chính trị, ý thức pháp quyền, ý thức đạo đức, ý thức thẩm mỹ, ý thức tôn giáo, ý thức khoa học, ý thức triết học.","Ý thức chính trị, ý thức pháp quyền, ý thức đạo đức, ý thức dân tộc, ý thức tôn giáo, ý thức khoa học, ý thức triết học.","Ý thức chính trị, ý thức pháp quyền, ý thức văn hóa, ý thức môi trường, ý thức tôn giáo, ý thức khoa học, ý thức triết học."],"a":1},{"lv":2,"id":"c3-201","ch":3,"n":201,"q":"Khi tồn tại xã hội thay đổi thì:","o":["Ý thức tôn giáo sẽ không thay đổi.","triết học sẽ thay đổi triệt để.","Ý thức xã hội sớm hay muộn cũng sẽ có những thay đổi nhất định.","Ý thức xã hội sẽ thay đổi một cách hệ thống và đồng bộ."],"a":2},{"lv":2,"id":"c3-202","ch":3,"n":202,"q":"Trong xã hội có giai cấp, hình thái ý thức xã hội nào quyết định đến các hình thái ý thức xã hội còn lại?","o":["Ý thức đạo đức","Ý thức chính trị","Ý thức thẩm mỹ","Ý thức pháp quyền"],"a":1},{"lv":2,"id":"c3-203","ch":3,"n":203,"q":"Ý thức xã hội không phụ thuộc vào tồn tại xã hội một cách thụ động mà còn có tác động tích cực trở lại tồn tại xã hội, đó là sự thể hiện:","o":["Tính độc lập tương đối của ý thức xã hội.","Tính định hướng của ý thức xã hội.","Ý thức xã hội luôn có tính vượt trước.","Tất cả các đáp án."],"a":0},{"lv":2,"id":"c3-204","ch":3,"n":204,"q":"Điều kiện cơ bản để ý thức xã hội tác động trở lại tồn tại xã hội là:","o":["Ý thức xã hội phải phù hợp với tồn tại xã hội.","Hoạt động thực tiễn của con người.","Điều kiện vật chất bảo đảm.","Ý thức xã hội phải “vượt trước” tồn tại xã hội."],"a":1},{"lv":3,"id":"c3-205","ch":3,"n":205,"q":"Vận dụng kiến thức nào của chủ nghĩa duy vật lịch sử để giải thích trong giai đoạn hiện nay vẫn còn tồn tại tư tưởng “trọng nam, khinh nữ”?","o":["Ý thức xã hội có tính vượt trước so với tồn tại xã hội.","Ý thức xã hội có tính kế thừa trong sự phát triển.","Có sự tác động qua lại giữa các hình thái ý thức xã hội khác nhau.","Ý thức xã hội thường lạc hậu hơn so với tồn tại xã hội."],"a":3},{"lv":3,"id":"c3-206","ch":3,"n":206,"q":"Vận dụng kiến thức nào của chủ nghĩa duy vật lịch sử để giải thích câu nói: “sức mạnh của thói quen, của phong tục, tập quán là sức mạnh bảo thủ ghê gớm nhất”?","o":["Quan hệ sản xuất tác động ngược trở lại lực lượng sản xuất.","Tính độc lập tương đối của ý thức xã hội so với tồn tại xã hội.","Cơ sở hạ tầng quyết định kiến trúc thượng tầng.","Không có đáp án nào."],"a":1},{"lv":3,"id":"c3-207","ch":3,"n":207,"q":"Vận dụng kiến thức đã học về ý thức xã hội, anh (chị) hãy cho biết: Tâm lý tiểu nông của người Việt Nam truyền thống căn bản là do:","o":["Bản tính cố hữu của người Việt.","Bị đế quốc, phong kiến nhiều thế kỷ áp bức, bóc lột.","Phương thức sản xuất tiểu nông, manh mún, lạc hậu.","Tất cả các phương án đều sai."],"a":2},{"lv":3,"id":"c3-208","ch":3,"n":208,"q":"Vận dụng kiến thức đã học về ý thức xã hội, anh (chị) hãy cho biết: Lối sống, phong tục tập quán của con người ở những vùng miền khác nhau là do:","o":["Tồn tại xã hội quyết định.","Sở thích theo nhóm người.","Sự khác nhau của ngôn ngữ.","Sự khác nhau về nhà nước và pháp luật."],"a":0},{"lv":3,"id":"c3-209","ch":3,"n":209,"q":"Vận dụng kiến thức đã học về ý thức xã hội, anh (chị) hãy cho biết: “Điều kiện sinh hoạt vật chất của xã hội biến đổi đến đâu thì ngay lập tức tâm lý xã hội và hệ tư tưởng xã hội cũng lập tức biến đổi đến đó”. Nhận định này đúng hay sai?","o":["Sai. Vì ý thức xã hội phụ thuộc vào tồn tại xã hội nhưng nó có tính độc lập tương đối.","Đúng. Vì tồn tại xã hội nào thì ý thức xã hội đó.","Đúng. Vì ý thức xã hội luôn luôn vượt trước tồn tại xã hội.","Sai. Vì ý thức xã hội luôn luôn lạc hậu hơn so với tồn tại xã hội."],"a":0},{"lv":3,"id":"c3-210","ch":3,"n":210,"q":"Vận dụng kiến thức đã học, anh (chị) hãy lựa chọn đáp án SAI về ý thức xã hội?","o":["Ý thức xã hội là sự phản ánh tồn tại xã hội.","Ý thức xã hội có tính độc lập tương đối trong quan hệ với tồn tại với xã hội.","Ý thức xã hội là đời sống chính trị của xã hội.","Ý thức xã hội không đồng nhất với ý thức cá nhân."],"a":2},{"lv":3,"id":"c3-211","ch":3,"n":211,"q":"Vận dụng kiến thức đã học, anh (chị) hãy lựa chọn đáp án đúng nhất về ý thức xã hội?","o":["Ý thức xã hội luôn lạc hậu hơn tồn tại xã hội.","Ý thức xã hội có thể lạc hậu, có thể vượt trước, có tính kế thừa, có sự tác động giữa các hình thái ý thức xã hội và có tính tác động ngược trở lại tồn tại xã hội.","Ý thức xã hội có tính vượt trước nên ý thức xã hội sẽ đóng vai trò quan trọng quyết định tồn tại xã hội.","Ý thức xã hội có trước và quyết định đến tồn tại xã hội."],"a":1},{"lv":3,"id":"c3-212","ch":3,"n":212,"q":"Một người thợ cơ khí lành nghề có thể vận hành máy tiện truyền thống rất nhanh chóng nhờ các tri thức kinh nghiệm tích lũy kinh nghiệm hằng ngày, nhưng khi được đào tạo về các tri thức toán học, nguyên lý sức bền vật liệu và các kiến thức chuyên ngành người thợ có thể tự thiết kế và vận hành máy tiện kỹ thuật số CNC hiện đại. Tình huống này phản ánh mối quan hệ nào?","o":["Ý thức thông thường cung cấp chất liệu kinh nghiệm phong phú, nhưng ý thức lý luận mới phản ánh đúng bản chất quy luật sâu sắc để định hướng thực tiễn đột phá.","Ý thức thông thường phản ánh thế giới sâu sắc, chính xác và có hệ thống hơn so với ý thức lý luận khoa học.","Ý thức lý luận khoa học chỉ sử dụng trong các hội thảo khoa học, không áp dụng được trong thực tế công việc.","Sinh viên kỹ thuật chỉ cần học các mẹo kinh nghiệm thực tế, hoàn toàn không cần học các lý thuyết cơ sở ngành."],"a":0},{"lv":3,"id":"c3-213","ch":3,"n":213,"q":"Sinh viên tích cực tham gia nghiên cứu, học tập đầy đủ các môn lý luận chính trị để hiểu rõ sâu sắc đường lối phát triển của Đảng, từ đó có định hướng nghề nghiệp đúng đắn phục vụ Tổ quốc. Vận dụng lý luận về ý thức xã hội, anh (chị) hãy cho biết vai trò của hình thái ý thức xã hội nào đang được phát huy?","o":["Ý thức chính trị giữ vai trò chủ đạo trong đời sống tinh thần, định hướng cho các hoạt động và các hình thái ý thức xã hội khác phát triển lành mạnh.","Ý thức chính trị giữ không giữ vai trò chủ đạo, mà là ý thức cá nhân mới quyết định trong tinh thần, định hướng cho các hoạt động và các hình thái ý thức xã hội khác.","Ý thức chính trị hoàn toàn thay thế vai trò của các hình thái ý thức khoa học kỹ thuật và ý thức đạo đức.","Ý thức chính trị là một dạng ý thức thụ động, luôn đi sau và chịu sự quyết định tuyệt đối của ý thức tôn giáo."],"a":0},{"lv":3,"id":"c3-214","ch":3,"n":214,"q":"Khi hoàn thành đồ án tốt nghiệp thiết kế chi tiết máy, sinh viên nghiêm túc tự giác khai báo nguồn tài liệu tham khảo và tuyệt đối không sao chép công trình của các khóa trước nhằm chấp hành Luật Sở hữu trí tuệ của Nhà nước. Hành vi tự giác này là biểu hiện của hình thái ý thức nào?","o":["Ý thức pháp quyền định hướng ý thức cá nhân hướng đến sự tự giác chấp hành.","Ý thức pháp quyền mang tính cưỡng chế, cá nhân tuân thủ mệnh lệnh một cách hình thức.","Ý thức pháp quyền độc lập với điều kiện sinh hoạt kinh tế và phương thức sản xuất của xã hội.","Vấn đề trên là do sinh viên có ý thức đạo đức khoa học cao, không cần đến luật pháp cũng tự giác thực hiện."],"a":0},{"lv":3,"id":"c3-215","ch":3,"n":215,"q":"Một kỹ sư Công nghệ thông tin dựa vào các nguyên lý toán học và thuật toán tối ưu hóa cấu trúc dữ liệu để xây dựng phần mềm quản lý kho thông minh, thay vì đưa ra các giải pháp sửa lỗi theo phán đoán cảm tính, may rủi. Việc làm của người kỹ sư này phản ánh đặc trưng của hình thái ý thức xã hội nào?","o":["Ý thức khoa học có tính khuôn mẫu, làm việc theo quy định và quy chuẩn không được phép sai sót.","Ý thức khoa học luôn mang tính siêu hình, máy móc các mối quan hệ nhân quả khách quan thực tế trong sản xuất.","Ý thức khoa học hoàn toàn độc lập và không mang lại hiệu quả thực tế nào đối với sự phát triển của sản xuất vật chất.","Ý thức khoa học phản ánh thế giới khách quan một cách chân thực bằng hệ thống khái niệm, quy luật logic, tri thức chính xác đã được thực tiễn kiểm nghiệm."],"a":3},{"lv":3,"id":"c3-216","ch":3,"n":216,"q":"Trong quá trình học đại học, một số sinh viên vẫn giữ thói quen học tập thụ động, chờ giảng viên đọc và chép. Hiện tượng này thể hiện rõ nét nhất biểu hiện nào trong tính độc lập tương đối của ý thức xã hội?","o":["Ý thức xã hội thường biến đổi chậm hơn so với sự phát triển nhanh chóng của tồn tại xã hội.","Ý thức xã hội luôn vượt trước tồn tại xã hội trong mọi điều kiện của quá trình biến đổi công nghệ.","Sự tác động qua lại chặt chẽ giữa ý thức thẩm mỹ với ý thức chính trị của người công nhân trong nhà máy.","Ý thức xã hội hoàn toàn độc lập và không chịu sự quy định hay quyết định nào từ phía tồn tại xã hội."],"a":0},{"lv":4,"id":"c3-217","ch":3,"n":217,"q":"Yếu tố nào quyết định nội dung, tính chất, đặc điểm, xu hướng vận động, sự biến đổi và phát triển của các hình thái ý thức xã hội?","o":["Ý thức xã hội thông thường, vì nó hình thành trực tiếp từ hoạt động thực tiễn hàng ngày.","Tồn tại xã hội, trong đó phương thức sản xuất vật chất là yếu tố cơ bản nhất.","Hệ tư tưởng xã hội, vì đây là trình độ cao của ý thức xã hội.","Tâm lý xã hội, vì nó phản ánh trực tiếp đời sống hàng ngày của xã hội."],"a":1},{"lv":4,"id":"c3-218","ch":3,"n":218,"q":"Phân tích nào đúng nhất về mối quan hệ giữa tồn tại xã hội và ý thức xã hội?","o":["Tồn tại xã hội quyết định ý thức xã hội, còn ý thức xã hội hoàn toàn thụ động trước tồn tại xã hội.","Ý thức xã hội quyết định sự biến đổi của tồn tại xã hội thông qua các hình thái ý thức khác nhau.","Tồn tại xã hội quyết định ý thức xã hội, đồng thời ý thức xã hội có tính độc lập tương đối và tác động trở lại tồn tại xã hội.","Tồn tại xã hội và ý thức xã hội tồn tại độc lập, chỉ tác động với nhau trong những giai đoạn lịch sử nhất định."],"a":2},{"lv":4,"id":"c3-219","ch":3,"n":219,"q":"Phân tích nào đúng nhất về sự tác động qua lại giữa các hình thái ý thức xã hội?","o":["Các hình thái ý thức xã hội hoàn toàn độc lập vì mỗi hình thái phản ánh một lĩnh vực riêng biệt.","Các hình thái ý thức xã hội có sự tác động qua lại; trong từng thời đại có thể có một hình thái nổi lên hàng đầu và tác động mạnh đến các hình thái khác.","Ý thức chính trị luôn là hình thái duy nhất có khả năng tác động đến các hình thái ý thức xã hội khác.","Ý thức khoa học luôn giữ vai trò hàng đầu trong mọi thời đại lịch sử."],"a":1},{"lv":4,"id":"c3-220","ch":3,"n":220,"q":"Nhận định nào sau đây KHÔNG phù hợp với tính độc lập tương đối của ý thức xã hội?","o":["Ý thức xã hội có thể kế thừa những thành tựu lý luận của các thời đại trước.","Ý thức xã hội có thể vượt trước tồn tại xã hội trong những điều kiện nhất định.","Ý thức xã hội có thể tác động trở lại tồn tại xã hội theo hướng thúc đẩy hoặc kìm hãm.","Ý thức xã hội luôn vận động nhanh hơn tồn tại xã hội vì nó có khả năng vượt trước tồn tại xã hội."],"a":3},{"lv":4,"id":"c3-221","ch":3,"n":221,"q":"Phân tích nào đúng nhất về vai trò của ý thức chính trị trong mối quan hệ giữa các hình thái ý thức xã hội?","o":["Ý thức chính trị chỉ phản ánh quan hệ giữa các giai cấp nên không có khả năng tác động đến các hình thái ý thức khác.","Ý thức chính trị có vai trò đặc biệt quan trọng; trong xã hội có giai cấp đối kháng, ý thức chính trị của giai cấp cách mạng có thể định hướng sự phát triển theo chiều hướng tiến bộ của các hình thái ý thức xã hội khác.","Ý thức chính trị luôn quyết định tuyệt đối các hình thái ý thức xã hội khác, không phụ thuộc vào điều kiện lịch sử.","Ý thức chính trị chỉ tác động đến ý thức pháp quyền vì hai hình thái này đều ra đời cùng với nhà nước."],"a":1},{"lv":5,"id":"c3-222","ch":3,"n":222,"q":"Theo phương pháp luận của triết học Mác-Lênin về kết cấu ý thức xã hội, giải pháp nào tối ưu nhất để nâng cao hàm lượng trí tuệ cho tâm lý xã hội trong đời sống tinh thần?","o":["Thay thế hoàn bộ tâm lý xã hội bằng ý thức xã hội thông thường thông qua hoạt động thực tiễn hàng ngày.","Sử dụng hệ tư tưởng khoa học để bổ sung, làm gia tăng hàm lượng trí tuệ và định hướng tâm lý xã hội phát triển tích cực.","Loại bỏ hoàn toàn hệ tư tưởng vì nó mang tính công thức cứng nhắc và xơ cứng.","Tách rời tâm lý xã hội khỏi hệ tư tưởng để đảm bảo tính tự phát của thói quen và tập quán."],"a":1},{"lv":5,"id":"c3-223","ch":3,"n":223,"q":"Khi đánh giá về kết cấu ý thức xã hội, nhận định nào dưới đây KHÔNG thuyết phục nhất theo tiêu chí phân loại trình độ phản ánh?","o":["Ý thức xã hội thông thường là tri thức hình thành trực tiếp trong hoạt động thực tiễn hàng ngày, chưa được hệ thống hóa.","Ý thức lý luận thể hiện ở các học thuyết xã hội được trình bày dưới dạng khái niệm, phạm trù, quy luật.","Hệ tư tưởng không khoa học là trình độ phản ánh các quan hệ, quá trình xã hội một cách khách quan, chính xác.","Hệ tư tưởng là trình độ cao của ý thức xã hội, hình thành khi nhận thức sâu sắc hơn điều kiện sinh hoạt vật chất."],"a":2},{"lv":5,"id":"c3-224","ch":3,"n":224,"q":"Theo phương pháp luận duy vật lịch sử, chính sách nào nên ưu tiên khi giải quyết mối quan hệ giữa xóa bỏ tư tưởng cũ và xây dựng tư tưởng mới?","o":["Áp dụng ngay các biện pháp hành chính cưỡng chế để xóa bỏ triệt để thói quen cũ trong thời gian ngắn nhất.","Nóng vội xóa bỏ toàn bộ ý thức xã hội cũ mà không cần tính đến tốc độ biến đổi của tồn tại xã hội.","Từng bước xóa bỏ tàn dư tư tưởng cũ song song với bồi đắp ý thức mới, tuyệt đối không nóng vội hay dùng biện pháp hành chính.","Chờ đợi tự phát tư tưởng cũ mất đi mà không cần tiến hành đấu tranh trên lĩnh vực tư tưởng."],"a":2},{"lv":5,"id":"c3-225","ch":3,"n":225,"q":"Theo phương pháp luận Mác-Lênin, nhận định nào thuyết phục nhất khi đánh giá về vai trò tác động trở lại của ý thức xã hội đối với tồn tại xã hội?","o":["Mọi ý thức xã hội đều thúc đẩy tồn tại xã hội phát triển bất chấp tính chất phản ánh của nó.","Ý thức xã hội tác động trở lại tồn tại xã hội theo hai hướng: thúc đẩy nếu phản ánh đúng quy luật, kìm hãm nếu phản ánh sai quy luật.","Mức độ tác động của ý thức xã hội không phụ thuộc vào điều kiện lịch sử hay sự thâm nhập vào quần chúng.","Tác động trở lại tồn tại xã hội là đặc điểm yếu nhất và không đáng kể của ý thức xã hội."],"a":1},{"lv":6,"id":"c3-226","ch":3,"n":226,"q":"Nếu được giao làm Trưởng ban chỉ đạo phong trào “Nếp sống xanh - Tiết kiệm điện nước' tại khu nội trú sinh viên của trường” anh (chị) nên đề xuất giải pháp tổng thể nào sau đây?","o":["Phát động cuộc thi thiết kế thiết bị cảm biến thông minh, công tơ đo đếm điện nước tự động tại từng phòng; tổ chức thi đua phòng ở tiết kiệm, hiệu quả, văn minh; tổ chức các hoạt động ngoài trời về chủ đề xanh – sạch – đẹp.","Tổ chức tuyên truyền liên tục trên hệ thống loa phát thanh của ký túc xá và dán khẩu hiệu, áp phích cỡ lớn ở những nơi trung tâm và phòng ở ký túc xá để tác động trực tiếp vào nhận thức của sinh viên.","Đề xuất áp dụng biện pháp cắt điện và nước sinh hoạt của toàn bộ khu nội trú sau 22 giờ bởi vì thời điểm này sinh viên trong ký túc xá không còn nhu cầu sử dụng điện nước, đồng thời tăng dần tiền điện và nước sinh hoạt theo khối lượng sử dụng để sinh viên sử dụng tiết kiệm hơn.","Yêu cầu sinh viên ký bản cam kết tiết kiệm bằng văn bản gửi cho Khoa và Nhà trường và có chế tài đối với những người vi phạm điều khoản cam kết."],"a":0},{"lv":1,"id":"c3-227","ch":3,"n":227,"q":"Quan niệm của triết học Mác-Lênin về bản chất con người?","o":["Con người là một thực thể thống nhất giữa mặt sinh vật với mặt xã hội.","Trong tính hiện thực của nó con người là tổng hòa những quan hệ xã hội trên nền tảng sinh học.","Con người là chủ thể và là sản phẩm của lịch sử.","Tất cả các đáp án."],"a":3},{"lv":1,"id":"c3-228","ch":3,"n":228,"q":"Tha hóa của con người được đẩy lên mức cao nhất trong nền sản xuất của chế độ xã hội nào?","o":["Chiếm hữu Nô lệ","Phong kiến","Tư bản Chủ nghĩa","Cộng sản Chủ nghĩa"],"a":2},{"lv":1,"id":"c3-229","ch":3,"n":229,"q":"Theo quan điểm của Triết học Mác-Lênin, nguyên nhân của hiện tượng tha hóa của con người là gì?","o":["Do sự ý muốn chủ quan của con người.","Do sự sắp đặt của Thượng đế.","Do sự xuất hiện của chế độ tư hữu về tư liệu sản xuất.","Do chế độ sở hữu chung về tư liệu sản xuất."],"a":2},{"lv":1,"id":"c3-230","ch":3,"n":230,"q":"Điền từ còn thiếu vào chỗ trống của luận điểm sau: “Sự phát triển tự do của mỗi người là ... cho sự phát triển tự do của tất cả mọi người”?","o":["Điều kiện","Nguyên nhân","Lý do","Tiền đề"],"a":0},{"lv":1,"id":"c3-231","ch":3,"n":231,"q":"Theo chủ nghĩa duy vật lịch sử, chủ thể chính sáng tạo ra lịch sử là:","o":["Vĩ nhân.","Cá nhân.","Quần chúng nhân dân.","Giai cấp."],"a":2},{"lv":1,"id":"c3-232","ch":3,"n":232,"q":"Chọn đáp án đúng nhất, lịch sử xã hội loài người được quyết định bởi:","o":["Quần chúng nhân dân.","Mệnh trời.","Cá nhân anh hùng hào kiệt.","Không do ai quyết định, vì nó diễn ra theo quy luật tự nhiên."],"a":0},{"lv":1,"id":"c3-233","ch":3,"n":233,"q":"Quan điểm của chủ nghĩa Mác-Lênin về lãnh tụ là gì?","o":["Những cá nhân kiệt xuất có sự gắn bó với quần chúng nhân dân.","Những cá nhân kiệt xuất được quần chúng tín nhiệm.","Những cá nhân kiệt xuất tự nguyện hy sinh bản thân mình vì lợi ích của quần chúng nhân dân.","Tất cả các đáp án."],"a":3},{"lv":2,"id":"c3-234","ch":3,"n":234,"q":"Tiền đề xuất phát của quan điểm duy vật lịch sử về con người mà triết học Mác - Lênin nghiên cứu là gì?","o":["Con người cụ thể.","Con người trừu tượng.","Con người hiện thực.","Con người lý tưởng."],"a":2},{"lv":2,"id":"c3-235","ch":3,"n":235,"q":"Chủ nghĩa duy vật lịch sử coi con người là một bộ phận của giới tự nhiên, còn giới tự nhiên là...","o":["Đối tượng chinh phục của con người.","Đối tượng cải tạo của con người.","Thân thể vô cơ của con người.","Đối tượng vô cơ của con người."],"a":2},{"lv":2,"id":"c3-236","ch":3,"n":236,"q":"Con người mà triết học Mác – Lênin nghiên cứu là:","o":["Con người cụ thể.","Con người trừu tượng.","Con người hiện thực.","Con người lý tưởng."],"a":2},{"lv":2,"id":"c3-237","ch":3,"n":237,"q":"Nội dung nào thể hiện đúng nhất quan điểm của chủ nghĩa duy vật lịch sử về con người?","o":["Con người là sản phẩm của lịch sử, luôn chịu tác động của lịch sử.","Con người vừa là chủ thể của lịch sử, vừa là sản phẩm của lịch sử.","Con người sáng tạo ra lịch sử theo mong muốn chủ quan của mình.","Con người vừa là sản phẩm của lịch sử, vừa là bộ phận của lịch sử."],"a":1},{"lv":2,"id":"c3-238","ch":3,"n":238,"q":"Khái niệm cá nhân được xác định trong quan hệ nào sau đây?","o":["Trong quan hệ với loài.","Trong quan hệ với giai cấp.","Trong quan hệ với xã hội.","Trong quan hệ với nhà nước."],"a":2},{"lv":2,"id":"c3-239","ch":3,"n":239,"q":"Vai trò của lãnh tụ đối với phong trào của quần chúng nhân dân?","o":["Thúc đẩy hoặc kìm hãm sự tiến bộ của xã hội.","Là người sáng lập ra các tổ chức chính trị, xã hội và là linh hồn của các tổ chức đó.","Lãnh tụ của mỗi thời đại chỉ có thể hoàn thành những nhiệm vụ đặt ra của thời đại đó.","Tất cả các đáp án."],"a":3},{"lv":2,"id":"c3-240","ch":3,"n":240,"q":"Theo quan niệm của triết học Mác Lênin, mục đích cao nhất của sự phát triển xã hội là:","o":["Hạnh phúc và sự phát triển toàn diện của con người.","Tăng trưởng kinh tế.","Ổn định xã hội.","Bình đẳng xã hội."],"a":0},{"lv":2,"id":"c3-241","ch":3,"n":241,"q":"Biểu hiện tha hóa ở con người, theo quan điểm của Triết học Mác\u0002Lênin là gì?","o":["Con người đối xử với nhau tàn bạo hơn.","Con người bị đánh mất mình trong lao động.","Con người lao động tự giác và sáng tạo hơn.","Tất cả đáp án đều đúng."],"a":1},{"lv":2,"id":"c3-242","ch":3,"n":242,"q":"Điều kiện và tiền đề để giải phóng triệt để con người theo quan điểm của Triết học Mác-Lênin là gì?","o":["Xóa bỏ áp bức bất công.","Xóa bỏ giai cấp và chế độ sở hữu tư nhân về tư liệu sản xuất.","Xóa bỏ lao động.","Xóa bỏ chế độ công hữu về tư liệu sản xuất."],"a":1},{"lv":3,"id":"c3-243","ch":3,"n":243,"q":"Sinh viên TNUT, ngoài việc chăm chỉ học tập lý thuyết trên lớp, còn tích cực tham gia các giải thể thao chạy việt dã và bóng đá tự quản để tăng cường sức khỏe. Dưới góc nhìn triết học Mác – Lênin về con người, việc rèn luyện thể chất này đóng vai trò gì?","o":["Rèn luyện thể chất để phát triển phương diện sinh học - tạo tiền đề tự nhiên vật chất không thể thiếu để con người thực hiện tốt các hoạt động xã hội.","Tham gia các hoạt động thể thao do Nhà trường tổ chức để cải thiện điểm rèn luyện trong quá trình học tập.","Tham gia các hoạt động thể thao để tránh xa những cám dỗ từ môi trường xã hội độc hại.","Rèn luyện thể thao là rèn luyện thể chất thuần túy không có tác động đến các vấn đề xã hội."],"a":0},{"lv":3,"id":"c3-244","ch":3,"n":244,"q":"Một sinh viên ngành Kỹ thuật cơ điện tử muốn hoàn thiện kỹ năng thiết kế robot chế tạo máy, đã chủ động đăng ký tham gia Câu lạc bộ Sáng tạo trẻ, thường xuyên cùng nhóm chế taọ và thử nghiệm các mô hình thực tế. Việc làm này thể hiện sự vận dụng đúng đắn luận điểm triết học nào sau đây?","o":["Con người chỉ có thể bộc lộ và phát triển toàn diện nhân cách của mình trong môi trường có các quan hệ xã hội thực tế lành mạnh.","Bản chất con người là một cá thể độc lập, nhưng khi tham gia vào các cộng đồng mới có thể chứng tỏ năng lực cá nhân.","Con người tham gia vào các cộng đồng sẽ được sử dụng những nguồn lực mà cá nhân không có, điều này sẽ giúp cá nhân hoàn thành công việc của mình mà không tốn chi phí.","Tham gia vào các cộng đồng sẽ nâng giá trị của con người, tạo ấn tượng tốt và uy tín đối với mọi người."],"a":0},{"lv":3,"id":"c3-245","ch":3,"n":245,"q":"Khi thiết kế hệ thống nâng hạ hàng hóa tự động cho nhà kho siêu thị, các kỹ sư ưu tiên lắp đặt cảm biến dừng khẩn cấp khi phát hiện người đi vào vùng nguy hiểm nhằm đảm bảo an toàn lao động. Việc ưu tiên này phản ánh quan điểm nào?","o":["Con người là mục tiêu tối cao của mọi quá trình phát triển khoa học - kỹ thuật, công nghệ phải phục vụ an toàn của con người.","Con người là tài sản quý nhất nên ưu tiên phát triển khoa học - kỹ thuật, công nghệ phải phục con người.","Con người đã có năng lự đoán trước được rủi do trong sản xuất sẽ tiết kiệm chi phí, bảo vệ tài sản cho nhà trường.","Hạn chế tới mức tối đa những sự cố trong sản xuất để đảm bảo quá trình sản xuất diễn ra liên tục, đây là công nghệ cần cho loài người."],"a":0},{"lv":3,"id":"c3-246","ch":3,"n":246,"q":"Sinh viên Đại học Kỹ thuật Công nghiệp không chỉ nỗ lực rèn luyện tay nghề chuyên môn cao để thiết kế các máy móc tinh xảo mà còn hăng hái học tập đạo đức cách mạng, rèn luyện nếp sống văn minh thượng tôn pháp luật. Sự kết hợp này phản ánh yêu cầu nào sau đây?","o":["Yêu cầu xây dựng con người Việt Nam phát triển toàn diện cả đạo đức và tài năng.","Yêu cầu xây dựng một lực lượng lao động tuyệt đối trung thành với Đảng.","Yêu cầu luôn sẵn sàng chiến đấu chống giặc ngoại xâm có thể đến bất cứ lúc nào.","Yêu cầu được thống nhất trong nghị quyết của Đảng."],"a":0},{"lv":3,"id":"c3-247","ch":3,"n":247,"q":"Một thành viên của nhóm thiết kế đồ án tốt nghiệp đã chủ động chia sẻ ý tưởng độc đáo của mình cho cả nhóm cùng bổ sung phản biện để hoàn thiện sản phẩm robot tối ưu nhất tham gia cuộc thi sáng tạo khoa học cấp tỉnh. Hành động này phản ánh đúng đắn sự kết hợp nào?","o":["Sự kết hợp hài hòa biện chứng giữa lợi ích cá nhân sáng tạo với lợi ích tập thể lành mạnh vì sự tiến bộ chung.","Sự kết hợp hài hòa biện chứng giữa tài năng cá nhân sáng tạo sự công nhận của tập thể để phát triển bản thân.","Sự kết hợp hài hòa biện chứng giữa sự độc đáo cá nhân và tính phổ biến của tập thể kết hợp trong một đồ án.","Sự triệt tiêu bớt tính cá nhân bằng sự phản biện mạnh mẽ của tập thể để có một đồ án làm hài lòng tất cả."],"a":0},{"lv":3,"id":"c3-248","ch":3,"n":248,"q":"Trong chiến lược phát triển kinh tế – xã hội (Nâng cao chất lượng giáo dục, y tế và đời sống nhân dân) tỉnh Thái Nguyên đã ưu tiên đẩy mạnh phát triển sản xuất công nghiệp công nghệ cao tại các khu công nghiệp Điềm Thụy, Sông Công. Việc ưu tiên này dựa trên quan điểm biện chứng nào?","o":["Nâng cao chất lượng giáo dục, y tế là một công cuộc khó khăn và lâu dài, nên ưu tiên giải quyết việc làm trước.","Tỉnh tranh thủ làn sóng FDI đang đổ về Việt Nam, cần có chính sách thu hút đầu tư kịp thời.","Lao động sản xuất vật chất là phương thức tồn tại cơ bản nhất của con người, tạo ra cơ sở vật chất quyết định sự phát triển của các hoạt động tinh thần khác.","Sự biện chứng giữa nghị quyết của Đảng bộ Tỉnh và chính sách của Chính quyền Tỉnh."],"a":2},{"lv":3,"id":"c3-249","ch":3,"n":249,"q":"Vận dụng lý luận của chủ nghĩa duy vật lịch sử về con người, anh (chị) hãy lựa chọn đáp án đúng nhất mục tiêu phát triển con người ở Việt Nam trong giai đoạn hiện nay?","o":["Phát triển thể chất con người.","Phát triển con người toàn diện.","Phát triển con người đạo đức.","Phát triển con người văn hóa."],"a":1},{"lv":3,"id":"c3-250","ch":3,"n":250,"q":"Trong tư tưởng truyền thống Việt Nam, vấn đề nào về con người được quan tâm nhiều nhất là:","o":["Bản chất con người.","Trí tuệ của con người.","Đạo lý làm người.","Sức mạnh chinh phục tự nhiên của con người."],"a":2},{"lv":3,"id":"c3-251","ch":3,"n":251,"q":"Vận dụng lý luận của chủ nghĩa duy vật lịch sử về con người, anh (chị) hãy cho biết: Tệ sung bái cá nhân trong xã hội là tuyệt đối hóa vai trò của:","o":["Lãnh tụ","Quần chúng nhân dân","Giai cấp thống trị","Tất cả các đáp án"],"a":0},{"lv":3,"id":"c3-252","ch":3,"n":252,"q":"Vận dụng lý luận của chủ nghĩa duy vật lịch sử về con người, anh (chị) hãy cho biết: Anh hùng tạo thời thế và thời thế tạo anh hùng, đúng hay sai?","o":["Sai. Vì khẳng định như vậy là tuyệt đối hóa vai trò của cá nhân, vĩ nhân.","Đúng. Vì giải thích từ luận điểm con người là vừa là chủ thể lịch sử và vừa là sản phẩm của hoàn cảnh, lịch sử.","Sai. Vì tuyệt đối hóa vai trò của quần chúng nhân dân.","Đúng. Vì tuyệt đối hóa vai trò của lãnh tụ."],"a":1},{"lv":3,"id":"c3-253","ch":3,"n":253,"q":"Nội dung bài thơ sau của Chủ tịch Hồ Chí Minh đề cập đến nội dung nào về con người theo quan điểm của triết học Mác – Lênin? “Ngủ thì ai cũng như lương thiện Tỉnh dạy phân ra kẻ dữ hiền. Hiền, dữ phải đâu là tính sẵn Phần nhiều do giáo dục mà nên”.","o":["Bản tính con người là do định sẵn.","Bản tính con người là tổng hòa các quan hệ xã hội.","Bản tính con người đều giống nhau.","Bản chất con người là lương thiện"],"a":1},{"lv":3,"id":"c3-254","ch":3,"n":254,"q":"Vận dụng sáng tạo lý luận của chủ nghĩa duy vật lịch sử, Chủ tịch Hồ Chí Minh và Đảng Cộng sản Việt Nam đã xác định: con người có mối quan hệ như thế nào với cách mạng Việt Nam?","o":["Là mục tiêu của Cách mạng.","Vừa là mục tiêu, vừa là động lực của cách mạng.","Là động lực của Cách mạng.","Là lượng lượng nòng cốt của Cách mạng."],"a":1},{"lv":4,"id":"c3-255","ch":3,"n":255,"q":"Phân tích nào đúng nhất về nguyên nhân làm cho lao động trở thành hành vi riêng có, quyết định sự khác biệt bản chất giữa con người và con vật?","o":["Do con người có đời sống tâm lý, ý thức và đời sống tâm linh phong phú hơn loài vật.","Do con người biết chế tạo và sử dụng công cụ lao động tác động vào tự nhiên để cải tạo nó, phục vụ nhu cầu của mình.","Do tổ chức cơ thể sinh học của con người tiến hóa hơn hẳn các động vật cấp cao khác.","Do con người có bản năng sinh tồn vượt trội giúp chiếm đoạt hiệu quả các sản phẩm sẵn có trong tự nhiên."],"a":1},{"lv":4,"id":"c3-256","ch":3,"n":256,"q":"Điều gì phản ánh bản chất của con người vừa là sản phẩm của lịch sử, vừa là chủ thể của lịch sử?","o":["Con người hoàn toàn bị động chịu sự quy định tuyệt đối của lịch sử và không thể cải biến hoàn cảnh.","Con người tiếp tục hoạt động trên tiền đề cũ của thế hệ trước để lại, đồng thời tiến hành hoạt động mới để cải biến điều kiện cũ và sáng tạo ra lịch sử.","Con người tự do sáng tạo ra lịch sử theo ý muốn chủ quan tùy tiện mà không phụ thuộc vào tiền đề quá khứ.","Lịch sử xã hội vận động theo một kịch bản an bài sẵn, con người chỉ đóng vai trò diễn viên đóng lại kịch bản đó."],"a":1},{"lv":4,"id":"c3-257","ch":3,"n":257,"q":"Nhận định nào dưới đây KHÔNG làm rõ đúng mối quan hệ giữa sự phát triển của cách mạng khoa học - công nghệ hiện đại với hiện tượng tha hóa lao động trong chủ nghĩa tư bản?","o":["Sản xuất và công nghệ càng phát triển thì người lao động càng dễ bị máy móc thay thế.","Người công nhân trở thành một bộ phận của máy móc và ngày càng phụ thuộc vào nó.","Sự phát triển khoa học - công nghệ trong chế độ tư hữu tư bản tự động xóa bỏ hoàn toàn sự tha hóa lao động.","Khoa học - công nghệ phát triển làm cho sự phân cực giàu nghèo trong xã hội hiện đại dãn rộng theo chiều tỷ lệ thuận."],"a":2},{"lv":4,"id":"c3-258","ch":3,"n":258,"q":"Nội dung có ý nghĩa then chốt nhất trong tư tưởng giải phóng con người của chủ nghĩa Mác - Lênin là gì?","o":["Giải thoát con người khỏi cuộc sống tạm để lên cõi Niết bàn hoặc Thiên đường.","Sử dụng thuần túy các điều chỉnh đạo đức và pháp luật duy tâm để cải tạo tâm lý con người.","Khắc phục sự tha hóa của con người và của lao động, biến lao động sáng tạo trở thành chức năng thực sự của con người.","Duy trì chế độ tư hữu tư bản chủ nghĩa nhưng tăng tiền công cho người lao động."],"a":2},{"lv":4,"id":"c3-259","ch":3,"n":259,"q":"Mối quan hệ giữa tính giai cấp, tính dân tộc và tính nhân loại trong mỗi con người được triết học Mác - Lênin phân tích như thế nào về mặt lịch sử?","o":["Tính giai cấp và tính dân tộc là vĩnh hằng; tính nhân loại chỉ là tạm thời.","Tính giai cấp và tính dân tộc mang tính lịch sử (sẽ mất dần theo sự phát triển xã hội); tính nhân loại và cá nhân là vĩnh viễn.","Cả tính giai cấp, tính dân tộc và tính nhân loại đều là những phạm trù vĩnh hằng không bao giờ thay đổi.","Tính nhân loại hoàn toàn đối lập và loại trừ tuyệt đối tính giai cấp trong mọi hoàn cảnh."],"a":1},{"lv":4,"id":"c3-260","ch":3,"n":260,"q":"Yếu tố nào quyết định trực tiếp vai trò là động lực phát triển lịch sử của quần chúng nhân dân trong phương thức sản xuất?","o":["Quần chúng nhân dân là lực lượng tiêu dùng chủ yếu các sản phẩm tự nhiên.","Quần chúng nhân dân lao động là yếu tố căn bản, động nhất, cách mạng nhất trong lực lượng sản xuất.","Quần chúng nhân dân luôn thụ động tuân theo các mệnh lệnh kiến trúc thượng tầng.","Quần chúng nhân dân chỉ tham gia vào các hoạt động sáng tạo nghệ thuật thuần túy."],"a":1},{"lv":5,"id":"c3-261","ch":3,"n":261,"q":"Quan điểm nào nên được lựa chọn khi giải thích mối quan hệ biện chứng giữa con người với tư cách là sản phẩm của lịch sử và chủ thể của lịch sử?","o":["Con người hoàn toàn chủ động sáng tạo lịch sử theo ý muốn chủ quan, không bị giới hạn bởi các tiền đề quá khứ.","Lịch sử quyết định hoàn toàn con người, con người chỉ là sản phẩm thụ động không có khả năng cải biến hoàn cảnh.","Con người bị quy định bởi điều kiện lịch sử do thế hệ trước để lại, nhưng thông qua thực tiễn lại chủ động cải biến điều kiện đó và tạo ra lịch sử mới.","Vai trò chủ thể lịch sử chỉ thuộc về các cá nhân kiệt xuất, quần chúng nhân dân chỉ là sản phẩm thụ động của lịch sử."],"a":2},{"lv":5,"id":"c3-262","ch":3,"n":262,"q":"Chính sách xã hội nào nên được ưu tiên để giải quyết hài hòa mối quan hệ giữa cá nhân và xã hội trong giai đoạn hiện nay?","o":["Tuyệt đối hóa lợi ích xã hội, sẵn sàng triệt tiêu các lợi ích cá nhân chính đáng.","Đề cao chủ nghĩa cá nhân cực đoan, lấy sự thỏa mãn của cá nhân làm thước đo duy nhất.","Kết hợp chặt chẽ giữa lợi ích cá nhân và lợi ích xã hội, tôn trọng sự phát triển riêng biệt của cá nhân trong sự thống nhất với lợi ích chung.","Buộc tất cả các cá nhân phải có suy nghĩ và hành động giống hệt nhau, xóa bỏ tính đơn nhất của cá thể."],"a":2},{"lv":5,"id":"c3-263","ch":3,"n":263,"q":"Phương án nào phù hợp nhất khi đánh giá về bản chất của hiện tượng tha hóa lao động trong xã hội tư bản?","o":["Là một hiện tượng tự nhiên tất yếu, xuất hiện do sự lười biếng bẩm sinh của người lao động.","Là tình trạng sản phẩm lao động và chính hoạt động lao động bị biến thành một lực lượng đối lập, thống trị lại người lao động.","Là quá trình người lao động tự nguyện dâng nộp thành quả lao động của mình cho xã hội mà không đòi hỏi đền bù.","Là hậu quả trực tiếp của việc con người phát minh ra ngôn ngữ và tư duy trừu tượng."],"a":1},{"lv":5,"id":"c3-264","ch":3,"n":264,"q":"Phương pháp luận nào nên được áp dụng để đánh giá một cách toàn diện và chính xác giá trị của một con người cụ thể?","o":["Đánh giá dựa trên nguồn gốc xuất thân gia đình và địa vị xã hội truyền thống.","Đánh giá dựa trên mức độ cống hiến thực tiễn của họ đối với sự tiến bộ xã hội và sự phát triển của cộng đồng.","Đánh giá dựa trên những lời hứa hẹn và tuyên bố lý tưởng suông của cá nhân đó.","Đánh giá dựa trên tài sản vật chất và khối lượng tư liệu sản xuất mà họ sở hữu."],"a":1},{"lv":6,"id":"c3-265","ch":3,"n":265,"q":"Nếu phải đề xuất một dự án phát triển cộng đồng do sinh viên TNUT làm nòng cốt nhằm thể hiện tính nhân loại và trách nhiệm xã hội, dự án nào dưới đây là tối ưu nhất?","o":["Dự án thiết kế và chế tạo hệ thống lọc nước giá rẻ, sử dụng năng lượng mặt trời cho các điểm trường vùng sâu vùng xa.","Dự án kinh doanh linh kiện điện tử trôi nổi không rõ nguồn gốc để thu lợi nhuận cá nhân nhanh nhất.","Dự án tổ chức các giải đấu game online nội bộ chỉ dành riêng cho sinh viên kỹ thuật.","Dự án viết phần mềm tự động tăng tương tác ảo trên các nền tảng mạng xã hội."],"a":0}];
